float4 SimpleBlur(sampler2D InputTex, float2 Coord, float2 pixelsize)
{
    float4 Blur = 0.0;

    static const float2 Offsets[4]=
    {
        float2(1.0, 1.0),
        float2(1.0, -1.0),
        float2(-1.0, 1.0),
        float2(-1.0, -1.0)
    };

    for (int i = 0; i < 4; i++)
    {
        Blur += tex2D(InputTex, Coord + Offsets[i] * pixelsize);
    }

    return Blur * 0.25;
}

