float2 BD(float2 p, float k1) //Polynomial Lens
{
	if(!CA_Type == 1)
		discard;
	p *= 0.5 + 0.5;//Center
	// Normalize the u,v coordinates in the range [-1;+1]
	p = (2.0f * p - 1.0f) / 1.0f;
	// Calculate l2 norm
	float r2 = p.x*p.x + p.y*p.y;
	float r4 = pow(r2,2);
	// Forward transform
	float x2 = p.x * (1.0 + k1 * r2);
	float y2 = p.y * (1.0 + k1 * r2);
	// De-normalize to the original range
	p.x = (x2 + 1.0) * 1.0 / 2.0;
	p.y = (y2 + 1.0) * 1.0 / 2.0;

return p;
}

