float2 VP(float2 texcoord, float k1)
{
	if(!CA_Type == 4)
		discard;
    float X = 1;
    float Y = k1;
    float midW = (X - 1)*(BUFFER_WIDTH*0.5)*pix.x;
    float midH = (Y - 1)*(BUFFER_HEIGHT*0.5)*pix.y;

