		uv_red = HVP(texcoord.xy,1-K1_Red * 0.025);
		uv_green = HVP(texcoord.xy,1-K1_Green * 0.025);
		uv_blue = HVP(texcoord.xy,1-K1_Blue * 0.025);
	}
	else if(CA_Type == 3)
