	if(View_Mode == 0)
	{
		NFAA = lerp(NFAA,GetBB( texcoord.xy), Mask );
	}
	else if(View_Mode == 1)
	{
		NFAA = Mask;
	}
	else if (View_Mode == 2)
	{
		NFAA = float3(-float2(-(r - l),-(t - s)) * 0.5 + 0.5,1);
	}

return NFAA;
}

