	r4 = tex2D(s0, r4.zw);
	r4.xyz = (r1.zzzz * r4).xyz;
	r4.xyz = (r4 * c3.zzzz).xyz;
	r5.xyz = (r5 * c3.zzzz).xyz;
	r5.xyz = (r1.zzzz * r5).xyz;
