	r2.xyz = (r0.wwww * r2).xyz;
	r0.x = pow(2, r0.x);
	r0.y = pow(2, r0.y);
	r2.xyz = (r2 * r0.xxxx + r3).xyz;
	r3 = tex2D(s0, r7.xy);
	r5 = tex2D(s0, r7.zw);
	r5.xyz = (r2.wwww * r5).xyz;
	r3.xyz = (r0.zzzz * r3).xyz;
	r3.xyz = (r3 * c3.zzzz + r4).xyz;
	r3.xyz = (r5 * c3.zzzz + r3).xyz;
	r0.xzw = (r0.wwww * r3.xyyz).xzw;
	r0.xyz = (r0.xzww * r0.yyyy + r2).xyz;
