> = float3(0.5, 0.0, 0.0);

uniform float fUIColorTempScaling <
	ui_type = "drag";
	ui_category = UI_CATEGORY_CURVES;
	ui_label = "Color Temperature Scaling";
	ui_tooltip = UI_TOOLTIP_DEBUG;
