			else
				return 1;
		}
		else
			return float4(0.25,0.5,0.9,1.0);
	}
	else
		return 0;
	*/
	if ((TexCoords.x > 0.54 || TexCoords.x < 0.46 || TexCoords.y > 0.545 || TexCoords.y < 0.455) || !Debug_Mode)
		return float4(color.rgb,1.0);
	else
