		{if (TC_B.x > 0.52 || TC_B.x < 0.48 || TC_B.y > 0.530 || TC_B.y < 0.47)
			return 1;
		else
			return float4(0.25,0.5,0.9,1.0);
		}
		else
			return 0;
	}

}


