< ui_tooltip = "Move this either before or after the VR shader depending on what you think looks better .\n"
			   "             This only shows in HelixVision Mode."; >
{
	pass USMOut
	{
		VertexShader = PostProcessVS;
		PixelShader = SmartSharp;
	}
}
