DepthAlpha.fx:
//#region Preprocessor

#include "ReShade.fxh"
#include "ReShadeUI.fxh"
#include "FXShaders/Common.fxh"
#include "FXShaders/KeyCodes.fxh"

#ifndef DEPTH_APLHA_SCREENSHOT_KEY
#define DEPTH_APLHA_SCREENSHOT_KEY VK_SNAPSHOT
#endif

//#endregion

//#region Uniforms

FXSHADERS_HELP(
	"This effect allows you to overwrite the transparency of screenshots using "
	"the scene depth as the alpha channel.\n"
	"\n"
	"You'll need a version of ReShade with the option to disable "
	"\"Clear Alpha Channel\" in the screenshot settings.\n"
	"\n"
	"If you use a different key for taking screenshots, it may be useful to "
	"change the value of DEPTH_ALPHA_SCREENSHOT_KEY to something other than "
	"VK_SNAPSHOT (the keycode for the printscreen key).\n"
	"\n"
	"To see which keycodes are available, refer to the \"KeyCodes.fxh\" file "
	"in the FXShaders repository shaders folder."
);

uniform float2 DepthRange
<
	__UNIFORM_DRAG_FLOAT2

	ui_label = "Range";
	ui_tooltip =
		"Defines the depth range for the depth multipliers.\n"
		" - The first value defines the start of the middle depth."
		" - The second value defines the end of the middle depth and the start "
		"of the far depth."
		"\nDefault: 0.0 1.0";
	ui_category = "Depth";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = float2(0.0, 1.0);

uniform float3 DepthMultiplier
<
	__UNIFORM_DRAG_FLOAT3

	ui_category = "Features";
	ui_label = "Depth Multiplier";
	ui_tooltip =
		"Multipliers for the transparency of near, middle and far depth "
		"respectively.\n"
		"Set to 0.0 to make a range completely transparent, 1.0 to make it "
		"completely opaque.\n"
		"\nDefault: 1.0 0.5 0.0";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = float3(1.0, 0.5, 0.0);

uniform float DepthSmoothness
<
	__UNIFORM_DRAG_FLOAT1

	ui_category = "Features";
	ui_label = "Depth Smoothness";
	ui_tooltip =
		"Smoothness of the transitions between depth multiplier ranges.\n"
		"\nDefault: 1.0";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = 1.0;

uniform bool ClearPreviousAlpha
<
	ui_category = "Features";
	ui_label = "Clear Previous Alpha";
	ui_tooltip =
		"Determines whether the effect should reset the alpha of the image to"
		"100% opaque before applying the effect or maintain it (applying the "
		"effect over the previous alpha).\n"
		"\nDefault: Off";
> = true;

uniform bool ColorizeTransparency
<
	ui_category = "Debug";
	ui_label = "Colorize Transparency";
	ui_tooltip =
		"Preview transparency by colorizing it.\n"
		"This option is automatically disabled when the key defined in "
		"DEPTH_ALPHA_SCREEENSHOT_KEY is being held down, which is the "
		"printscreen key by default.\n"
		"There's a small chance that the test color might still appear in the "
		"screenshot, but keeping the screenshot key held for a small time "
		"seems to help.\n"
		"You can also simply disable this option before taking a screenshot.\n"
		"\nDefault: Off";
> = false;

uniform float4 TestColor
<
	__UNIFORM_COLOR_FLOAT4

	ui_category = "Debug";
	ui_label = "Transparency Test Color";
	ui_tooltip =
		"The color used when Colorize Transparency is enabled.\n"
		"The alpha channel of this color has nothing to do with the final "
		"result, it merely serves to determine the opacity of this color while "
		"testing.\n"
		"\nDefault: 0 0 0 255";
> = float4(0.0, 0.0, 0.0, 1.0);

uniform bool IsScreenshotKeyDown
<
	source = "key";
	keycode = DEPTH_APLHA_SCREENSHOT_KEY;
>;

//#endregion

//#region Functions

void ApplyDepthToAlpha(inout float alpha, float depth)
{
	// if (DepthCurve.x < DepthCurve.y)
	// 	depth = smoothstep(DepthCurve.x, DepthCurve.y, 1.0 - depth);
	// else
	// 	depth = smoothstep(DepthCurve.y, DepthCurve.x, depth);

	float is_near = smoothstep(
		depth - DepthSmoothness,
		depth + DepthSmoothness,
		DepthRange.x);

	float is_far = smoothstep(
		DepthRange.y - DepthSmoothness,
		DepthRange.y + DepthSmoothness, depth);

	float is_middle = (1.0 - is_near) * (1.0 - is_far);

	alpha *= lerp(1.0, DepthMultiplier.x, is_near);
	alpha *= lerp(1.0, DepthMultiplier.y, is_middle);
	alpha *= lerp(1.0, DepthMultiplier.z, is_far);
}

//#endregion

//#region Shaders

float4 MainPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float4 color = tex2D(ReShade::BackBuffer, uv);
	color.a = ClearPreviousAlpha ? 1.0 : color.a;

	float depth = ReShade::GetLinearizedDepth(uv);
	ApplyDepthToAlpha(color.a, depth);

	if (!IsScreenshotKeyDown && ColorizeTransparency)
		color.rgb = lerp(
			lerp(color.rgb, TestColor.rgb, TestColor.a),
			color.rgb,
			color.a);

	return color;
}

//#endregion

//#region Technique

technique DepthAlpha
<
	ui_tooltip =
		"Effect that uses depth as transparency to allow for screenshots with "
		"transparency, like a chroma-key.";
>
{
	pass
	{
		VertexShader = PostProcessVS;
		PixelShader = MainPS;
	}
}

//#endregion

DepthHaze.fx:
///////////////////////////////////////////////////////////////////
// This effect works like a one-side DoF for distance haze, which slightly
// blurs far away elements. A normal DoF has a focus point and blurs using
// two planes. 
//
// It works by first blurring the screen buffer using 2-pass block blur and
// then blending the blurred result into the screen buffer based on depth
// it uses depth-difference for extra weight in the blur method so edges
// of high-contrasting lines with high depth diffence don't bleed.
///////////////////////////////////////////////////////////////////
// By Otis / Infuse Project
///////////////////////////////////////////////////////////////////

#include "ReShadeUI.fxh"

uniform float EffectStrength < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.0; ui_max=1.0;
	ui_tooltip = "The strength of the effect. Range from 0.0, which means no effect, till 1.0 which means pixels are 100% blurred based on depth.";
> = 0.9;
uniform float3 FogColor < __UNIFORM_COLOR_FLOAT3
	ui_tooltip = "Color of the fog, in (red , green, blue)";
> = float3(0.8,0.8,0.8);
uniform float FogStart < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.0; ui_max=1.0;
	ui_tooltip = "Start of the fog. 0.0 is at the camera, 1.0 is at the horizon, 0.5 is halfway towards the horizon. Before this point no fog will appear.";
> = 0.2;
uniform float FogFactor < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.0; ui_max=1.0;
	ui_tooltip = "The amount of fog added to the scene. 0.0 is no fog, 1.0 is the strongest fog possible.";
> = 0.2;

#include "ReShade.fxh"

//////////////////////////////////////
// textures
//////////////////////////////////////
texture   Otis_FragmentBuffer1 	{ Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; Format = RGBA8;};	
texture   Otis_FragmentBuffer2 	< pooled = true; > { Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; Format = RGBA8;};	

//////////////////////////////////////
// samplers
//////////////////////////////////////
sampler2D Otis_SamplerFragmentBuffer2 { Texture = Otis_FragmentBuffer2; };
sampler2D Otis_SamplerFragmentBuffer1 {	Texture = Otis_FragmentBuffer1; };

//////////////////////////////////////
// code
//////////////////////////////////////
float CalculateWeight(float distanceFromSource, float sourceDepth, float neighborDepth)
{
	return (1.0 - abs(sourceDepth - neighborDepth)) * (1/distanceFromSource) * neighborDepth;
}

void PS_Otis_DEH_BlockBlurHorizontal(in float4 pos : SV_Position, in float2 texcoord : TEXCOORD, out float4 outFragment : SV_Target0)
{
	float4 color = tex2D(ReShade::BackBuffer, texcoord);
	float colorDepth = ReShade::GetLinearizedDepth(texcoord).r;
	float n = 1.0f;

	[loop]
	for(float i = 1; i < 5; ++i) 
	{
		float2 sourceCoords = texcoord + float2(i * BUFFER_PIXEL_SIZE.x, 0.0);
		float weight = CalculateWeight(i, colorDepth, ReShade::GetLinearizedDepth(sourceCoords).r);
		color += (tex2D(ReShade::BackBuffer, sourceCoords) * weight);
		n+=weight;

		sourceCoords = texcoord - float2(i * BUFFER_PIXEL_SIZE.x, 0.0);
		weight = CalculateWeight(i, colorDepth, ReShade::GetLinearizedDepth(sourceCoords).r);
		color += (tex2D(ReShade::BackBuffer, sourceCoords) * weight);
		n+=weight;
	}
	outFragment = color/n;
}

void PS_Otis_DEH_BlockBlurVertical(in float4 pos : SV_Position, in float2 texcoord : TEXCOORD, out float4 outFragment : SV_Target0)
{
	float4 color = tex2D(Otis_SamplerFragmentBuffer1, texcoord);
	float colorDepth = ReShade::GetLinearizedDepth(texcoord).r;
	float n=1.0f;

	[loop]
	for(float j = 1; j < 5; ++j) 
	{
		float2 sourceCoords = texcoord + float2(0.0, j * BUFFER_PIXEL_SIZE.y);
		float weight = CalculateWeight(j, colorDepth, ReShade::GetLinearizedDepth(sourceCoords).r);
		color += (tex2D(Otis_SamplerFragmentBuffer1, sourceCoords) * weight);
		n+=weight;

		sourceCoords = texcoord - float2(0.0, j * BUFFER_PIXEL_SIZE.y);
		weight = CalculateWeight(j, colorDepth, ReShade::GetLinearizedDepth(sourceCoords).r);
		color += (tex2D(Otis_SamplerFragmentBuffer1, sourceCoords) * weight);
		n+=weight;
	}
	outFragment = color/n;
}

void PS_Otis_DEH_BlendBlurWithNormalBuffer(float4 vpos: SV_Position, float2 texcoord: TEXCOORD, out float4 fragment: SV_Target0)
{
	float depth = ReShade::GetLinearizedDepth(texcoord).r;
	float4 blendedFragment = lerp(tex2D(ReShade::BackBuffer, texcoord), tex2D(Otis_SamplerFragmentBuffer2, texcoord), clamp(depth  * EffectStrength, 0.0, 1.0)); 
	float yFactor = clamp(texcoord.y > 0.5 ? 1-((texcoord.y-0.5)*2.0) : texcoord.y * 2.0, 0, 1);
	fragment = lerp(blendedFragment, float4(FogColor, blendedFragment.r), clamp((depth-FogStart) * yFactor * FogFactor, 0.0, 1.0));
}

technique DepthHaze
{
	// 3 passes. First 2 passes blur screenbuffer into Otis_FragmentBuffer2 using 2 pass block blur with 10 samples each (so 2 passes needed)
	// 3rd pass blends blurred fragments based on depth with screenbuffer.
	pass Otis_DEH_Pass0
	{
		VertexShader = PostProcessVS;
		PixelShader = PS_Otis_DEH_BlockBlurHorizontal;
		RenderTarget = Otis_FragmentBuffer1;
	}

	pass Otis_DEH_Pass1
	{
		VertexShader = PostProcessVS;
		PixelShader = PS_Otis_DEH_BlockBlurVertical;
		RenderTarget = Otis_FragmentBuffer2;
	}

	pass Otis_DEH_Pass2
	{
		VertexShader = PostProcessVS;
		PixelShader = PS_Otis_DEH_BlendBlurWithNormalBuffer;
	}
}

