#pragma once

#define FXSHADERS_ASPECT_RATIO_SCALE_TYPE_LIST \
"Cover\0" \
"Fit\0" \
"Stretch\0"

namespace FXShaders { namespace AspectRatio
{

namespace ScaleType
{
	static const int Cover = 0;
	static const int Fit = 1;
	static const int Stretch = 2;
}

float2 CoverScale(float2 uv)
{
	return BUFFER_WIDTH > BUFFER_HEIGHT
		? float2(1.0, BUFFER_HEIGHT * BUFFER_RCP_WIDTH)
		: float2(BUFFER_WIDTH * BUFFER_RCP_HEIGHT, 1.0);
}

float2 FitScale(float2 uv)
{
	return BUFFER_WIDTH > BUFFER_HEIGHT
		? float2(BUFFER_WIDTH * BUFFER_RCP_HEIGHT, 1.0)
		: float2(1.0, BUFFER_HEIGHT * BUFFER_RCP_WIDTH);
}

float2 ApplyScale(int type, float2 uv)
{
	switch (type)
	{
		case ScaleType::Cover:
			return CoverScale(uv);
		case ScaleType::Fit:
			return FitScale(uv);
		// case ScaleType::Stretch:
		default:
			return uv;
	}
}

}} // Namespace.

FXShaders/Blending.fxh:
#pragma once

namespace FXShaders
{

/**
 * Standard screen blend mode.
 *
 * @param a The original color, normalized.
 * @param b The color to blend with the original color, normalized.
 * @param w How much to blend with the original color.
 *          If set to 0.0 the result will be the original color left intact.
 */
float3 BlendScreen(float3 a, float3 b, float w)
{
	return 1.0 - (1.0 - a) * (1.0 - b * w);
}

/**
 * Standard overlay blend mode.
 *
 * @param a The original color, normalized.
 * @param b The color to blend with the original color, normalized.
 * @param w How much to blend with the original color.
 *          If set to 0.0 the result will be the original color left intact.
 */
float3 BlendOverlay(float3 a, float3 b, float w)
{
	float3 color = (a < 0.5)
		? 2.0 * a * b
		: 1.0 - 2.0 * (1.0 - a) * (1.0 - b);

	return lerp(a, color, w);
}

/**
 * Standard soft light blend mode.
 *
 * @param a The original color, normalized.
 * @param b The color to blend with the original color, normalized.
 * @param w How much to blend with the original color.
 *          If set to 0.0 the result will be the original color left intact.
 */
float3 BlendSoftLight(float3 a, float3 b, float w)
{
	float3 color = (1.0 - 2.0 * b) * (a * a) + 2.0 * b * a;

	return lerp(a, color, w);
}

/**
 * Standard hard light blend mode.
 *
 * @param a The original color, normalized.
 * @param b The color to blend with the original color, normalized.
 * @param w How much to blend with the original color.
 *          If set to 0.0 the result will be the original color left intact.
 */
float3 BlendHardLight(float3 a, float3 b, float w)
{
	float3 color = (a > 0.5)
		? 2.0 * a * b
		: 1.0 - 2.0 * (1.0 - a) * (1.0 - b);

	return lerp(a, color, w);
}

}

