/*
	Flashlight shader by luluco250

	MIT Licensed.
*/

#include "ReShade.fxh"

#ifndef FLASHLIGHT_NO_DEPTH
#define FLASHLIGHT_NO_DEPTH 0
#endif

#ifndef FLASHLIGHT_NO_TEXTURE
#define FLASHLIGHT_NO_TEXTURE 0
#endif

#ifndef FLASHLIGHT_NO_BLEND_FIX
#define FLASHLIGHT_NO_BLEND_FIX 0
#endif

uniform float uBrightness <
	ui_label = "Brightness";
	ui_tooltip =
		"Flashlight halo brightness.\n"
		"\nDefault: 10.0";
	ui_type = "drag";
	ui_min = 0.0;
	ui_max = 100.0;
	ui_step = 0.01;
> = 10.0;

uniform float uSize <
	ui_label = "Size";
	ui_tooltip =
		"Flashlight halo size in pixels.\n"
		"\nDefault: 420.0";
	ui_type = "drag";
	ui_min = 10.0;
	ui_max = 1000.0;
	ui_step = 1.0;
> = 420.0;

uniform float3 uColor <
	ui_label = "Color";
	ui_tooltip =
		"Flashlight halo color.\n"
		"\nDefault: R:255 G:230 B:200";
	ui_type = "color";
> = float3(255, 230, 200) / 255.0;

#if !FLASHLIGHT_NO_DEPTH
uniform float uDistance <
	ui_label = "Distance";
	ui_tooltip =
		"The distance that the flashlight can illuminate.\n"
		"Only works if the game has depth buffer access.\n"
		"\nDefault: 0.1";
	ui_type = "drag";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = 0.1;
#endif

sampler2D sColor {
	Texture = ReShade::BackBufferTex;
	SRGBTexture = true;
	MinFilter = POINT;
	MagFilter = POINT;
};

#define nsin(x) (sin(x) * 0.5 + 0.5)

float4 PS_Flashlight(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET {
	float2 res = ReShade::ScreenSize;
	float2 coord = uv * res;

	float halo = distance(coord, res * 0.5);
	float flashlight = uSize - min(halo, uSize);
	flashlight /= uSize;

	#if !FLASHLIGHT_NO_TEXTURE
	// Add some texture to the halo by using some sin lines + reduce intensity
	// when nearing the center of the halo.
	float defects = sin(flashlight * 30.0) * 0.5 + 0.5;
	defects = lerp(defects, 1.0, flashlight * 2.0);

	static const float contrast = 0.125;

	defects = 0.5 * (1.0 - contrast) + defects * contrast;
	flashlight *= defects * 4.0;
	#else
	flashlight *= 2.0;
	#endif

	#if !FLASHLIGHT_NO_DEPTH
	float depth = 1.0 - ReShade::GetLinearizedDepth(uv);
	depth = pow(abs(depth), 1.0 / uDistance);
	flashlight *= depth;
	#endif

	float3 colored_flashlight = flashlight * uColor;
	colored_flashlight *= colored_flashlight * colored_flashlight;

	float3 result = 1.0 + colored_flashlight * uBrightness;

	float3 color = tex2D(sColor, uv).rgb;
	color *= result;

	#if !FLASHLIGHT_NO_BLEND_FIX

	// Add some minimum amount of light to very dark pixels.	
	color = max(color, (result - 1.0) * 0.001);

	#endif

	return float4(color, 1.0);
}

technique Flashlight {
	pass {
		VertexShader = PostProcessVS;
		PixelShader = PS_Flashlight;
		SRGBWriteEnable = true;
	}
}

FlexibleCA.fx:
//#region Preprocessor

#include "ReShade.fxh"
#include "ReShadeUI.fxh"

//#endregion

//#region Uniforms

uniform int Mode
<
	__UNIFORM_COMBO_INT1

	ui_text =
		"How to use:\n"
		"\n"
		"First, choose what kind of chromatic aberration you wish to use by "
		"setting the Mode. Check it's description for details.\n"
		"\n"
		"Secondly, define the Ratio. This controls the chromatic aberration's "
		"\"colors\".\n"
		"\n"
		"Finally, set how large the chromatic aberration will be by setting "
		"the Multiplier.\n"
		" ";
	ui_tooltip =
		"Mode defining how the chromatic aberration is created.\n"
		"\n"
		"  Translate:\n"
		"    Move channels horizontally and vertically.\n"
		"\n"
		"  Scale:\n"
		"    Zoom channels from the center.\n"
		"\n"
		"Default: Scale";
	ui_items = "Translate\0Scale\0";
> = 1;

uniform float3 Ratio
<
	__UNIFORM_SLIDER_FLOAT3

	ui_tooltip =
		"Ratio of how each channel is distorted.\n"
		"The values control the red, green and blue channels respectively.\n"
		"\n"
		"Default: -1.0 0.0 1.0";
	ui_min = -1.0;
	ui_max = 1.0;
> = float3(-1.0, 0.0, 1.0);

uniform float Multiplier
<
	__UNIFORM_SLIDER_FLOAT1

	ui_tooltip =
		"Multiplier of the ratio, defining how much distortion there is.\n"
		"\n"
		"Default: 1.0";
	ui_min = 0.0;
	ui_max = 6.0;
	ui_step = 0.001;
> = 1.0;

//#endregion

//#region Functions

float2 scale_uv(float2 uv, float2 scale, float2 center)
{
	return (uv - center) * scale + center;
}

//#endregion

//#region Shaders

float4 MainPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	const float2 ps = ReShade::PixelSize;

	float2 uv_r = uv;
	float2 uv_g = uv;
	float2 uv_b = uv;

	float3 ratio;

	switch (Mode)
	{
		case 0: // Translate
			ratio = Ratio * Multiplier;

			uv_r += ps * ratio.r;
			uv_g += ps * ratio.g;
			uv_b += ps * ratio.b;
			break;
		case 1: // Scale
			ratio = Multiplier * length(ps) + 1.0;
			ratio = lerp(ratio, 1.0 / ratio, Ratio * 0.5 + 0.5);

			uv_r = scale_uv(uv_r, ratio.r, 0.5);
			uv_g = scale_uv(uv_g, ratio.g, 0.5);
			uv_b = scale_uv(uv_b, ratio.b, 0.5);
			break;
	}

	float3 color = float3(
		tex2D(ReShade::BackBuffer, uv_r).r,
		tex2D(ReShade::BackBuffer, uv_g).g,
		tex2D(ReShade::BackBuffer, uv_b).b);

	return float4(color, 1.0);
}

//#endregion

//#region Technique

technique FlexibleCA
{
	pass
	{
		VertexShader = PostProcessVS;
		PixelShader = MainPS;
	}
}

//#endregion

