//#endregion

//#region Uniforms

uniform float DofScale
<
	__UNIFORM_DRAG_FLOAT1

	ui_label = "Scale";
	ui_tooltip =
		"If this is empty, nag @luluco250 in the ReShade Discord channel.\n"
		"\nDefault: 3.0";
