> = 3.0;

uniform float FocusTime
<
	__UNIFORM_DRAG_FLOAT1

	ui_label = "Time";
	ui_tooltip =
		"If this is empty, nag @luluco250 in the ReShade Discord channel.\n"
		"\nDefault: 350.0";
	ui_category = "Focus";
	ui_min = 0.0;
	ui_max = 2000.0;
	ui_step = 10.0;
> = 350.0;

uniform float2 FocusPoint
<
	__UNIFORM_DRAG_FLOAT2

	ui_label = "Point";
	ui_tooltip =
		"If this is empty, nag @luluco250 in the ReShade Discord channel.\n"
		"\nDefault: 0.5 0.5";
	ui_category = "Focus";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = float2(0.5, 0.5);

uniform float FrameTime <source = "frametime";>;

//#endregion

//#region Textures

#if FOCAL_DOF_USE_SRGB
	sampler BackBuffer
	{
		Texture = ReShade::BackBufferTex;
		SRGBTexture = true;
	};

	#define BACKBUFFER BackBuffer
#else
	#define BACKBUFFER ReShade::BackBuffer
#endif

texture FocalDOF_Focus { Format = R32F; };
sampler Focus { Texture = FocalDOF_Focus; };

texture FocalDOF_LastFocus { Format = R32F; };
sampler LastFocus { Texture = FocalDOF_LastFocus; };

//#endregion

//#region Shaders

void GetFocusVS(
	uint id : SV_VERTEXID,
	out float4 p : SV_POSITION,
	out float2 uv : TEXCOORD0,
	out float focus : TEXCOORD1)
{
	PostProcessVS(id, p, uv);

	#if FOCAL_DOF_USE_TEX2D_IN_VS
		float last = tex2Dfetch(LastFocus, 0).x;
		focus = ReShade::GetLinearizedDepth(FocusPoint);
		focus = lerp(last, focus, FrameTime / FocusTime);
		focus = saturate(focus);
	#else
		focus = 0.0;
	#endif
}

void ReadFocusVS(
	uint id : SV_VERTEXID,
	out float4 p : SV_POSITION,
	out float2 uv : TEXCOORD0,
	out float focus : TEXCOORD1)
{
	PostProcessVS(id, p, uv);

	#if FOCAL_DOF_USE_TEX2D_IN_VS
		focus = tex2Dfetch(Focus, 0).x;
	#else
		focus = 0.0;
	#endif
}

float4 GetFocusPS(
	float4 p : SV_POSITION,
	float2 uv : TEXCOORD0,
	float focus : TEXCOORD1) : SV_TARGET
{
	#if !FOCAL_DOF_USE_TEX2D_IN_VS
		float last = tex2Dfetch(LastFocus, 0).x;
		focus = ReShade::GetLinearizedDepth(FocusPoint);
		focus = lerp(last, focus, FrameTime / FocusTime);
		focus = saturate(focus);
	#endif

	return focus;
}

float4 SaveFocusPS(
	float4 p : SV_POSITION,
	float2 uv : TEXCOORD0,
	float focus : TEXCOORD1) : SV_TARGET
{
	#if !FOCAL_DOF_USE_TEX2D_IN_VS
		focus = tex2Dfetch(Focus, 0).x;
	#endif

	return focus;
}

float4 MainPS(
	float4 p : SV_POSITION,
	float2 uv : TEXCOORD0,
	float focus : TEXCOORD1) : SV_TARGET
{
	float depth = ReShade::GetLinearizedDepth(uv);
	float scale = abs(depth - focus) * DofScale;

	#define FETCH(off) exp(\
		tex2D(BACKBUFFER, uv + ReShade::PixelSize * off * scale))

	static const float2 offsets[] =
	{
		float2(0.0, 1.0),
		float2(0.75, 0.75),
		float2(1.0, 0.0),
		float2(0.75, -0.75),
		float2(0.0, -1.0),
		float2(-0.75, -0.75),
		float2(-1.0, 0.0),
		float2(-0.75, 0.75)
	};

	float4 color = FETCH(0.0);

	[unroll]
	for (int i = 0; i < 8; ++i)
		color += FETCH(offsets[i]);
	color /= 9;

	#undef FETCH

	return log(color);
}

//#endregion

//#region Technique

technique FocalDOF
{
	pass GetFocus
	{
		VertexShader = GetFocusVS;
		PixelShader = GetFocusPS;
		RenderTarget = FocalDOF_Focus;
	}
	pass SaveFocus
	{
		VertexShader = ReadFocusVS;
		PixelShader = SaveFocusPS;
		RenderTarget = FocalDOF_LastFocus;
	}
	pass Main
	{
		VertexShader = ReadFocusVS;
		PixelShader = MainPS;

		#if FOCAL_DOF_USE_SRGB
			SRGBWriteEnable = true;
		#endif
	}
}

//#endregion

FramerateLimiter.fx:
/*
	The world's worst framerate limiter.

	This is an example of how to capture frames at specific time points and use
	them later.
*/

//#region Preprocessor

#include "ReShade.fxh"
#include "ReShadeUI.fxh"

//#endregion

//#region Uniforms

uniform float Framerate
<
	__UNIFORM_SLIDER_FLOAT1

	ui_tooltip = "Default: 30.0";
	ui_min = 1.0;
	ui_max = 144.0;
> = 30.0;

uniform float Timer <source = "timer";>;

//#endregion

//#region Textures

texture LastBackBufferTex { Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; };
sampler LastBackBuffer { Texture = LastBackBufferTex; };

texture LastTimeTex { Format = R32F; };
sampler LastTime { Texture = LastTimeTex; };

texture LastTimeTempTex { Format = R32F; };
sampler LastTimeTemp { Texture = LastTimeTempTex; };

//#endregion

//#region Functions

bool should_write(sampler LastTime)
{
	float last_time = tex2Dfetch(LastTime, 0).x;
	float target = rcp(Framerate) * 1000.0;

	return Timer - last_time > target;
}

//#endregion

//#region Shaders

float4 MainPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	return tex2D(LastBackBuffer, uv);
}

float4 SaveLastBackBufferPS(
	float4 p: SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	if (should_write(LastTime))
		return tex2D(ReShade::BackBuffer, uv);

	discard;
}

float4 CopyLastTimeToTempPS(
	float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	return tex2Dfetch(LastTime, 0);
}

float4 SaveLastTimePS(float4 p: SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	if (should_write(LastTimeTemp))
		return Timer;

	discard;
}

//#endregion

//#region Technique

technique FramerateLimiter
{
	pass SaveLastBackBuffer
	{
		VertexShader = PostProcessVS;
		PixelShader = SaveLastBackBufferPS;
		RenderTarget = LastBackBufferTex;
	}
	pass CopyLastTimeToTemp
	{
		VertexShader = PostProcessVS;
		PixelShader = CopyLastTimeToTempPS;
		RenderTarget = LastTimeTempTex;
	}
	pass SaveLastTime
	{
		VertexShader = PostProcessVS;
		PixelShader = SaveLastTimePS;
		RenderTarget = LastTimeTex;
	}
	pass Main
	{
		VertexShader = PostProcessVS;
		PixelShader = MainPS;
	}
}

//#endregion

