  uniform float3 HUEMagenta < __UNIFORM_COLOR_FLOAT3
      ui_label="Magenta";
      ui_tooltip =
      "Be careful. Do not to push too far!\n"
      "You can only shift as far as the next\n"
      "or previous hue's current value.\n\n"
