//High Pass Sharpening by Ioxa
//Version 1.5 for ReShade 3.0

//Settings

#include "ReShadeUI.fxh"

uniform int HighPassSharpRadius < __UNIFORM_SLIDER_INT1
	ui_min = 1; ui_max = 3;
	ui_tooltip = "1 = 3x3 mask, 2 = 5x5 mask, 3 = 7x7 mask.";
> = 1;

