	you must distribute your contributions under the same license as the original.

	No additional restrictions — You may not apply legal terms or technological measures 
	that legally restrict others from doing anything the license permits.
*/

#include "ReShade.fxh"

//user variables//////////////////////////////////////////////////////////////////////////////////

#include "ReShadeUI.fxh"

uniform float fLightDoF_Width < __UNIFORM_SLIDER_FLOAT1
	ui_label = "Bokeh Width [Light DoF]";
	ui_min = 1.0;
	ui_max = 25.0;
> = 5.0;

uniform float fLightDoF_Amount < __UNIFORM_SLIDER_FLOAT1
	ui_label = "DoF Amount [Light DoF]";
	ui_min = 0.0;
	ui_max = 10.0;
> = 10.0;

uniform bool bLightDoF_UseCA <
	ui_label = "Use Chromatic Aberration [Light DoF]";
	ui_tooltip = "Use color channel shifting.";
> = false;

uniform float2 f2LightDoF_CA < __UNIFORM_SLIDER_FLOAT2
	ui_label = "Chromatic Aberration [Light DoF]";
	ui_tooltip = "Shifts color channels.\nFirst value controls far CA, second controls near CA.";
	ui_min = 0.0;
	ui_max = 1.0;
> = float2(0.0, 1.0);

uniform bool bLightDoF_AutoFocus <
	ui_label = "Use Auto Focus [Light DoF]";
> = true;

uniform float fLightDoF_AutoFocusSpeed <
	ui_label = "Auto Focus Speed [Light DoF]";
	ui_type = "drag";
	ui_min = 0.001;
	ui_max = 1.0;
> = 0.1;

uniform bool bLightDoF_UseMouseFocus <
	ui_label = "Use Mouse for Auto Focus Center [Light DoF]";
	ui_tooltip = "Use the mouse position as the auto focus center";
> = false;

uniform float2 f2Bokeh_AutoFocusCenter < __UNIFORM_SLIDER_FLOAT2
	ui_label = "Auto Focus Center [Light DoF]";
	ui_tooltip = "Target for auto focus.\nFirst value is horizontal: Left<->Right\nSecond value is vertical: Up<->Down";
	ui_min = 0.0;
	ui_max = 1.0;
> = float2(0.5, 0.5);

uniform float fLightDoF_ManualFocus < __UNIFORM_SLIDER_FLOAT1
	ui_label = "Manual Focus [Light DoF]";
	ui_min = 0.0;
	ui_max = 1.0;
> = 0.0;

//system variables////////////////////////////////////////////////////////////////////////////////

//internal variable that holds the current mouse position
uniform float2 f2LightDoF_MouseCoord <source="mousepoint";>;

//textures////////////////////////////////////////////////////////////////////////////////////////

/*
	For those curious...

	Two textures are needed in order to delay focus.
	I just lerp between them by a speed.
*/

//texture for saving the current frame's focus
texture tFocus { Format = R16F; };
//texture for saving the last frame's focus
texture tLastFocus { Format = R16F; };

//samplers////////////////////////////////////////////////////////////////////////////////////////

//sampler for the current frame's focus
sampler sFocus { Texture=tFocus; };
//sampler for the last frame's focus
sampler sLastFocus { Texture=tLastFocus; };

//functions///////////////////////////////////////////////////////////////////////////////////////

//interpret the focus textures and separate far/near focuses
float getFocus(float2 coord, bool farOrNear) {
	float depth = ReShade::GetLinearizedDepth(coord);

	depth -= bLightDoF_AutoFocus ? tex2D(sFocus, 0).x : fLightDoF_ManualFocus;

	if (farOrNear) {
		depth = saturate(-depth * fLightDoF_Amount);
	}
	else {
		depth = saturate(depth * fLightDoF_Amount);
	}

	return depth;
}

//helper function for poisson-disk blur
float2 rot2D(float2 pos, float angle) {
	float2 source = float2(sin(angle), cos(angle));
	return float2(dot(pos, float2(source.y, -source.x)), dot(pos, source));
}

//poisson-disk blur
float3 poisson(sampler sp, float2 uv, float farOrNear, float CA) {
	float2 poisson[12];
	poisson[0]  = float2(-.326,-.406);
	poisson[1]  = float2(-.840,-.074);
	poisson[2]  = float2(-.696, .457);
	poisson[3]  = float2(-.203, .621);
	poisson[4]  = float2( .962,-.195);
	poisson[5]  = float2( .473,-.480);
	poisson[6]  = float2( .519, .767);
	poisson[7]  = float2( .185,-.893);
	poisson[8]  = float2( .507, .064);
	poisson[9]  = float2( .896, .412);
	poisson[10] = float2(-.322,-.933);
	poisson[11] = float2(-.792,-.598);

	float3 col = 0;
	float random = frac(sin(dot(uv, float2(12.9898, 78.233))) * 43758.5453);
	float4 basis = float4(rot2D(float2(1, 0), random), rot2D(float2(0, 1), random));
	[unroll]
	for (int i = 0; i < 12; ++i) {
		float2 offset = poisson[i];
		offset = float2(dot(offset, basis.xz), dot(offset, basis.yw));

		if (bLightDoF_UseCA) {
			float2 rCoord = uv + offset * BUFFER_PIXEL_SIZE * fLightDoF_Width * (1.0 + CA);
			float2 gCoord = uv + offset * BUFFER_PIXEL_SIZE * fLightDoF_Width * (1.0 + CA * 0.5);
			float2 bCoord = uv + offset * BUFFER_PIXEL_SIZE * fLightDoF_Width;

			rCoord = lerp(uv, rCoord, getFocus(rCoord, farOrNear));
			gCoord = lerp(uv, gCoord, getFocus(gCoord, farOrNear));
			bCoord = lerp(uv, bCoord, getFocus(bCoord, farOrNear));

			col += 	float3(
						tex2Dlod(sp, float4(rCoord, 0, 0)).r,
						tex2Dlod(sp, float4(gCoord, 0, 0)).g,
						tex2Dlod(sp, float4(bCoord, 0, 0)).b
					);
		}
		else {
			float2 coord = uv + offset * BUFFER_PIXEL_SIZE * fLightDoF_Width;
			coord = lerp(uv, coord, getFocus(coord, farOrNear));
			col += tex2Dlod(sp, float4(coord, 0, 0)).rgb;
		}

	}
	return col * 0.083;
}

//shaders/////////////////////////////////////////////////////////////////////////////////////////

//far blur shader
float3 Far(float4 pos : SV_Position, float2 uv : TEXCOORD) : SV_Target {
	return poisson(ReShade::BackBuffer, uv, false, f2LightDoF_CA.x);
}

//near blur shader
float3 Near(float4 pos : SV_Position, float2 uv : TEXCOORD) : SV_Target {
	return poisson(ReShade::BackBuffer, uv, true, f2LightDoF_CA.y);
}

//shader to get the focus, kinda like center of confusion but less complicated
float GetFocus(float4 pos : SV_Position, float2 uv : TEXCOORD) : SV_Target {
	float2 linearMouse = f2LightDoF_MouseCoord * BUFFER_PIXEL_SIZE; //linearize the mouse position
	float2 focus = bLightDoF_UseMouseFocus ? linearMouse : f2Bokeh_AutoFocusCenter;
	return lerp(tex2D(sLastFocus, 0).x, ReShade::GetLinearizedDepth(focus), fLightDoF_AutoFocusSpeed);
}

//shader for saving this frame's focus to lerp with the next one's
float SaveFocus(float4 pos : SV_Position, float2 uv : TEXCOORD) : SV_Target {
	return tex2D(sFocus, 0).x;
}


//techniques//////////////////////////////////////////////////////////////////////////////////////

//this technique is dedicated for auto focus, so you don't need it if you're not using auto-focus :)
technique LightDoF_AutoFocus {
	pass GetFocus {
		VertexShader=PostProcessVS;
		PixelShader=GetFocus;
		RenderTarget=tFocus;
	}
	pass SaveFocus {
		VertexShader=PostProcessVS;
		PixelShader=SaveFocus;
		RenderTarget=tLastFocus;
	}
}

//technique for far blur
technique LightDoF_Far {
	pass Far {
		VertexShader=PostProcessVS;
		PixelShader=Far;
	}
}

//technique for near blur
technique LightDoF_Near {
	pass Near {
		VertexShader=PostProcessVS;
		PixelShader=Near;
	}
}

LiquidLens.fx:
#include "FXShaders/AspectRatio.fxh"
#include "FXShaders/Common.fxh"
#include "FXShaders/Convolution.fxh"
#include "FXShaders/Math.fxh"
#include "FXShaders/Tonemap.fxh"
#include "FXShaders/Transform.fxh"

#ifndef MAGIC_LENS_BLUR_SAMPLES
#define MAGIC_LENS_BLUR_SAMPLES 9
#endif

#ifndef MAGIC_LENS_DOWNSCALE
#define MAGIC_LENS_DOWNSCALE 4
#endif

namespace FXShaders { namespace LiquidLens
{

static const int BlurSamples = MAGIC_LENS_BLUR_SAMPLES;
static const int Downscale = MAGIC_LENS_DOWNSCALE;
static const float BaseFlareDownscale = 4.0;

FXSHADERS_WIP_WARNING();

uniform float Brightness
<
	ui_category = "Appearance";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 1.0;
> = 0.1;

uniform float Saturation
<
	ui_category = "Appearance";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 2.0;
> = 0.7;

uniform float Threshold
<
	ui_category = "Appearance";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 1.0;
> = 0.95;

uniform int Tonemapper
<
	ui_category = "Appearance";
	ui_type = "combo";
	ui_items = FXSHADERS_TONEMAPPER_LIST;
> = Tonemap::Type::BakingLabACES;

uniform float BlurSize
<
	ui_category = "Gaussian Blur";
	ui_label = "Size";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 1.0;
> = 1.0;

uniform float BlurSigma
<
	ui_category = "Gaussian Blur";
	ui_label = "Sigma";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 1.0;
> = 0.5;

uniform float FisheyeAmount
<
	ui_category = "Fisheye Lens";
	ui_category_closed = true;
	ui_label = "Amount";
	ui_type = "slider";
	ui_min = -1.0;
	ui_max = 1.0;
> = -0.1;

uniform float FisheyeZoom
<
	ui_category = "Fisheye Lens";
	ui_category_closed = true;
	ui_label = "Zoom";
	ui_type = "slider";
	ui_min = -1.0;
	ui_max = 1.0;
> = 1.0;

uniform int FisheyeScaleType
<
	ui_category = "Fisheye Lens";
	ui_text = "Aspect Ratio Scaling";
	ui_label = " ";
	ui_type = "radio";
	ui_items = FXSHADERS_ASPECT_RATIO_SCALE_TYPE_LIST;
> = AspectRatio::ScaleType::Cover;

uniform float TintAmount
<
	ui_category = "Flares";
	ui_category_closed = true;
	ui_label = "Tinting Amount";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 1.0;
> = 1.0;

#define _FLARE_TINT(id, defaultValue) \
uniform float4 Tint##id \
< \
	ui_category = "Flares"; \
	ui_label = "Tint " #id; \
	ui_type = "color"; \
> = defaultValue

_FLARE_TINT(1, float4(1.0, 0.0, 0.0, 1.0));
_FLARE_TINT(2, float4(1.0, 0.5, 0.0, 1.0));
_FLARE_TINT(3, float4(1.0, 1.0, 0.0, 1.0));
_FLARE_TINT(4, float4(0.0, 1.0, 0.0, 1.0));
_FLARE_TINT(5, float4(0.0, 1.0, 1.0, 1.0));
_FLARE_TINT(6, float4(0.0, 0.0, 1.0, 1.0));
_FLARE_TINT(7, float4(1.0, 0.0, 1.0, 1.0));

#undef _FLARE_TINT

#define _FLARE_SCALE(id, defaultValue) \
uniform float Scale##id \
< \
	ui_category = "Flares"; \
	ui_label = "Scale " #id; \
	ui_type = "slider"; \
	ui_min = -1.0; \
	ui_max = 1.0; \
> = defaultValue

_FLARE_SCALE(1, 0.01);
_FLARE_SCALE(2, 0.02);
_FLARE_SCALE(3, 0.03);
_FLARE_SCALE(4, 0.04);
_FLARE_SCALE(5, 0.05);
_FLARE_SCALE(6, 0.06);
_FLARE_SCALE(7, 0.07);

#undef _FLARE_SCALE

uniform bool ShowLens
<
	ui_category = "Debug";
	ui_category_closed = true;
	ui_label = "Show Lens Flare Texture";
> = false;

texture BackBufferTex : COLOR;

sampler BackBuffer
{
	Texture = BackBufferTex;
	SRGBTexture = true;
	AddressU = BORDER;
	AddressV = BORDER;
};

texture LensATex// <pooled = true;>
{
	Width = BUFFER_WIDTH / Downscale;
	Height = BUFFER_HEIGHT / Downscale;
	Format = RGBA16F;
};

sampler LensA
{
	Texture = LensATex;
	AddressU = BORDER;
	AddressV = BORDER;
};

texture LensBTex// <pooled = true;>
{
	Width = BUFFER_WIDTH / Downscale;
	Height = BUFFER_HEIGHT / Downscale;
	Format = RGBA16F;
};

sampler LensB
{
	Texture = LensBTex;
	AddressU = BORDER;
	AddressV = BORDER;
};

float4 PreparePS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	uv = ScaleCoord(1.0 - uv, BaseFlareDownscale);
	float4 color = tex2D(BackBuffer, uv);
	color.rgb = Tonemap::Inverse(Tonemapper, color.rgb);

	color.rgb = ApplySaturation(color.rgb, Saturation);
	color.rgb *= color.rgb >= Tonemap::Inverse(Tonemapper, Threshold).x;
	color.rgb *= Brightness;

	return color;
}

float4 Blur(sampler sp, float2 uv, float2 dir)
{
	dir *= BlurSize * Downscale;
	float sigma = sqrt(BlurSamples) * BlurSigma;
	return GaussianBlur1D(sp, uv, dir, sigma, BlurSamples);
}

float4 BlurXPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	return Blur(LensA, uv, float2(BUFFER_RCP_WIDTH, 0));
}

float4 BlurYPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	return Blur(LensB, uv, float2(0, BUFFER_RCP_HEIGHT));
}

float4 BlendPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float4 color = tex2D(BackBuffer, uv);
	color.rgb = Tonemap::Inverse(Tonemapper, color.rgb);

	uv = Transform::FisheyeLens(FisheyeScaleType, uv, FisheyeAmount * 10.0, FisheyeZoom * 3.0);

	#define _GET_TINT(id) float4(lerp(1.0, Tint##id##.rgb * Tint##id##.a, TintAmount), 1.0)

	#define _GET_FLARE(id) \
	(tex2D(LensA, ScaleCoord(uv, Scale##id * BaseFlareDownscale)) * _GET_TINT(id))

	float4 lens =
		_GET_FLARE(1) +
		_GET_FLARE(2) +
		_GET_FLARE(3) +
		_GET_FLARE(4) +
		_GET_FLARE(5) +
		_GET_FLARE(6) +
		_GET_FLARE(7);
	lens /= 7;

	#undef _GET_FLARE
	#undef _GET_TINT

	color.rgb = ShowLens
		? lens.rgb
		: color.rgb + lens.rgb; 

	color.rgb = Tonemap::Apply(Tonemapper, color.rgb);

	return color;
}

technique LiquidLens
{
	pass Prepare
	{
		VertexShader = ScreenVS;
		PixelShader = PreparePS;
		RenderTarget = LensATex;
	}
	pass BlurX
	{
		VertexShader = ScreenVS;
		PixelShader = BlurXPS;
		RenderTarget = LensBTex;
	}
	pass BlurY
	{
		VertexShader = ScreenVS;
		PixelShader = BlurYPS;
		RenderTarget = LensATex;
	}
	pass Blend
	{
		VertexShader = ScreenVS;
		PixelShader = BlendPS;
		SRGBWriteEnable = true;
	}
}

}} // Namespace.

LocalContrastCS.fx:
/*
LocalContrastCS
By: Lord Of Lunacy


A histogram based contrast stretching shader that locally adjusts the contrast of the image
based on the contents of small regions of the image.


Srinivasan, S & Balram, Nikhil. (2006). Adaptive contrast enhancement using local region stretching.
http://citeseerx.ist.psu.edu/viewdoc/download?doi=10.1.1.526.5037&rep=rep1&type=pdf
*/


#ifndef LARGE_CONTRAST_LUT
	#define LARGE_CONTRAST_LUT 1
#endif

#ifndef MORE_LOCALITY
	#define MORE_LOCALITY 0
#endif

#define DIVIDE_ROUNDING_UP(numerator, denominator) (int(numerator + denominator - 1) / int(denominator))

#if MORE_LOCALITY != 0
	#define TILES_SAMPLES_PER_THREAD uint2(2, 2)
#else
	#define TILES_SAMPLES_PER_THREAD uint2(3, 3)
#endif

#define COLUMN_SAMPLES_PER_THREAD 4
#define LOCAL_ARRAY_SIZE (TILES_SAMPLES_PER_THREAD.x * TILES_SAMPLES_PER_THREAD.y)
#if LARGE_CONTRAST_LUT != 0
	#define BIN_COUNT 1024
#else
	#define BIN_COUNT 256
#endif
#define GROUP_SIZE uint2(32, 32)
#undef RESOLUTION_MULTIPLIER
#define RESOLUTION_MULTIPLIER 1
#define DISPATCH_SIZE uint2(DIVIDE_ROUNDING_UP(BUFFER_WIDTH, TILES_SAMPLES_PER_THREAD.x * GROUP_SIZE.x * RESOLUTION_MULTIPLIER), \
					  DIVIDE_ROUNDING_UP(BUFFER_HEIGHT, TILES_SAMPLES_PER_THREAD.y * GROUP_SIZE.y * RESOLUTION_MULTIPLIER))

#if (((__RENDERER__ >= 0xb000 && __RENDERER__ < 0x10000) || (__RENDERER__ >= 0x14300)) && __RESHADE__ >=40800)
	#define CONTRAST_COMPUTE 1
#else
	#define CONTRAST_COMPUTE 0
#endif

#if CONTRAST_COMPUTE != 0
namespace LocalContrast 
{
	texture BackBuffer : COLOR;
	texture LocalTiles {Width = BIN_COUNT; Height = DISPATCH_SIZE.x * DISPATCH_SIZE.y; Format = R32f;};
	texture Histogram {Width = BIN_COUNT; Height = 1; Format = R32f;};
	texture HistogramLUT {Width = BIN_COUNT; Height = DISPATCH_SIZE.x * DISPATCH_SIZE.y; Format = R32f;};
	texture RegionVariancesH {Width = DISPATCH_SIZE.x * DISPATCH_SIZE.y; Height = 1; Format = RGBA32f;};
	texture RegionVariances {Width = DISPATCH_SIZE.x * DISPATCH_SIZE.y; Height = 1; Format = RGBA32f;};

	sampler sBackBuffer {Texture = BackBuffer;};
	sampler sLocalTiles {Texture = LocalTiles;};
	sampler sHistogram {Texture = Histogram;};
	sampler sHistogramLUT {Texture = HistogramLUT;};
	sampler sRegionVariancesH {Texture = RegionVariancesH;};
	sampler sRegionVariances {Texture = RegionVariances;};

	storage wLocalTiles {Texture = LocalTiles;};
	storage wHistogram {Texture = Histogram;};
	storage wHistogramLUT {Texture = HistogramLUT;};
	storage wRegionVariancesH {Texture = RegionVariancesH;};
	storage wRegionVariances {Texture = RegionVariances;};

	static const float GAUSSIAN[9] = {0.063327,	0.093095,	0.122589,	0.144599,	0.152781,	0.144599,	0.122589,	0.093095,	0.063327};
	//static const float GAUSSIAN[9] = {0.048297,	0.08393,	0.124548,	0.157829,	0.170793,	0.157829,	0.124548,	0.08393,	0.048297};
	//static const float GAUSSIAN[9] = {0.028532,	0.067234,	0.124009,	0.179044,	0.20236,	0.179044,	0.124009,	0.067234,	0.028532};
	//static const float GAUSSIAN[9] = {0.000229,	0.005977,	0.060598,	0.241732,	0.382928,	0.241732,	0.060598,	0.005977,	0.000229};
	//static const float GAUSSIAN[5] = {0.153388,	0.221461,	0.250301,	0.221461,	0.153388};


	uniform float GlobalStrength<
		ui_type = "slider";
		ui_label = "Strength";
		ui_min = 0; ui_max = 1;
	> = 0.75;

	uniform float Minimum<
		ui_type = "slider";
		ui_label = "Minimum";
		ui_category = "Thresholds";
		ui_min = 0; ui_max = 1;
	> = 0;

	uniform float DarkThreshold<
		ui_type = "slider";
		ui_label = "Dark Threshold";
		ui_category = "Thresholds";
		ui_min = 0; ui_max = 1;
	> = 0.333;

	uniform float LightThreshold<
		ui_type = "slider";
		ui_label = "LightThreshold";
		ui_category = "Thresholds";
		ui_min = 0; ui_max = 1;
	> = 0.667;

	uniform float Maximum<
		ui_type = "slider";
		ui_label = "Maximum";
		ui_category = "Thresholds";
		ui_min = 0; ui_max = 1;
	> = 1;

	uniform float DarkPeak<
		ui_type = "slider";
		ui_label = "Dark Blending Curve";
		ui_category = "Dark Settings";
		ui_min = 0; ui_max = 1;
	> = 0.075;

	uniform float DarkMax<
		ui_type = "slider";
		ui_label = "Dark Maximum Blending";
		ui_category = "Dark Settings";
		ui_min = 0; ui_max = 1;
	> = 0.15;

	uniform float MidPeak<
		ui_type = "slider";
		ui_label = "Mid Blending Curve";
		ui_category = "Mid Settings";
		ui_min = 0; ui_max = 1;
	> = 0.5;

	uniform float MidMax<
		ui_type = "slider";
		ui_label = "Mid Maximum Blending";
		ui_category = "Mid Settings";
		ui_min = 0; ui_max = 1;
	> = 0.4;

	uniform float LightPeak<
		ui_type = "slider";
		ui_label = "Light Blending Curve";
		ui_category = "Light Settings";
		ui_min = 0; ui_max = 1;
	> = 0.7;

	uniform float LightMax<
		ui_type = "slider";
		ui_label = "Light Maximum Blending";
		ui_category = "Light Settings";
		ui_min = 0; ui_max = 1;
	> = 0.3;


	groupshared uint HistogramBins[BIN_COUNT];
	void HistogramTilesCS(uint3 id : SV_DispatchThreadID, uint3 gid : SV_GroupID, uint3 gtid : SV_GroupThreadID)
	{
		uint threadIndex = gtid.x + gtid.y * GROUP_SIZE.x;
		uint groupIndex = gid.x + gid.y * DISPATCH_SIZE.x;

		[unroll]
		while(threadIndex < BIN_COUNT)
		{
			HistogramBins[threadIndex] = 0;
			threadIndex += GROUP_SIZE.x * GROUP_SIZE.y;
		}
		barrier();

		uint localValue[LOCAL_ARRAY_SIZE];
		[unroll]
		for(int i = 0; i < TILES_SAMPLES_PER_THREAD.x; i++)
		{
			[unroll]
			for(int j = 0; j < TILES_SAMPLES_PER_THREAD.y; j++)
			{
				float2 coord = (gid.xy * TILES_SAMPLES_PER_THREAD * GROUP_SIZE + (gtid.xy * TILES_SAMPLES_PER_THREAD + float2(i, j)) * 3) * RESOLUTION_MULTIPLIER;
				coord -= float2(GROUP_SIZE * TILES_SAMPLES_PER_THREAD) * 1.5;
				uint arrayIndex = i + TILES_SAMPLES_PER_THREAD.x * j;
				if(any(coord >= uint2(BUFFER_WIDTH, BUFFER_HEIGHT)) || any(coord < 0))
				{
					localValue[arrayIndex] = BIN_COUNT;
				}
				else
				{
					localValue[arrayIndex] = uint(round(dot(tex2Dfetch(sBackBuffer, float2(coord)).rgb, float3(0.299, 0.587, 0.114)) * (BIN_COUNT - 1)));
				}
			}
		}


		[unroll]
		for(int i = 0; i < LOCAL_ARRAY_SIZE; i++)
		{
			if(localValue[i] < BIN_COUNT)
			{
				atomicAdd(HistogramBins[localValue[i]], 1);
			}
		}
		barrier();
		threadIndex = gtid.x + gtid.y * GROUP_SIZE.x;
		[unroll]
		while(threadIndex < BIN_COUNT)
		{
			tex2Dstore(wLocalTiles, int2(threadIndex, groupIndex), float4(HistogramBins[threadIndex], 1, 1, 1));
			threadIndex += GROUP_SIZE.x * GROUP_SIZE.y;
		}
	}

	groupshared float prefixSums[BIN_COUNT * 2];
	groupshared float valuePrefixSums[BIN_COUNT * 2];
	groupshared float3 regionSums;
	groupshared float3 regionMeans;
	groupshared uint3 regionVariances;

	void ContrastLUTCS(uint3 id : SV_DispatchThreadID)
	{
		float localBin = tex2Dfetch(sLocalTiles, id.xy).r;
		float localPrefixSum = localBin;
		float luma = (float(id.x) / float(BIN_COUNT - 1));
		float localValuePrefixSum = localBin * luma;
		prefixSums[id.x] = localPrefixSum;
		valuePrefixSums[id.x] = localValuePrefixSum;
		barrier();

		uint2 prefixSumOffset = uint2(0, BIN_COUNT);

		bool enabled = true;

		[unroll]
		for(int i = 0; i < log2(BIN_COUNT - 1) + 1; i++)
		{
			int access = id.x - exp2(i);
			if(access >= 0)
			{
				localPrefixSum += prefixSums[access + prefixSumOffset.x];
				localValuePrefixSum += valuePrefixSums[access + prefixSumOffset.x];
				prefixSums[id.x + prefixSumOffset.y] = localPrefixSum;
				valuePrefixSums[id.x + prefixSumOffset.y] = localValuePrefixSum;
			}
			else if (enabled)
			{
				prefixSums[id.x + prefixSumOffset.y] = localPrefixSum;
				valuePrefixSums[id.x + prefixSumOffset.y] = localValuePrefixSum;
				enabled = false;
			}

			prefixSumOffset.xy = prefixSumOffset.yx;
			barrier();
		}

		float3 localRegionSums;
		float3 localRegionMeans;
		uint darkThresholdUint = DarkThreshold * (BIN_COUNT - 1);
		uint lightThresholdUint = LightThreshold * (BIN_COUNT - 1);

		if(id.x == 0)
		{
			localRegionSums.x = prefixSums[darkThresholdUint + prefixSumOffset.x];
			localRegionSums.y = prefixSums[lightThresholdUint + prefixSumOffset.x];
			localRegionSums.z = prefixSums[BIN_COUNT - 1 + prefixSumOffset.x];

			localRegionMeans.x = valuePrefixSums[darkThresholdUint + prefixSumOffset.x];
			localRegionMeans.y = valuePrefixSums[lightThresholdUint + prefixSumOffset.x];
			localRegionMeans.z = valuePrefixSums[BIN_COUNT - 1 + prefixSumOffset.x];
			localRegionMeans /= localRegionSums;
			regionMeans = localRegionMeans;

			localRegionSums.z -= localRegionSums.y;
			localRegionSums.y -= localRegionSums.x;
			regionSums = localRegionSums;
			regionVariances = 0;
		}
		barrier();

		localRegionSums = regionSums;
		localRegionMeans = regionMeans;
		float lutValue;

		if(id.x <= darkThresholdUint)
		{
			if(localRegionSums.x == 0)
			{
				lutValue = (float(id.x) / float(BIN_COUNT - 1));
			}
			else
			{
				float offset = Minimum;
				float multiplier = float(DarkThreshold - Minimum);
				lutValue = saturate((localPrefixSum / localRegionSums.x) * multiplier) + offset;
			}
			uint varianceComponent = uint(float(abs(luma - localRegionMeans.x)) * float(localBin * (BIN_COUNT)));
			atomicAdd(regionVariances[0], varianceComponent);
		}
		else if(id.x <= lightThresholdUint)
		{
			if(localRegionSums.y == 0)
			{
				lutValue = (float(id.x) / float(BIN_COUNT - 1));
			}
			else
			{
				float offset = DarkThreshold;
				float multiplier = float(LightThreshold - DarkThreshold);
				localPrefixSum -= localRegionSums.x;
				lutValue = saturate(((localPrefixSum) / localRegionSums.y) * multiplier) + offset;
			}
				uint varianceComponent = uint(float(abs(luma - localRegionMeans.y)) * float(localBin * (BIN_COUNT)));
				atomicAdd(regionVariances[1], varianceComponent);
		}
		else
		{
			if(localRegionSums.z == 0)
			{
				lutValue = (float(id.x) / float(BIN_COUNT - 1));
			}
			else
			{
				float offset = LightThreshold;
				float multiplier = float(LightThreshold - DarkThreshold);
				localPrefixSum -= localRegionSums.x + localRegionSums.y;
				lutValue = saturate(((localPrefixSum) / localRegionSums.z) * multiplier) + offset;
			}
				uint varianceComponent = uint(float(abs(luma - localRegionMeans.z)) * float(localBin * (BIN_COUNT)));
				atomicAdd(regionVariances[2], varianceComponent);
		}
		barrier();

		if(id.x == 0)
		{
			float3 localRegionVariances = float3(regionVariances) / ((BIN_COUNT) * float3(max(localRegionSums, 0.001)));
			//localRegionVariances = 0.95 * previousRegionVariances + 0.05 * localRegionVariances;
			tex2Dstore(wRegionVariances, int2(id.y, 0), float4(localRegionVariances.xyz, 1));
		}

		tex2Dstore(wHistogramLUT, id.xy, lutValue);
	}

	// Vertex shader generating a triangle covering the entire screen
	void PostProcessVS(in uint id : SV_VertexID, out float4 position : SV_Position, out float2 texcoord : TEXCOORD)
	{
		texcoord.x = (id == 2) ? 2.0 : 0.0;
		texcoord.y = (id == 1) ? 2.0 : 0.0;
		position = float4(texcoord * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
	}

	float WeightingCurve(float peak, float variance, float maximumBlending)
	{
		float output;
		if(variance <= peak)
		{
			return lerp(0, maximumBlending, abs(variance) / peak);
		}
		else
		{
			return lerp(maximumBlending, 0, abs(variance - peak) / (1 - peak));
		}
	}

	void LUTInterpolation(uint2 coord, float yOld, out float yNew, out float3 variances)
	{
		uint2 blockSize = uint2((GROUP_SIZE.x * TILES_SAMPLES_PER_THREAD.x), (GROUP_SIZE.y * TILES_SAMPLES_PER_THREAD.y));
		uint2 groupCoord = coord / blockSize;
		int2 position = (coord % blockSize) - float2(blockSize / 2);
		float2 positionCoord = float2(abs(position)) / float2(blockSize);
		float2 weights = smoothstep(0, 1, positionCoord);
		uint group = groupCoord.x + groupCoord.y * DISPATCH_SIZE.x;
		int2 groupCoordW;
		float samples[4];
		float3 varianceSamples[4];
		samples[0] = tex2Dfetch(sHistogramLUT, float2(yOld * BIN_COUNT, group)).x;
		varianceSamples[0] = tex2Dfetch(sRegionVariances, float2(group, 0)).xyz;
		int2 groupCoordTemp = groupCoord;
		if(position.x < 0)
		{
			groupCoordTemp.x -= 1;
			groupCoordTemp = clamp(groupCoordTemp, 0, DISPATCH_SIZE);
			groupCoordW = groupCoordTemp;
			group = groupCoord.x + groupCoord.y * DISPATCH_SIZE.x;
			samples[1] = tex2Dfetch(sHistogramLUT, float2(yOld * BIN_COUNT, group)).x;
			varianceSamples[1] = tex2Dfetch(sRegionVariances, float2(group, 0)).xyz;
		}
		else
		{
			groupCoordTemp.x += 1;
			groupCoordTemp = clamp(groupCoordTemp, 0, DISPATCH_SIZE);
			groupCoordW = groupCoordTemp;
			group = groupCoordTemp.x + groupCoordTemp.y * DISPATCH_SIZE.x;
			samples[1] = tex2Dfetch(sHistogramLUT, float2(yOld * BIN_COUNT, group)).x;
			varianceSamples[1] = tex2Dfetch(sRegionVariances, float2(group, 0)).xyz;
		}

		if(position.y < 0)
		{
			groupCoordTemp.y -= 1;
			groupCoordTemp = clamp(groupCoordTemp, 0, DISPATCH_SIZE);
			groupCoordW.y = groupCoordTemp.y;
			group = groupCoordTemp.x + groupCoordTemp.y * DISPATCH_SIZE.x;
			samples[2] = tex2Dfetch(sHistogramLUT, float2(yOld * BIN_COUNT, group)).x;
			varianceSamples[2] = tex2Dfetch(sRegionVariances, float2(group, 0)).xyz ;
		}
		else
		{
			groupCoordTemp.y += 1;
			groupCoordTemp = clamp(groupCoordTemp, 0, DISPATCH_SIZE);
			groupCoordW.y = groupCoordTemp.y;
			group = groupCoordTemp.x + groupCoordTemp.y * DISPATCH_SIZE.x;
			samples[2] = tex2Dfetch(sHistogramLUT, float2(yOld * BIN_COUNT, group)).x;
			varianceSamples[2] = tex2Dfetch(sRegionVariances, float2(group, 0)).xyz;
		}

		group = groupCoordW.x + groupCoordW.y * DISPATCH_SIZE.x;
		samples[3] = tex2Dfetch(sHistogramLUT, float2(yOld * BIN_COUNT, group)).x;
		varianceSamples[3] = tex2Dfetch(sRegionVariances, float2(group, 0)).xyz;

		yNew = lerp(lerp(samples[0], samples[1], weights.x), lerp(samples[2], samples[3], weights.x), weights.y);
		variances = lerp(lerp(varianceSamples[0], varianceSamples[1], weights.x), lerp(varianceSamples[2], varianceSamples[3], weights.x), weights.y);
	}

	void GaussianVarianceHPS(float4 pos : SV_Position, float2 texcoord : TEXCOORD, out float4 GaussianVariance : SV_Target0)
	{
		GaussianVariance = 0;
		uint textureHeight = DISPATCH_SIZE.x * DISPATCH_SIZE.y;
		uint2 coord = texcoord * float2(1, textureHeight);
		uint2 group = uint2(coord.x / (GROUP_SIZE.x * TILES_SAMPLES_PER_THREAD.x), (coord.y / (GROUP_SIZE.y * TILES_SAMPLES_PER_THREAD.y)));
		[unroll]
		for(int i = -4; i <= 4; i++)
		{
			int2 sampleCoord = uint2(coord.x, coord.y + i);
			sampleCoord.y = clamp(sampleCoord.y, 0, textureHeight - 1);
			sampleCoord.xy = sampleCoord.yx;
			GaussianVariance.xyz += GAUSSIAN[i + 4] * tex2Dfetch(sRegionVariances, sampleCoord).xyz;
		}
		GaussianVariance.w = 1;
	}

	void GaussianVarianceVPS(float4 pos : SV_Position, float2 texcoord : TEXCOORD, out float4 GaussianVariance : SV_Target0)
	{
		GaussianVariance = 0;
		uint textureHeight = DISPATCH_SIZE.x * DISPATCH_SIZE.y;
		uint2 coord = texcoord * float2(1, textureHeight);
		uint2 group = uint2(coord.x / (GROUP_SIZE.x * TILES_SAMPLES_PER_THREAD.x), (coord.y / (GROUP_SIZE.y * TILES_SAMPLES_PER_THREAD.y)));
		int2 clampingValues;
		clampingValues.x = coord.y % DISPATCH_SIZE.x;
		clampingValues.y = textureHeight - (DISPATCH_SIZE.x - clampingValues.x) - 1;
		[unroll]
		for(int i = -4; i <= 4; i++)
		{
			int2 sampleCoord = uint2(coord.x, coord.y + i * DISPATCH_SIZE.x);
			sampleCoord.y = clamp(sampleCoord.y, clampingValues.x, clampingValues.y);
			sampleCoord.xy = sampleCoord.yx;
			GaussianVariance.xyz += GAUSSIAN[i + 4] * tex2Dfetch(sRegionVariancesH, sampleCoord).xyz;
		}
		GaussianVariance.w = 1;
	}


	void OutputPS(float4 pos : SV_Position, float2 texcoord : TEXCOORD, out float3 color : SV_Target0)
	{
		color = tex2D(sBackBuffer, texcoord).rgb;
		uint2 coord = texcoord * float2(BUFFER_WIDTH, BUFFER_HEIGHT);
		float yOld = dot(color, float3(0.299, 0.587, 0.114));
		uint group = coord.x / (GROUP_SIZE.x * TILES_SAMPLES_PER_THREAD.x) + (coord.y / (GROUP_SIZE.y * TILES_SAMPLES_PER_THREAD.y)) * DISPATCH_SIZE.x;
		float3 variances;
		float yNew;
		LUTInterpolation(coord, /*texcoord,*/ yOld, yNew, variances);
		float alpha;


		if(yOld <= DarkThreshold)
		{
			alpha = WeightingCurve(DarkPeak, variances.x, DarkMax);
			//alpha = variances.x;
		}
		else if(yOld <= LightThreshold)
		{
			alpha = WeightingCurve(MidPeak, variances.y, MidMax);
			//alpha = variances.y;
		}
		else
		{
			alpha = WeightingCurve(LightPeak, variances.z, LightMax);
			//alpha = variances.z;
		}
		float y = lerp(yOld, yNew, (alpha * GlobalStrength));

		float cb = -0.168736 * color.r - 0.331264 * color.g + 0.500000 * color.b;
		float cr = +0.500000 * color.r - 0.418688 * color.g - 0.081312 * color.b;

		color = float3(
				y + 1.402 * cr,
				y - 0.344136 * cb - 0.714136 * cr,
				y + 1.772 * cb);

	}

	technique LocalContrastCS<ui_tooltip = "A histogram based contrast stretching shader that locally adjusts the contrast of the image\n"
										   "based on the contents of small regions of the image.\n\n"
										   "May cause square shaped artifacting \n\n"
										   "Part of the Insane Shaders repository";>
	{
		pass
		{
			ComputeShader = HistogramTilesCS<GROUP_SIZE.x, GROUP_SIZE.y>;
			DispatchSizeX = DISPATCH_SIZE.x;
			DispatchSizeY = DISPATCH_SIZE.y;
		}

		pass
		{
			ComputeShader = ContrastLUTCS<(BIN_COUNT), 1>;
			DispatchSizeX = 1;
			DispatchSizeY = DISPATCH_SIZE.x * DISPATCH_SIZE.y;
		}

		pass
		{
			VertexShader = PostProcessVS;
			PixelShader = GaussianVarianceHPS;
			RenderTarget = RegionVariancesH;
		}

		pass
		{
			VertexShader = PostProcessVS;
			PixelShader = GaussianVarianceVPS;
			RenderTarget = RegionVariances;
		}

		pass
		{
			VertexShader = PostProcessVS;
			PixelShader = OutputPS;
		}
	}
}
#endif //CONTRAST_COMPUTE != 0

LumaSharpen.fx:
/**
   LumaSharpen version 1.5.0
   by Christian Cann Schuldt Jensen ~ CeeJay.dk

   It blurs the original pixel with the surrounding pixels and then subtracts this blur to sharpen the image.
   It does this in luma to avoid color artifacts and allows limiting the maximum sharpning to avoid or lessen halo artifacts.
   This is similar to using Unsharp Mask in Photoshop.

   Version 1.5.1
  - UI improvements for Reshade 3.x
 */

#include "ReShadeUI.fxh"

uniform float sharp_strength < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.1; ui_max = 3.0;
	ui_label = "Shapening strength";
	ui_tooltip = "Strength of the sharpening";

> = 0.65;
uniform float sharp_clamp < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.0; ui_max = 1.0; ui_step = 0.005;
	ui_label = "Sharpening limit";
	ui_tooltip = "Limits maximum amount of sharpening a pixel receives\nThis helps avoid \"haloing\" artifacts which would otherwise occur when you raised the strength too much.";
> = 0.035;
uniform int pattern <
	ui_type = "combo";
	ui_items =	"Fast" "\0"
				"Normal" "\0"
				"Wider"	"\0"
				"Pyramid shaped" "\0";
	ui_label = "Sample pattern";
	ui_tooltip = "Choose a sample pattern.\n"
	"Fast is faster but slightly lower quality.\n"
	"Normal is normal.\n"
	"Wider is less sensitive to noise but also to fine details.\n"
	"Pyramid has a slightly more aggresive look.";
> = 1;
uniform float offset_bias < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.0; ui_max = 6.0;
	ui_label = "Offset bias";
	ui_tooltip = "Offset bias adjusts the radius of the sampling pattern. I designed the pattern for an offset bias of 1.0, but feel free to experiment.";
> = 1.0;
uniform bool show_sharpen <
	ui_label = "Show sharpening pattern";
	ui_tooltip = "Visualize the strength of the sharpen\nThis is useful for seeing what areas the sharpning affects the most";
> = false;

#include "ReShade.fxh"

   /*-----------------------------------------------------------.
  /                      Developer settings                     /
  '-----------------------------------------------------------*/
#define CoefLuma float3(0.2126, 0.7152, 0.0722)      // BT.709 & sRBG luma coefficient (Monitors and HD Television)
//#define CoefLuma float3(0.299, 0.587, 0.114)       // BT.601 luma coefficient (SD Television)
//#define CoefLuma float3(1.0/3.0, 1.0/3.0, 1.0/3.0) // Equal weight coefficient

   /*-----------------------------------------------------------.
  /                          Main code                          /
  '-----------------------------------------------------------*/

float3 LumaSharpenPass(float4 position : SV_Position, float2 tex : TEXCOORD) : SV_Target
{
	// -- Get the original pixel --
	float3 ori = tex2D(ReShade::BackBuffer, tex).rgb; // ori = original pixel

	// -- Combining the strength and luma multipliers --
	float3 sharp_strength_luma = (CoefLuma * sharp_strength); //I'll be combining even more multipliers with it later on

	/*-----------------------------------------------------------.
	/                       Sampling patterns                     /
	'-----------------------------------------------------------*/
	float3 blur_ori;

	//   [ NW,   , NE ] Each texture lookup (except ori)
	//   [   ,ori,    ] samples 4 pixels
	//   [ SW,   , SE ]

	// -- Pattern 1 -- A (fast) 7 tap gaussian using only 2+1 texture fetches.
	if (pattern == 0)
	{
		// -- Gaussian filter --
		//   [ 1/9, 2/9,    ]     [ 1 , 2 ,   ]
		//   [ 2/9, 8/9, 2/9]  =  [ 2 , 8 , 2 ]
		//   [    , 2/9, 1/9]     [   , 2 , 1 ]

		blur_ori  = tex2D(ReShade::BackBuffer, tex + (BUFFER_PIXEL_SIZE / 3.0) * offset_bias).rgb;  // North West
		blur_ori += tex2D(ReShade::BackBuffer, tex + (-BUFFER_PIXEL_SIZE / 3.0) * offset_bias).rgb; // South East

		//blur_ori += tex2D(ReShade::BackBuffer, tex + (BUFFER_PIXEL_SIZE / 3.0) * offset_bias); // North East
		//blur_ori += tex2D(ReShade::BackBuffer, tex + (-BUFFER_PIXEL_SIZE / 3.0) * offset_bias); // South West

		blur_ori /= 2;  //Divide by the number of texture fetches

		sharp_strength_luma *= 1.5; // Adjust strength to aproximate the strength of pattern 2
	}

	// -- Pattern 2 -- A 9 tap gaussian using 4+1 texture fetches.
	if (pattern == 1)
	{
		// -- Gaussian filter --
		//   [ .25, .50, .25]     [ 1 , 2 , 1 ]
		//   [ .50,   1, .50]  =  [ 2 , 4 , 2 ]
		//   [ .25, .50, .25]     [ 1 , 2 , 1 ]

		blur_ori  = tex2D(ReShade::BackBuffer, tex + float2(BUFFER_PIXEL_SIZE.x, -BUFFER_PIXEL_SIZE.y) * 0.5 * offset_bias).rgb; // South East
		blur_ori += tex2D(ReShade::BackBuffer, tex - BUFFER_PIXEL_SIZE * 0.5 * offset_bias).rgb;  // South West
		blur_ori += tex2D(ReShade::BackBuffer, tex + BUFFER_PIXEL_SIZE * 0.5 * offset_bias).rgb; // North East
		blur_ori += tex2D(ReShade::BackBuffer, tex - float2(BUFFER_PIXEL_SIZE.x, -BUFFER_PIXEL_SIZE.y) * 0.5 * offset_bias).rgb; // North West

		blur_ori *= 0.25;  // ( /= 4) Divide by the number of texture fetches
	}

	// -- Pattern 3 -- An experimental 17 tap gaussian using 4+1 texture fetches.
	if (pattern == 2)
	{
		// -- Gaussian filter --
		//   [   , 4 , 6 ,   ,   ]
		//   [   ,16 ,24 ,16 , 4 ]
		//   [ 6 ,24 ,   ,24 , 6 ]
		//   [ 4 ,16 ,24 ,16 ,   ]
		//   [   ,   , 6 , 4 ,   ]

		blur_ori  = tex2D(ReShade::BackBuffer, tex + BUFFER_PIXEL_SIZE * float2(0.4, -1.2) * offset_bias).rgb;  // South South East
		blur_ori += tex2D(ReShade::BackBuffer, tex - BUFFER_PIXEL_SIZE * float2(1.2, 0.4) * offset_bias).rgb; // West South West
		blur_ori += tex2D(ReShade::BackBuffer, tex + BUFFER_PIXEL_SIZE * float2(1.2, 0.4) * offset_bias).rgb; // East North East
		blur_ori += tex2D(ReShade::BackBuffer, tex - BUFFER_PIXEL_SIZE * float2(0.4, -1.2) * offset_bias).rgb; // North North West

		blur_ori *= 0.25;  // ( /= 4) Divide by the number of texture fetches

		sharp_strength_luma *= 0.51;
	}

	// -- Pattern 4 -- A 9 tap high pass (pyramid filter) using 4+1 texture fetches.
	if (pattern == 3)
	{
		// -- Gaussian filter --
		//   [ .50, .50, .50]     [ 1 , 1 , 1 ]
		//   [ .50,    , .50]  =  [ 1 ,   , 1 ]
		//   [ .50, .50, .50]     [ 1 , 1 , 1 ]

		blur_ori  = tex2D(ReShade::BackBuffer, tex + float2(0.5 * BUFFER_PIXEL_SIZE.x, -BUFFER_PIXEL_SIZE.y * offset_bias)).rgb;  // South South East
		blur_ori += tex2D(ReShade::BackBuffer, tex + float2(offset_bias * -BUFFER_PIXEL_SIZE.x, 0.5 * -BUFFER_PIXEL_SIZE.y)).rgb; // West South West
		blur_ori += tex2D(ReShade::BackBuffer, tex + float2(offset_bias * BUFFER_PIXEL_SIZE.x, 0.5 * BUFFER_PIXEL_SIZE.y)).rgb; // East North East
		blur_ori += tex2D(ReShade::BackBuffer, tex + float2(0.5 * -BUFFER_PIXEL_SIZE.x, BUFFER_PIXEL_SIZE.y * offset_bias)).rgb; // North North West

		//blur_ori += (2 * ori); // Probably not needed. Only serves to lessen the effect.

		blur_ori /= 4.0;  //Divide by the number of texture fetches

		sharp_strength_luma *= 0.666; // Adjust strength to aproximate the strength of pattern 2
	}

	 /*-----------------------------------------------------------.
	/                            Sharpen                          /
	'-----------------------------------------------------------*/

	// -- Calculate the sharpening --
	float3 sharp = ori - blur_ori;  //Subtracting the blurred image from the original image

#if 0 //older 1.4 code (included here because the new code while faster can be difficult to understand)
	// -- Adjust strength of the sharpening --
	float sharp_luma = dot(sharp, sharp_strength_luma); //Calculate the luma and adjust the strength

	// -- Clamping the maximum amount of sharpening to prevent halo artifacts --
	sharp_luma = clamp(sharp_luma, -sharp_clamp, sharp_clamp);  //TODO Try a curve function instead of a clamp

#else //new code
	// -- Adjust strength of the sharpening and clamp it--
	float4 sharp_strength_luma_clamp = float4(sharp_strength_luma * (0.5 / sharp_clamp),0.5); //Roll part of the clamp into the dot

	//sharp_luma = saturate((0.5 / sharp_clamp) * sharp_luma + 0.5); //scale up and clamp
	float sharp_luma = saturate(dot(float4(sharp,1.0), sharp_strength_luma_clamp)); //Calculate the luma, adjust the strength, scale up and clamp
	sharp_luma = (sharp_clamp * 2.0) * sharp_luma - sharp_clamp; //scale down
#endif

	// -- Combining the values to get the final sharpened pixel	--
	float3 outputcolor = ori + sharp_luma;    // Add the sharpening to the the original.

	 /*-----------------------------------------------------------.
	/                     Returning the output                    /
	'-----------------------------------------------------------*/

	if (show_sharpen)
	{
		//outputcolor = abs(sharp * 4.0);
		outputcolor = saturate(0.5 + (sharp_luma * 4.0)).rrr;
	}

	return saturate(outputcolor);
}

technique LumaSharpen
{
	pass
	{
		VertexShader = PostProcessVS;
		PixelShader = LumaSharpenPass;
	}
}

MBMB.fx:
/*
	Mouse-Based Motion Blur by luluco250
*/

#include "ReShade.fxh"

//Macros////////////////////////////////////////////////////////////////////////////////////////////

// How many samples/taps to take from the image.
// Too low will make the blur less smooth.
// Too high can be very bad for performance.
#ifndef MBMB_SAMPLES
#define MBMB_SAMPLES 20
#endif

// Use gaussian blur or simple linear blurring?
#ifndef MBMB_GAUSSIAN
#define MBMB_GAUSSIAN 1
#endif

// Depth flags, they do exactly what they're named after.
#define AFFECT_INTENSITY 1
#define AFFECT_DISTORTION 2

// To use these flags, you define MBMB_DEPTH_FLAGS in
// this fashion: 
//
// MBMB_DEPTH_FLAGS=0
// MBMB_DEPTH_FLAGS=AFFECT_INTENSITY
// MBMB_DEPTH_FLAGS=AFFECT_DISTORTION
// MBMB_DEPTH_FLAGS=AFFECT_INTENSITY | AFFECT_DISTORTION
//
// Note the '|' OR operator, this combines the flags.
#ifndef MBMB_DEPTH_FLAGS
#define MBMB_DEPTH_FLAGS 0
#endif

// Smoothes out mouse movement, but uses two textures and passes.
#ifndef MBMB_SMOOTHING
#define MBMB_SMOOTHING 0
#endif

// Simulates HDR, which makes highlights keep
// their brightness even after blurring.
#ifndef MBMB_HDR
#define MBMB_HDR 0
#endif

//Uniforms//////////////////////////////////////////////////////////////////////////////////////////

uniform float fSensitivity <
	ui_label   = "Sensitivity";
	ui_tooltip = "This is multiplied to the mouse speed.\n"
	             "Lower values will help smooth out motion "
				 "as the mouse speed can be a bit \"jumpy\" "
				 "at low motions.\n"
				 "Higher values will instead increase it even "
				 "more, increasing the overall \"instensity\" "
				 "of the effect.\n"
	             "\nDefault: 0.1";
	ui_type    = "drag";
	ui_min     = 0.0;
	ui_max     = 100.0;
	ui_step    = 0.01;
> = 0.1;

uniform float fDistortion <
	ui_label   = "Distortion";
	ui_tooltip = "How much to distort the blurring to "
	             "simulate the look of real vector-based "
				 "motion blur.\n"
				 "Can look weird with values too high "
				 "but also smoothes out the blurring, "
				 "preventing \"straight lines\".\n"
	             "\nDefault: 1.0";
	ui_type    = "drag";
	ui_min     = 0.0;
	ui_max     = 10.0;
	ui_step    = 0.01;
> = 1.0;

uniform float2 f2MinMaxSpeed <
	ui_label   = "Min/Max Speed";
	ui_tooltip = "The first value tells the shader where "
	             "to cut off the mouse speed, so it only "
				 "blurs when you move the mouse at a speed "
				 "higher than it.\n"
				 "The second value specifies the maximum "
				 "speed allowed from the mouse.\n"
				 "You can disable this by setting the "
				 "first value to 0.0 and the second to a "
				 "very high value, like 100.0.\n"
	             "\nDefault: (0.1, 10.0)";
	ui_type    = "drag";
	ui_min     = 0.0;
	ui_max     = 100.0;
	ui_step    = 0.01;
> = float2(0.1, 10.0);

#if MBMB_DEPTH_FLAGS > 0
uniform float fDepthInfluence <
	ui_label   = "Depth Influence";
	ui_tooltip = "How much depth affects the effect.\n"
	             "Values lower than 1.0 will reduce "
				 "how much depth has an effect on the "
				 "intensity and distortion of the effect.\n"
	             "Values above 1.0 will increase it's effect.\n"
				 "It is recommended to test thoroughly to "
				 "find a good balance.\n"
	             "\nDefault: 1.0";
	ui_type    = "drag";
	ui_min     = 0.0;
	ui_max     = 10.0;
	ui_step    = 0.001;
> = 1.0;
#endif

#if MBMB_GAUSSIAN
uniform float fBlur_Sigma <
	ui_label   = "Blur Sigma";
	ui_tooltip = "How much to blur the image.\n"
	             "Too much will reduce the overall "
				 "quality of the blurring.\n"
				 "While too little will reduce the "
				 "amount of blurring overall.\n"
	             "\nDefault: 4.0";
	ui_type    = "drag";
	ui_min     = 1.0;
	ui_max     = 100.0;
	ui_step    = 0.01;
> = 4.0;
#endif

#if MBMB_SMOOTHING
uniform float fSmoothing <
	ui_label   = "Smoothing";
	ui_tooltip = "Default: 10.0";
	ui_type    = "drag";
	ui_min     = 0.01;
	ui_max     = 100.0;
	ui_step    = 0.01;
> = 10.0;
#endif

#if MBMB_HDR
uniform float fHDRBrightness <
	ui_label   = "HDR Brightness";
	ui_tooltip = "Default: 3.0";
	ui_type    = "drag";
	ui_min     = 1.0;
	ui_max     = 10.0;
	ui_step    = 0.01;
> = 3.0;
#endif

#if MBMB_SMOOTHING
uniform float fFrameTime <source = "frametime";>;
#endif

uniform float3 f3MouseDelta <source = "mousedelta";>;

//Textures//////////////////////////////////////////////////////////////////////////////////////////

sampler2D sBackBuffer {
	Texture     = ReShade::BackBufferTex;
	//SRGBTexture = true;
	MinFilter   = LINEAR;
	MagFilter   = LINEAR;
	MipFilter   = LINEAR;
	AddressU    = CLAMP;
	AddressV    = CLAMP;
};

#if MBMB_SMOOTHING
texture2D tMBMB_Mouse {
	Format = RG16F;
};
sampler2D sMouse {
	Texture   = tMBMB_Mouse;
	MinFilter = POINT;
	MagFilter = POINT;
	MipFilter = POINT;
	AddressU  = BORDER;
	AddressV  = BORDER;
};

texture2D tMBMB_LastMouse {
	Format = RG16F;
};
sampler2D sLastMouse {
	Texture   = tMBMB_LastMouse;
	MinFilter = POINT;
	MagFilter = POINT;
	MipFilter = POINT;
	AddressU  = BORDER;
	AddressV  = BORDER;
};
#endif

#if MBMB_HDR
texture2D tMBMB_HDR {
	Width  = BUFFER_WIDTH;
	Height = BUFFER_HEIGHT;
	Format = RGBA16F;
};
sampler2D sHDR {
	Texture   = tMBMB_HDR;
	MinFilter = LINEAR;
	MagFilter = LINEAR;
	MipFilter = LINEAR;
	AddressU  = CLAMP;
	AddressV  = CLAMP;
};
#endif

//Functions/////////////////////////////////////////////////////////////////////////////////////////

// https://en.wikipedia.org/wiki/Gaussian_blur#Mathematics
float gaussian1D(float x, float sigma) {
	return (1.0 / sqrt(2.0 * 3.1415 * (sigma * sigma))) * exp(-((x * x) / (2.0 * (sigma * sigma))));
}

// Better than regular clamping for a number of reasons.
// More specifically it keeps the overall 'form' of the vector,
// normal clamping distorts it.
float2 clamp_magnitude(float2 v, float2 min_max) {
	if (v.x == 0.0 && v.y == 0.0) {
		return 0.0;
	} else {
		float mag = length(v);
		return (mag < min_max.x) ? 0.0 : (v / mag) * min(mag, min_max.y);
	}
}

float3 reinhard(float3 c) {
	return c / (1.0 + c);
}

float3 inv_reinhard(float3 c, float max_c) {
	return (c / max(1.0 - c, max_c));
}

//Shader////////////////////////////////////////////////////////////////////////////////////////////

#if MBMB_HDR
float4 PS_MakeHDR(
	float4 position : SV_POSITION,
	float2 uv       : TEXCOORD
) : SV_TARGET {
	return float4(pow(tex2D(sBackBuffer, uv).rgb, fHDRBrightness), 1.0);
}
#endif

float4 PS_MBMB(
	float4 position : SV_POSITION,
	float2 uv       : TEXCOORD
) : SV_TARGET {
#if MBMB_SMOOTHING
	float2 speed = tex2Dfetch(sMouse, (int4)0).xy * fSensitivity;
#else
	float2 speed = f3MouseDelta.xy * fSensitivity;
#endif

	float2 mms = f2MinMaxSpeed;
	mms.y = mms.y <= 0.0 ? 10000.0 : mms.y;
	speed = clamp_magnitude(speed, mms);

#if MBMB_DEPTH_FLAGS > 0
	float depth = ReShade::GetLinearizedDepth(uv);
	depth = lerp(1.0, depth * fDepthInfluence, saturate(fDepthInfluence));
#endif

	// This tells the direction and how much to blur the image.
	float2 ps = ReShade::PixelSize * speed;

	float d = fDistortion;
#if MBMB_DEPTH_FLAGS & AFFECT_DISTORTION
	d *= depth;
#endif

	// Distortion stuff, makes it look like real vector motion blur.
	float2 distort = 1.0 - abs(uv - 0.5) * 2.0;
	ps *= lerp(1.0, distort.yx * d, saturate(d));

#if MBMB_DEPTH_FLAGS & AFFECT_INTENSITY
	ps = lerp(0.0, ps, depth);
#endif

#if MBMB_HDR
#define sColor sHDR
#else
#define sColor sBackBuffer
#endif

#if MBMB_GAUSSIAN
	// We'll use color.a for accumulation.
	float4 color = 0.0;

	// The usual blurring algorithm, gather various points
	// at a certain offset and then blend them.
	for (int i = -MBMB_SAMPLES / 2; i <= MBMB_SAMPLES / 2; ++i) {
		float offset = i;
		color += float4(tex2D(sColor, uv + ps * offset).rgb, 1.0) * gaussian1D(offset, fBlur_Sigma);
	}
	color.rgb /= color.a;
#else
	float3 color = 0.0;

	// Much simpler blurring, similar to box blur.
	for (int i = -MBMB_SAMPLES / 2; i <= MBMB_SAMPLES / 2; ++i)
		color += tex2D(sColor, uv + ps * i).rgb;
	color /= MBMB_SAMPLES;
#endif

#if MBMB_HDR
	color.rgb = pow(color.rgb, 1.0 / fHDRBrightness);
#endif

	return float4(color.rgb, 1.0);

#undef sColor
}

#if MBMB_SMOOTHING
float4 PS_SaveMouse(
	float4 position : SV_POSITION,
	float2 uv       : TEXCOORD
) : SV_TARGET {
	float2 mouse = f3MouseDelta.xy;
	float2 last  = tex2Dfetch(sLastMouse, (int4)0).xy;
	mouse = lerp(last, mouse, saturate(fFrameTime / fSmoothing));
	return float4(mouse, 0.0, 1.0);
}

float4 PS_SaveLast(
	float4 position : SV_POSITION,
	float2 uv       : TEXCOORD
) : SV_TARGET {
	return float4(tex2Dfetch(sMouse, (int4)0).xy, 0.0, 1.0);
}
#endif

//Technique/////////////////////////////////////////////////////////////////////////////////////////

technique MBMB {
#if MBMB_HDR
	pass MakeHDR {
		VertexShader = PostProcessVS;
		PixelShader  = PS_MakeHDR;
		RenderTarget = tMBMB_HDR;
	}
#endif
	pass MBMB {
		VertexShader    = PostProcessVS;
		PixelShader     = PS_MBMB;
		//SRGBWriteEnable = true;
	}

	#if MBMB_SMOOTHING
	pass SaveMouse {
		VertexShader = PostProcessVS;
		PixelShader  = PS_SaveMouse;
		RenderTarget = tMBMB_Mouse;
	}
	pass SaveLast {
		VertexShader = PostProcessVS;
		PixelShader  = PS_SaveLast;
		RenderTarget = tMBMB_LastMouse;
	}
	#endif
}

