	! Made settings backwards compatible with SweetFX

*/


/*---------------.
| :: Includes :: |
'---------------*/

#include "ReShade.fxh"
#include "ReShadeUI.fxh"

uniform int Monochrome_preset <
	ui_type = "combo";
	ui_label = "Preset";
	ui_tooltip = "Choose a preset";
	//ui_category = "";
	ui_items = "Custom\0"
	"Monitor or modern TV\0"
	"Equal weight\0"
	"Agfa 200X\0"
	"Agfapan 25\0"
	"Agfapan 100\0"
	"Agfapan 400\0"
	"Ilford Delta 100\0"
	"Ilford Delta 400\0"
	"Ilford Delta 400 Pro & 3200\0"
	"Ilford FP4\0"
	"Ilford HP5\0"
	"Ilford Pan F\0"
	"Ilford SFX\0"
	"Ilford XP2 Super\0"
	"Kodak Tmax 100\0"
	"Kodak Tmax 400\0"
	"Kodak Tri-X\0";
> = 0;

uniform float3 Monochrome_conversion_values < __UNIFORM_COLOR_FLOAT3
	ui_label = "Custom Conversion values";
> = float3(0.21, 0.72, 0.07);

/*
uniform bool Normalize <
	ui_label = "Normalize";
	ui_tooltip = "Normalize the coefficients?";
> = false;
*/

uniform float Monochrome_color_saturation < __UNIFORM_SLIDER_FLOAT1
	ui_label = "Saturation";
	ui_min = 0.0; ui_max = 1.0;
> = 0.0;

float3 MonochromePass(float4 vpos : SV_Position, float2 texcoord : TexCoord) : SV_Target
{
	float3 color = tex2D(ReShade::BackBuffer, texcoord).rgb;

	float3 Coefficients = float3(0.21, 0.72, 0.07);

	float3 Coefficients_array[18] = 
	{
		Monochrome_conversion_values, //Custom
		float3(0.21, 0.72, 0.07), //sRGB monitor
		float3(0.3333333, 0.3333334, 0.3333333), //Equal weight
		float3(0.18, 0.41, 0.41), //Agfa 200X
		float3(0.25, 0.39, 0.36), //Agfapan 25
		float3(0.21, 0.40, 0.39), //Agfapan 100
		float3(0.20, 0.41, 0.39), //Agfapan 400 
		float3(0.21, 0.42, 0.37), //Ilford Delta 100
		float3(0.22, 0.42, 0.36), //Ilford Delta 400
		float3(0.31, 0.36, 0.33), //Ilford Delta 400 Pro & 3200
		float3(0.28, 0.41, 0.31), //Ilford FP4
		float3(0.23, 0.37, 0.40), //Ilford HP5
		float3(0.33, 0.36, 0.31), //Ilford Pan F
		float3(0.36, 0.31, 0.33), //Ilford SFX
		float3(0.21, 0.42, 0.37), //Ilford XP2 Super
		float3(0.24, 0.37, 0.39), //Kodak Tmax 100
		float3(0.27, 0.36, 0.37), //Kodak Tmax 400
		float3(0.25, 0.35, 0.40) //Kodak Tri-X
	};

	Coefficients = Coefficients_array[Monochrome_preset];

	// Calculate monochrome
	float3 grey = dot(Coefficients, color);

	// Adjust the remaining saturation
	color = lerp(grey, color, Monochrome_color_saturation);

	// Return the result
	return saturate(color);
}

technique Monochrome
{
	pass
	{
		VertexShader = PostProcessVS;
		PixelShader = MonochromePass;
	}
}

MultiFX.fx:
/*
	MultiFX by luluco250

	A compilation of common post processing effects combined into a single pass.
*/

#include "ReShade.fxh"

//Macros/////////////////////////////////////////////////////////////////////////////////////////////////////////

#ifndef MULTIFX_DEBUG
#define MULTIFX_DEBUG 0
#endif

#ifndef MULTIFX_SRGB
#define MULTIFX_SRGB 1
#endif

#ifndef MULTIFX_CA
#define MULTIFX_CA 1
#endif

#ifndef MULTIFX_VIGNETTE
#define MULTIFX_VIGNETTE 1
#endif

#ifndef MULTIFX_FILMGRAIN
#define MULTIFX_FILMGRAIN 1
#endif

#ifndef MULTIFX_SCURVE
#define MULTIFX_SCURVE 1
#endif

#define nsin(x) (sin(x) * 0.5 + 0.5)

//Uniforms///////////////////////////////////////////////////////////////////////////////////////////////////////

#if MULTIFX_CA
uniform float3 f3CA_Intensity <
	ui_label   = "[Chromatic Aberration] Intensity";
	ui_tooltip = "Controls the scale of each color channel in the image. (Red, Green, Blue)";
	ui_type    = "drag";
	ui_min     = 0.0;
	ui_max     = 1.0;
	ui_step    = 0.001;
> = 0.0;
#endif
uniform float fVignette_Intensity <
	ui_label = "[Vignette] Opacity";
	ui_type  = "drag";
	ui_min   = 0.0;
	ui_max   = 3.0;
	ui_step  = 0.001;
> = 0.0;

uniform float2 f2Vignette_StartEnd <
	ui_label   = "[Vignette] Start/End";
	ui_tooltip = "Controls the range/contrast of vignette by defining start and end offsets.";
	ui_type    = "drag";
	ui_min     =-10.0;
	ui_max     = 10.0;
	ui_step    = 0.001;
> = float2(0.0, 1.0);

uniform float fFilmGrain_Intensity <
	ui_label = "[Film Grain] Intensity";
	ui_type  = "drag";
	ui_min   = 0.0;
	ui_max   = 1.0;
	ui_step  = 0.001;
> = 0.0;

uniform float fFilmGrain_Speed <
	ui_label = "[Film Grain] Speed";
	ui_type  = "drag";
	ui_min   = 0.0;
	ui_max   = 100.0;
	ui_step  = 0.001;
> = 1.0;

uniform float fFilmGrain_Mean <
	ui_label = "[Film Grain] Mean";
	ui_type  = "drag";
	ui_min   = 0.0;
	ui_max   = 1.0;
	ui_step  = 0.001;
> = 0.0;

uniform float fFilmGrain_Variance <
	ui_label = "[Film Grain] Variance";
	ui_type  = "drag";
	ui_min   = 0.0;
	ui_max   = 1.0;
	ui_step  = 0.001;
> = 0.5;

#if MULTIFX_DEBUG
uniform bool bFilmGrain_ShowNoise <
	ui_label = "[Film Grain] Show Noise";
> = false;
#endif

uniform float fSCurve_Intensity <
	ui_label = "[S-Curve] Intensity";
	ui_type  = "drag";
	ui_min   = 0.0;
	ui_max   = 3.0;
	ui_step  = 0.001;
> = 0.0;

uniform float fTime <source = "timer";>;
/*uniform float fDelta <source = "frametime";>;
uniform float2 f2Mouse <source = "mousepoint";>;*/

//Textures///////////////////////////////////////////////////////////////////////////////////////////////////////

sampler2D sMultiFX_BackBuffer {
	Texture = ReShade::BackBufferTex;
	#if MULTIFX_SRGB
	SRGBTexture = true;
	#endif
};

//Functions//////////////////////////////////////////////////////////////////////////////////////////////////////

float2 scale_uv(float2 uv, float2 scale, float2 center) {
	return (uv - center) * scale + center;
}

float2 scale_uv(float2 uv, float2 scale) {
	return scale_uv(uv, scale, 0.5);
}

float fmod(float a, float b) {
	float c = frac(abs(a / b)) * abs(b);
	return (a < 0.0) ? -c : c;
}

float rand(float2 uv) {
	float a = 12.9898;
	float b = 78.233;
	float c = 43758.5453;
	float dt = dot(uv, float2(a, b));
	float sn = fmod(dt, 3.1415);
	return frac(sin(sn) * c);
}

float3 blend_dodge(float3 a, float3 b, float w) {
	return lerp(a, a / max(1.0 - b, 0.0000001), w);
}

float gaussian(float z, float u, float o) {
    return (1.0 / (o * sqrt(2.0 * 3.1415))) * exp(-(((z - u) * (z - u)) / (2.0 * (o * o))));
}

float get_lum(float3 color) {
	return max(color.r, max(color.g, color.b));
}

//Effects////////////////////////////////////////////////////////////////////////////////////////////////////////

void ChromaticAberration(out float4 color, float2 uv) {
	color = float4(
		tex2D(sMultiFX_BackBuffer, scale_uv(uv, 1.0 - f3CA_Intensity.r * 0.01)).r,
		tex2D(sMultiFX_BackBuffer, scale_uv(uv, 1.0 - f3CA_Intensity.g * 0.01)).g,
		tex2D(sMultiFX_BackBuffer, scale_uv(uv, 1.0 - f3CA_Intensity.b * 0.01)).b,
		1.0
	);
}

void Vignette(inout float4 color, float2 uv) {
	float vignette = 1.0 - smoothstep(
		f2Vignette_StartEnd.x,
		f2Vignette_StartEnd.y,
		distance(uv, 0.5)
	);
	color = lerp(color, color * vignette, fVignette_Intensity);
}

void FilmGrain(inout float4 color, float2 uv) {
	float t     = fTime * 0.001 * fFilmGrain_Speed;
    float seed  = dot(uv, float2(12.9898, 78.233));
    float noise = frac(sin(seed) * 43758.5453 + t);
	noise = gaussian(noise, fFilmGrain_Mean, fFilmGrain_Variance * fFilmGrain_Variance);

    //float lum   = get_lum(color.rgb);
	//noise = smoothstep(f2FilmGrain_Curve.x, f2FilmGrain_Curve.y, noise);

	#if MULTIFX_DEBUG
	if (bFilmGrain_ShowNoise)
		color = noise;
	else
	#endif

	float3 grain = noise * (1.0 - color.rgb);
	color.rgb += grain * fFilmGrain_Intensity * 0.01;

    //color += lerp(noise, color * noise, lum) * fFilmGrain_Intensity;
}

void SCurve(inout float4 color, float2 uv) {
	color = lerp(color, smoothstep(0.0, 1.0, color), fSCurve_Intensity);
}

//Shader/////////////////////////////////////////////////////////////////////////////////////////////////////////

void PS_MultiFX(
	float4 position  : SV_POSITION,
	float2 uv        : TEXCOORD,
	out float4 color : SV_TARGET
) {
	#if MULTIFX_CA
	ChromaticAberration(color, uv);
	#else
	color = tex2D(sMultiFX_BackBuffer, uv);
	#endif
	#if MULTIFX_VIGNETTE
	Vignette(color, uv);
	#endif
	#if MULTIFX_FILMGRAIN
	FilmGrain(color, uv);
	#endif
	#if MULTIFX_SCURVE
	SCurve(color, uv);
	#endif
	color.a = 1.0;
}

//Technique//////////////////////////////////////////////////////////////////////////////////////////////////////

technique MultiFX {
	pass {
		VertexShader = PostProcessVS;
		PixelShader = PS_MultiFX;
		#if MULTIFX_SRGB
		SRGBWriteEnable = true;
		#endif
	}
}

MultiLUT.fx:
//+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// ReShade effect file
//+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
// Multi-LUT shader, using a texture atlas with multiple LUTs
// by Otis / Infuse Project.
// Based on Marty's LUT shader 1.0 for ReShade 3.0
// Copyright © 2008-2016 Marty McFly
//+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

#ifndef fLUT_TextureName
	#define fLUT_TextureName "MultiLut_atlas1.png"
#endif
#ifndef fLUT_TileSizeXY
	#define fLUT_TileSizeXY 32
#endif
#ifndef fLUT_TileAmount
	#define fLUT_TileAmount 32
#endif
#ifndef fLUT_LutAmount
	#define fLUT_LutAmount 17
#endif

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

#include "ReShadeUI.fxh"

uniform int fLUT_LutSelector < 
	ui_type = "combo";
	ui_items="Neutral\0Color1\0Color2\0Color3 (Blue oriented)\0Color4 (Hollywood)\0Color5\0Color6\0Color7\0Color8\0Cool light\0Flat & green\0Red lift matte\0Cross process\0Azure Red Dual Tone\0Sepia\0\B&W mid constrast\0\B&W high contrast\0";
	ui_label = "The LUT to use";
	ui_tooltip = "The LUT to use for color transformation. 'Neutral' doesn't do any color transformation.";
> = 0;

uniform float fLUT_AmountChroma < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.00; ui_max = 1.00;
	ui_label = "LUT chroma amount";
	ui_tooltip = "Intensity of color/chroma change of the LUT.";
> = 1.00;

uniform float fLUT_AmountLuma < __UNIFORM_SLIDER_FLOAT1
	ui_min = 0.00; ui_max = 1.00;
	ui_label = "LUT luma amount";
	ui_tooltip = "Intensity of luma change of the LUT.";
> = 1.00;

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

#include "ReShade.fxh"
texture texMultiLUT < source = fLUT_TextureName; > { Width = fLUT_TileSizeXY*fLUT_TileAmount; Height = fLUT_TileSizeXY * fLUT_LutAmount; Format = RGBA8; };
sampler	SamplerMultiLUT { Texture = texMultiLUT; };

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

void PS_MultiLUT_Apply(float4 vpos : SV_Position, float2 texcoord : TEXCOORD, out float4 res : SV_Target0)
{
	float4 color = tex2D(ReShade::BackBuffer, texcoord.xy);
	float2 texelsize = 1.0 / fLUT_TileSizeXY;
	texelsize.x /= fLUT_TileAmount;

	float3 lutcoord = float3((color.xy*fLUT_TileSizeXY-color.xy+0.5)*texelsize.xy,color.z*fLUT_TileSizeXY-color.z);
	lutcoord.y /= fLUT_LutAmount;
	lutcoord.y += (float(fLUT_LutSelector)/ fLUT_LutAmount);
	float lerpfact = frac(lutcoord.z);
	lutcoord.x += (lutcoord.z-lerpfact)*texelsize.y;

	float3 lutcolor = lerp(tex2D(SamplerMultiLUT, lutcoord.xy).xyz, tex2D(SamplerMultiLUT, float2(lutcoord.x+texelsize.y,lutcoord.y)).xyz,lerpfact);

	color.xyz = lerp(normalize(color.xyz), normalize(lutcolor.xyz), fLUT_AmountChroma) * 
	            lerp(length(color.xyz),    length(lutcolor.xyz),    fLUT_AmountLuma);

	res.xyz = color.xyz;
	res.w = 1.0;
}

//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
//
//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++


technique MultiLUT
{
	pass MultiLUT_Apply
	{
		VertexShader = PostProcessVS;
		PixelShader = PS_MultiLUT_Apply;
	}
}

