	ui_tooltip =
		"Which bloom texture to show with the 'Show Only Bloom' debug option.\n"
		"Set to -1 to view all textures blended.\n"
		"\nDefault: -1";
	ui_category = "Debug";
	ui_min = -1;
	ui_max = MaxBloomLevel;
> = -1;

#endif

#if NEO_BLOOM_DITHERING

uniform float DitherAmount
<
	__UNIFORM_DRAG_FLOAT1

	ui_label = "Amount";
	ui_tooltip =
		"Amount of dithering to apply to the bloom.\n"
		"\nDefault: 0.1";
	ui_category = "Dithering";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = 0.1;

#endif

#if NEO_BLOOM_ADAPT

uniform float FrameTime <source = "frametime";>;

#endif

//#endregion

//#region Textures

sampler BackBuffer
{
	Texture = ReShade::BackBufferTex;
	SRGBTexture = true;
};

texture NeoBloom_DownSample <pooled="true";>
{
	Width = NEO_BLOOM_TEXTURE_SIZE;
	Height = NEO_BLOOM_TEXTURE_SIZE;
	Format = RGBA16F;
	MipLevels = NEO_BLOOM_TEXTURE_MIP_LEVELS;
};
sampler DownSample
{
	Texture = NeoBloom_DownSample;
};

texture NeoBloom_AtlasA <pooled="true";>
{
	Width = BUFFER_WIDTH / NEO_BLOOM_DOWN_SCALE;
	Height = BUFFER_HEIGHT / NEO_BLOOM_DOWN_SCALE;
	Format = RGBA16F;
};
sampler AtlasA
{
	Texture = NeoBloom_AtlasA;
	AddressU = BORDER;
	AddressV = BORDER;
};

texture NeoBloom_AtlasB <pooled="true";>
{
	Width = BUFFER_WIDTH / NEO_BLOOM_DOWN_SCALE;
	Height = BUFFER_HEIGHT / NEO_BLOOM_DOWN_SCALE;
	Format = RGBA16F;
};
sampler AtlasB
{
	Texture = NeoBloom_AtlasB;
	AddressU = BORDER;
	AddressV = BORDER;
};

#if NEO_BLOOM_ADAPT

texture NeoBloom_Adapt <pooled="true";>
{
	Format = R16F;
};
sampler Adapt
{
	Texture = NeoBloom_Adapt;
	MinFilter = POINT;
	MagFilter = POINT;
	MipFilter = POINT;
};

texture NeoBloom_LastAdapt
{
	Format = R16F;
};
sampler LastAdapt
{
	Texture = NeoBloom_LastAdapt;
	MinFilter = POINT;
	MagFilter = POINT;
	MipFilter = POINT;
};

#endif

#if NEO_BLOOM_LENS_DIRT

texture NeoBloom_LensDirt
<
	source = NEO_BLOOM_LENS_DIRT_TEXTURE_NAME;
>
{
	Width = NEO_BLOOM_LENS_DIRT_TEXTURE_WIDTH;
	Height = NEO_BLOOM_LENS_DIRT_TEXTURE_HEIGHT;
};
sampler LensDirt
{
	Texture = NeoBloom_LensDirt;
};

#endif

#if NEO_BLOOM_NEEDS_LAST

texture NeoBloom_Last
{
	Width = BUFFER_WIDTH / NEO_BLOOM_GHOSTING_DOWN_SCALE;
	Height = BUFFER_HEIGHT / NEO_BLOOM_GHOSTING_DOWN_SCALE;

	#if NEO_BLOOM_GHOSTING && NEO_BLOOM_DEPTH_ANTI_FLICKER
		Format = RGBA16F;
	#else
		Format = R8;
	#endif
};
sampler Last
{
	Texture = NeoBloom_Last;
};

#if NEO_BLOOM_DEPTH

texture NeoBloom_Depth
{
	Width = BUFFER_WIDTH;
	Height = BUFFER_HEIGHT;
	Format = R8;
};
sampler Depth
{
	Texture = NeoBloom_Depth;
};

#endif

#endif

//#endregion

//#region Functions

float3 blend_bloom(float3 color, float3 bloom)
{
	float w;
	if (NormalizeBrightness)
		w = Intensity / MaxBrightness;
	else
		w = Intensity;

	switch (BloomBlendMode)
	{
		default:
			return 0.0;
		case BloomBlendMode_Mix:
			return lerp(color, bloom, log2(w + 1.0));
		case BloomBlendMode_Addition:
			return color + bloom * w * 3.0;
		case BloomBlendMode_Screen:
			return BlendScreen(color, bloom, w);
	}
}

float3 inv_tonemap_bloom(float3 color)
{
	if (MagicMode)
		return pow(abs(color), MaxBrightness * 0.01);

	return Tonemap::Reinhard::InverseOldLum(color, 1.0 / MaxBrightness);
}

float3 inv_tonemap(float3 color)
{
	if (MagicMode)
		return color;

	return Tonemap::Reinhard::InverseOld(color, 1.0 / MaxBrightness);
}

float3 tonemap(float3 color)
{
	if (MagicMode)
		return color;

	return Tonemap::Reinhard::Apply(color);
}

//#endregion

//#region Shaders

#if NEO_BLOOM_DEPTH && NEO_BLOOM_DEPTH_ANTI_FLICKER

float GetDepthPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float3 depth = ReShade::GetLinearizedDepth(uv);

	#if NEO_BLOOM_GHOSTING
		float last = tex2D(Last, uv).a;
	#else
		float last = tex2D(Last, uv).r;
	#endif

	depth = lerp(depth, last, DepthAntiFlicker);

	return depth;
}

#endif

float4 DownSamplePS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float4 color = tex2D(BackBuffer, uv);
	color.rgb = saturate(ApplySaturation(color.rgb, Saturation));
	color.rgb *= ColorFilter;
	color.rgb = inv_tonemap_bloom(color.rgb);

	#if NEO_BLOOM_DEPTH
		#if NEO_BLOOM_DEPTH_ANTI_FLICKER
			float3 depth = tex2D(Depth, uv).x;
		#else
			float3 depth = ReShade::GetLinearizedDepth(uv);
		#endif

		float is_near = smoothstep(
			depth - DepthSmoothness,
			depth + DepthSmoothness,
			DepthRange.x);

		float is_far = smoothstep(
			DepthRange.y - DepthSmoothness,
			DepthRange.y + DepthSmoothness, depth);

		float is_middle = (1.0 - is_near) * (1.0 - is_far);

		color.rgb *= lerp(1.0, DepthMultiplier.x, is_near);
		color.rgb *= lerp(1.0, DepthMultiplier.y, is_middle);
		color.rgb *= lerp(1.0, DepthMultiplier.z, is_far);
	#endif

	return color;
}

float4 SplitPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float4 color = 0.0;

	[unroll]
	for (int i = 0; i < BloomCount; ++i)
	{
		float4 rect = BloomLevels[i];
		float2 rect_uv = ScaleCoord(uv - rect.xy, 1.0 / rect.z, 0.0);
		float inbounds =
			step(0.0, rect_uv.x) * step(rect_uv.x, 1.0) *
			step(0.0, rect_uv.y) * step(rect_uv.y, 1.0);

		rect_uv = ScaleCoord(rect_uv, 1.0 + Padding * (i + 1), 0.5);

		float4 pixel = tex2Dlod(DownSample, float4(rect_uv, 0, rect.w));
		pixel.rgb *= inbounds;
		pixel.a = inbounds;

		color += pixel;
	}

	return color;
}

float4 BlurXPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float2 dir =
		PixelScale *
		float2(BUFFER_RCP_WIDTH, 0.0) *
		NEO_BLOOM_DOWN_SCALE;

	return GaussianBlur1D(AtlasA, uv, dir, Sigma, BlurSamples);
}

float4 BlurYPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float2 dir =
		PixelScale *
		float2(0.0, BUFFER_RCP_HEIGHT) *
		NEO_BLOOM_DOWN_SCALE;

	return GaussianBlur1D(AtlasB, uv, dir, Sigma, BlurSamples);
}

#if NEO_BLOOM_ADAPT

float4 CalcAdaptPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float3 color = tex2Dlod(
		DownSample,
		float4(0.5, 0.5, 0.0, NEO_BLOOM_TEXTURE_MIP_LEVELS - AdaptPrecision)
	).rgb;
	color = tonemap(color);

	float gs;
	switch (AdaptFormula)
	{
		case 0:
			gs = dot(color, 0.333);
			break;
		case 1:
			gs = max(color.r, max(color.g, color.b));
			break;
		case 2:
			gs = GetLumaGamma(color);
			break;
		case 3:
			gs = GetLumaLinear(color);
			break;
	}

	gs *= AdaptSensitivity;
	gs = AdaptUseLimits ? clamp(gs, AdaptLimits.x, AdaptLimits.y) : gs;

	float last = tex2D(LastAdapt, 0.0).r;
	gs = lerp(last, gs, saturate((FrameTime * 0.001) / max(AdaptTime, 0.001)));

	return float4(gs, 0.0, 0.0, 1.0);
}

float4 SaveAdaptPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	return tex2D(Adapt, 0.0);
}

#endif

float4 JoinBloomsPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float4 bloom = 0.0;
	float accum = 0.0;

	[unroll]
	for (int i = 0; i < BloomCount; ++i)
	{
		float4 rect = BloomLevels[i];
		float2 rect_uv = ScaleCoord(uv, 1.0 / (1.0 + Padding * (i + 1)), 0.5);
		rect_uv = ScaleCoord(rect_uv + rect.xy / rect.z, rect.z, 0.0);

		float weight = NormalDistribution(i, Mean, Variance);
		bloom += tex2D(AtlasA, rect_uv) * weight;
		accum += weight;
	}
	bloom /= accum;

	#if NEO_BLOOM_GHOSTING
		float3 last = tex2D(Last, uv).rgb;
		bloom.rgb = lerp(bloom.rgb, last.rgb, GhostingAmount);
	#endif

	return bloom;
}

#if NEO_BLOOM_NEEDS_LAST

float4 SaveLastBloomPS(
	float4 p : SV_POSITION,
	float2 uv : TEXCOORD
) : SV_TARGET
{
	float4 color = float4(0.0, 0.0, 0.0, 1.0);

	#if NEO_BLOOM_DEPTH && NEO_BLOOM_DEPTH_ANTI_FLICKER
		color = tex2D(Depth, uv).x;
	#endif

	#if NEO_BLOOM_GHOSTING
		color.rgb = tex2D(AtlasB, uv).rgb;
	#endif

	return color;
}

#endif

// As a workaround for a bug in the current ReShade DirectX 9 code generator,
// we have to return the parameters instead of using out.
// If we don't do that, the DirectX 9 half pixel offset bug is not automatically
// corrected by the code generator, which leads to a slightly blurry image.
BlendPassParams BlendVS(uint id : SV_VERTEXID)
{
	BlendPassParams p;

	PostProcessVS(id, p.p, p.uv);

	#if NEO_BLOOM_LENS_DIRT && NEO_BLOOM_LENS_DIRT_ASPECT_RATIO_CORRECTION
		float ar = BUFFER_WIDTH * BUFFER_RCP_HEIGHT;
		float ar_inv = BUFFER_HEIGHT * BUFFER_RCP_WIDTH;
		float is_horizontal = step(ar, DirtAspectRatio);
		float ratio = lerp(
			DirtAspectRatio * ar_inv,
			ar * DirtAspectRatioInv,
			is_horizontal);

		p.lens_uv = ScaleCoord(p.uv, float2(1.0, ratio), 0.5);
	#endif

	return p;
}

float4 BlendPS(BlendPassParams p) : SV_TARGET
{
	float2 uv = p.uv;

	float4 color = tex2D(BackBuffer, uv);
	color.rgb = inv_tonemap(color.rgb);

	#if NEO_BLOOM_GHOSTING
		float4 bloom = tex2D(AtlasB, uv);
	#else
		float4 bloom = JoinBloomsPS(p.p, uv);
	#endif

	#if NEO_BLOOM_DITHERING
		bloom.rgb = FXShaders::Dithering::Ordered16::Apply(
			bloom.rgb,
			uv,
			DitherAmount);
	#endif

	#if NEO_BLOOM_LENS_DIRT
		float4 dirt = tex2D(LensDirt, p.lens_uv);
		bloom.rgb = mad(dirt.rgb, bloom.rgb * LensDirtAmount, bloom.rgb);
	#endif

	#if NEO_BLOOM_DEBUG
		switch (DebugOptions)
		{
			case DebugOption_OnlyBloom:
				if (BloomTextureToShow == -1)
				{
					color.rgb = tonemap(bloom.rgb);
				}
				else
				{
					float4 rect = BloomLevels[BloomTextureToShow];
					float2 rect_uv = ScaleCoord(
						uv,
						1.0 / (1.0 + Padding * (BloomTextureToShow + 1)),
						0.5
					);

					rect_uv = ScaleCoord(rect_uv + rect.xy / rect.z, rect.z, 0.0);
					color = tex2D(AtlasA, rect_uv);
					color.rgb = tonemap(color.rgb);
				}

				return color;
			case DebugOptions_TextureAtlas:
				color = tex2D(AtlasA, uv);
				color.rgb = lerp(checkered_pattern(uv), color.rgb, color.a);
				color.a = 1.0;

				return color;

			#if NEO_BLOOM_ADAPT
				case DebugOption_Adaptation:
					color = tex2Dlod(
						DownSample,
						float4(
							uv,
							0.0,
							NEO_BLOOM_TEXTURE_MIP_LEVELS - AdaptPrecision)
					);
					color.rgb = tonemap(color.rgb);
					return color;
			#endif

			#if NEO_BLOOM_DEPTH
				case DebugOption_DepthRange:
					#if NEO_BLOOM_DEPTH_ANTI_FLICKER
						float depth = tex2D(Depth, uv).x;
					#else
						float depth = ReShade::GetLinearizedDepth(uv);
					#endif

					color.r = smoothstep(0.0, DepthRange.x, depth);
					color.g = smoothstep(DepthRange.x, DepthRange.y, depth);
					color.b = smoothstep(DepthRange.y, 1.0, depth);

					color.r *= smoothstep(
						depth - DepthSmoothness,
						depth + DepthSmoothness,
						DepthRange.x);

					color.g *= smoothstep(
						depth - DepthSmoothness,
						depth + DepthSmoothness,
						DepthRange.y);

					return color;
			#endif
		}
	#endif

	#if NEO_BLOOM_ADAPT
		float adapt = tex2D(Adapt, 0.0).r;
		float exposure = exp(AdaptExposure) / max(adapt, 0.001);
		exposure = lerp(1.0, exposure, AdaptAmount);

		if (MagicMode)
		{
			bloom.rgb = Tonemap::Uncharted2Filmic::Apply(
				bloom.rgb * exposure * 0.1);
		}

		switch (AdaptMode)
		{
			case AdaptMode_FinalImage:
				color = blend_bloom(color, bloom);
				color.rgb *= exposure;
				break;
			case AdaptMode_OnlyBloom:
				bloom.rgb *= exposure;
				color = blend_bloom(color, bloom);
				break;
		}
	#else
		if (MagicMode)
			bloom.rgb = Tonemap::Uncharted2Filmic::Apply(bloom.rgb * 10.0);

		color.rgb = blend_bloom(color.rgb, bloom.rgb);
	#endif

	if (!MagicMode)
		color.rgb = tonemap(color.rgb);

	return color;
}

//#endregion

//#region Technique

technique NeoBloom
{
	#if NEO_BLOOM_DEPTH && NEO_BLOOM_DEPTH_ANTI_FLICKER
		pass GetDepth
		{
			VertexShader = PostProcessVS;
			PixelShader = GetDepthPS;
			RenderTarget = NeoBloom_Depth;
		}
	#endif

	pass DownSample
	{
		VertexShader = PostProcessVS;
		PixelShader = DownSamplePS;
		RenderTarget = NeoBloom_DownSample;
	}
	pass Split
	{
		VertexShader = PostProcessVS;
		PixelShader = SplitPS;
		RenderTarget = NeoBloom_AtlasA;
	}
	pass BlurX
	{
		VertexShader = PostProcessVS;
		PixelShader = BlurXPS;
		RenderTarget = NeoBloom_AtlasB;
	}
	pass BlurY
	{
		VertexShader = PostProcessVS;
		PixelShader = BlurYPS;
		RenderTarget = NeoBloom_AtlasA;
	}

	#if NEO_BLOOM_ADAPT
		pass CalcAdapt
		{
			VertexShader = PostProcessVS;
			PixelShader = CalcAdaptPS;
			RenderTarget = NeoBloom_Adapt;
		}
		pass SaveAdapt
		{
			VertexShader = PostProcessVS;
			PixelShader = SaveAdaptPS;
			RenderTarget = NeoBloom_LastAdapt;
		}
	#endif

	#if NEO_BLOOM_NEEDS_LAST
		pass JoinBlooms
		{
			VertexShader = PostProcessVS;
			PixelShader = JoinBloomsPS;
			RenderTarget = NeoBloom_AtlasB;
		}
		pass SaveLastBloom
		{
			VertexShader = PostProcessVS;
			PixelShader = SaveLastBloomPS;
			RenderTarget = NeoBloom_Last;
		}
	#endif

	pass Blend
	{
		VertexShader = BlendVS;
		PixelShader = BlendPS;
		SRGBWriteEnable = true;
	}
}

//#endregion

}

NightVision.fx:
#include "ReShade.fxh"

uniform float iGlobalTime < source = "timer"; >;

float hash(in float n) { return frac(sin(n)*43758.5453123); }

float mod(float x, float y)
{
	return x - y * floor (x/y);
}

float3 PS_Nightvision(float4 pos : SV_Position, float2 uv : TEXCOORD) : SV_Target
{	
	float2 p = uv;

	float2 u = p * 2. - 1.;
	float2 n = u * float2(BUFFER_ASPECT_RATIO, 1.0);
	float3 c = tex2D(ReShade::BackBuffer, uv).xyz;

	// flicker, grain, vignette, fade in
	c += sin(hash(iGlobalTime*0.001)) * 0.01;
	c += hash((hash(n.x) + n.y) * iGlobalTime*0.001) * 0.5;
	c *= smoothstep(length(n * n * n * float2(0.0, 0.0)), 1.0, 0.4);
    c *= smoothstep(0.001, 3.5, iGlobalTime*0.001) * 1.5;

	c = dot(c, float3(0.2126, 0.7152, 0.0722)) 
	  * float3(0.2, 1.5 - hash(iGlobalTime*0.001) * 0.1,0.4);

	return c;
}

technique Nightvision {
	pass Nightvision {
		VertexShader=PostProcessVS;
		PixelShader=PS_Nightvision;
	}
}

NormalMap.fx:
//#region Includes

#include "FXShaders/Common.fxh"
#include "FXShaders/Math.fxh"

//#endregion

//#region Preprocessor Directives

#ifndef NORMAL_MAP_WIDTH
#define NORMAL_MAP_WIDTH 1024
#endif

#ifndef NORMAL_MAP_HEIGHT
#define NORMAL_MAP_HEIGHT 1024
#endif

#ifndef NORMAL_MAP_TEXTURE
#define NORMAL_MAP_TEXTURE "NormalMap.png"
#endif

//#endregion

namespace FXShaders
{

//#region Constants

static const float2 NormalResolution = float2(NORMAL_MAP_WIDTH, NORMAL_MAP_HEIGHT);
static const float2 NormalPixelSize = 1.0 / NormalResolution;
static const float NormalAspectRatio = NormalResolution.x * NormalPixelSize.y;
static const float TranslationScale = 1.0;
static const float RotationScale = 0.2;

static const int AddressMode_Repeat = 0;
static const int AddressMode_Clip = 1;
static const int AddressMode_Stretch = 2;

static const float DistortionAmountScale = 100.0;

//#endregion

//#region Uniforms

FXSHADERS_WIP_WARNING();

uniform float DistortionAmount
<
	ui_label = "Distortion Amount";
	ui_tooltip =
		"Determines the amount of distortion to apply to the image based on "
		"normal map texture.\n"
		"\nDefault: 1.0";
	ui_type = "slider";
	ui_min = -3.0;
	ui_max = 3.0;
> = 1.0;

uniform float TextureScale
<
	ui_label = "Texture Scale";
	ui_tooltip =
		"Scales the normal map texture on the screen.\n"
		"\nDefault: 6.0";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 10.0;
> = 6.0;

uniform float ZScale
<
	ui_label = "Z Scale";
	ui_tooltip =
		"Determines how much the Z axis of the normal map affects the "
		"distortion.\n"
		"\nDefault: 1.0";
	ui_type = "slider";
	ui_min = 0.0;
	ui_max = 1.0;
> = 1.0;

uniform float2 Translation
<
	ui_label = "Translation Speed";
	ui_tooltip =
		"Speed at which the normal map is moved.\n"
		"\nDefault: 0.0 0.0";
	ui_type = "slider";
	ui_min = -1.0;
	ui_max = 1.0;
> = 0.0;

uniform float Rotation
<
	ui_label = "Rotation Speed";
	ui_tooltip =
		"Speed at which the normal map is spinned.\n"
		"\nDefault: 0.0";
	ui_type = "slider";
	ui_min = -1.0;
	ui_max = 1.0;
> = 0.0;

uniform int AddressMode
<
	ui_label = "Texture Address Mode";
	ui_tooltip =
		"Determines how out of bounds coordinates of the normal map texture"
		"are rendered.\n"
		"\nDefault: Repeat";
	ui_type = "combo";
	ui_items = "Repeat\0Clip\0Stretch\0";
> = AddressMode_Repeat;

uniform float Timer <source = "timer";>;

//#endregion

//#region Textures

texture BackBufferTex : COLOR;

sampler BackBuffer
{
	Texture = BackBufferTex;
	MinFilter = LINEAR;
	MagFilter = LINEAR;
	MipFilter = LINEAR;
};

texture NormalTex <source = NORMAL_MAP_TEXTURE;>
{
	Width = NormalResolution.x;
	Height = NormalResolution.y;
};

sampler NormalRepeat
{
	Texture = NormalTex;
	AddressU = REPEAT;
	AddressV = REPEAT;
};

sampler NormalClip
{
	Texture = NormalTex;
	AddressU = BORDER;
	AddressV = BORDER;
};

sampler NormalStretch
{
	Texture = NormalTex;
};

//#endregion

//#region Functions

float2 CorrectAspect(float2 uv)
{
	// Correct the normal map aspect ratio in case it's not 1:1.
	uv = CorrectAspectRatio(uv, NormalAspectRatio, 1.0);

	// Correct the normal map aspecct ratio to cover the screen's aspect ratio.
	uv = CorrectAspectRatio(
		uv,
		NormalAspectRatio,
		GetAspectRatio());

	return uv;
}

float2 ApplyScale(float2 uv)
{
	// Apply the normal texture scale.
	return ScaleCoord(uv, TextureScale);
}

float2 ApplyRotation(float2 uv)
{
	// We'll apply the rotation with non-normalized coordinates, otherwise it
	// breaks the aspect ratio.
	uv *= NormalResolution;
	uv = RotatePoint(
		uv,
		Rotation * Timer * RotationScale,
		NormalResolution * 0.5);
	uv *= NormalPixelSize;

	return uv;
}

float2 ApplyTranslation(float2 uv)
{
	// Apply translation.
	const float2 offset =
		float2(-Translation.x, Translation.y) *
		Timer *
		TranslationScale;

	return uv + offset * NormalPixelSize;
}

float2 ApplyTransformations(float2 uv)
{
	uv = CorrectAspect(uv);
	uv = ApplyScale(uv);
	uv = ApplyRotation(uv);
	uv = ApplyTranslation(uv);

	return uv;
}

float2 ReadNormalTexture(float2 uv)
{
	uv = ApplyTransformations(uv);

	// HACK:
	//
	// Using a switch breaks, probably because the SPIR-V code is attempting to
	// optimize the call by changing the sampler dynamically, which HLSL does
	// not support.

	// TODO: Check if apply address modes programmatically is more efficient.

	float4 normal = 0.0;

	if (AddressMode == AddressMode_Repeat)
		normal = tex2D(NormalRepeat, uv);
	else if (AddressMode == AddressMode_Clip)
		normal = tex2D(NormalClip, uv);
	else if (AddressMode == AddressMode_Stretch)
		normal = tex2D(NormalStretch, uv);

	normal.xyz *= normal.a;
	normal = normal * 2.0 - 1.0;
	normal.xy *= lerp(1.0, normal.z, ZScale);

	return normal.xy;
}

//#endregion

//#region Shaders

float4 MainPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	const float2 normal = ReadNormalTexture(uv);
	const float amount = DistortionAmount * DistortionAmountScale;
	const float2 ps = GetPixelSize() * amount;
	uv += normal.xy * ps;

	return tex2D(BackBuffer, uv);
}

//#endregion

//#region Techniques

technique NormalMap
<
	ui_tooltip = "FXShaders - Distorts the image using a normal map texture.";
>
{
	pass
	{
		VertexShader = ScreenVS;
		PixelShader = MainPS;
	}
}

//#endregion

