			palette[2] = float3(0.376470588235294,0.0392156862745098,0.0117647058823529);
			palette[3] = float3(0.811764705882353,0.133333333333333,0.0549019607843137);
			palette[4] = float3(0.16078431372549,0.345098039215686,0.0352941176470588);
			palette[5] = float3(0.937254901960784,0.16078431372549,0.0705882352941176);
			palette[6] = float3(0.356862745098039,0.349019607843137,0.0431372549019608);
			palette[7] = float3(0.352941176470588,0.352941176470588,0.352941176470588);
			palette[8] = float3(0.803921568627451,0.372549019607843,0.207843137254902);
			palette[9] = float3(0.494117647058824,0.509803921568627,0.756862745098039);
			palette[10] = float3(0.305882352941176,0.623529411764706,0.0980392156862745);
			palette[11] = float3(0.792156862745098,0.509803921568627,0.364705882352941);
			palette[12] = float3(1,0.392156862745098,0.215686274509804);
			palette[13] = float3(1,0.525490196078431,0.368627450980392);
			palette[14] = float3(0.631372549019608,0.63921568627451,0.76078431372549);
			palette[15] = float3(1,0.768627450980392,0.517647058823529);
		}

		if (Nostalgia_palette == 12) // Mattel Aquarius
		{
			palette[0] = float3(0,0,0);
			palette[1] = float3(1,1,1);
			palette[2] = float3(0.494117647058824,0.0980392156862745,0.164705882352941);
			palette[3] = float3(0.764705882352941,0,0.105882352941176);
			palette[4] = float3(0.725490196078431,0.694117647058824,0.337254901960784);
			palette[5] = float3(0.784313725490196,0.725490196078431,0.0274509803921569);
			palette[6] = float3(0.231372549019608,0.592156862745098,0.180392156862745);
			palette[7] = float3(0.0274509803921569,0.749019607843137,0);
			palette[8] = float3(0.250980392156863,0.650980392156863,0.584313725490196);
			palette[9] = float3(0,0.776470588235294,0.643137254901961);
			palette[10] = float3(0.749019607843137,0.749019607843137,0.749019607843137);
			palette[11] = float3(0.513725490196078,0.152941176470588,0.564705882352941);
			palette[12] = float3(0.717647058823529,0,0.819607843137255);
			palette[13] = float3(0.0196078431372549,0.0509803921568627,0.407843137254902);
			colorCount = 14;
		}

		if (Nostalgia_palette == 13) // Gameboy
		{
			palette[0] = float3(0.0588235294117647,0.219607843137255,0.0588235294117647);
			palette[1] = float3(0.607843137254902,0.737254901960784,0.0588235294117647);
			palette[2] = float3(0.188235294117647,0.384313725490196,0.188235294117647);
			palette[3] = float3(0.545098039215686,0.674509803921569,0.0588235294117647);
			colorCount = 4;
		}


		if (Nostalgia_palette == 14) //aek16 ( http://eastfarthing.com/blog/2016-05-06-palette/ )
		{
			palette[0] 	= float3(0.247059,	0.196078,	0.682353); //
			palette[1] 	= float3(0.890196,	0.054902,	0.760784); //
			palette[2] 	= float3(0.729412,	0.666667,	1.000000); //
			palette[3] 	= float3(1.,		  1.000000,	1.      ); //White
			palette[4] 	= float3(1.000000,	0.580392,	0.615686); //
			palette[5] 	= float3(0.909804,	0.007843,	0.000000); //
			palette[6] 	= float3(0.478431,	0.141176,	0.239216); //
			palette[7] 	= float3(0.,		  0.	  ,	0.		); //Black
			palette[8] 	= float3(0.098039,	0.337255,	0.282353); //
			palette[9] 	= float3(0.415686,	0.537255,	0.152941); //
			palette[10] 	= float3(0.086275,	0.929412,	0.458824); //
			palette[11] 	= float3(0.196078,	0.756863,	0.764706); //
			palette[12] 	= float3(0.019608,	0.498039,	0.756863); //
			palette[13] 	= float3(0.431373,	0.305882,	0.137255); //
			palette[14] 	= float3(0.937255,	0.890196,	0.019608); //
			palette[15] 	= float3(0.788235,	0.560784,	0.298039); //
		}

		// :: Dither :: //

		if (Nostalgia_dither == 1) //aek16 ( http://eastfarthing.com/blog/2016-05-06-palette/ )
		{

			//Calculate grid position
			float grid_position = frac(dot(texcoord, BUFFER_SCREEN_SIZE * 0.5) + 0.25); //returns 0.25 and 0.75

			//Calculate how big the shift should be
			float dither_shift = (0.25) * (1.0 / (pow(2,2.0) - 1.0)); // 0.25 seems good both when using math and when eyeballing it. So does 0.75 btw.

			//Shift the individual colors differently, thus making it even harder to see the dithering pattern
			float3 dither_shift_RGB = float3(dither_shift, dither_shift, dither_shift); //dithering

			//modify shift acording to grid position.
			dither_shift_RGB = lerp(2.0 * dither_shift_RGB, -2.0 * dither_shift_RGB, grid_position); //shift acording to grid position.

			//shift the color by dither_shift
			//color.rgb += lerp(2.0 * dither_shift_RGB, -2.0 * dither_shift_RGB, grid_position); //shift acording to grid position.
			color.rgb += dither_shift_RGB;
		}

		// :: Color matching :: //

		float3 diff = color - palette[0]; //find the difference in color compared to color 0

		float dist = dot(diff,diff); //squared distance of difference - we don't need to calculate the square root of this

		float closest_dist = dist; //this has to be the closest distance so far as it's the first we have checked
		float3 closest_color = palette[0]; //and closest color so far is this one

		for (int i = 1 ; i < colorCount ; i++) //for colors 1 to colorCount
		{
			diff = color - palette[i]; //find the difference in color

			dist = dot(diff,diff); //squared distance of difference - we don't need to calculate the square root of this

			if (dist < closest_dist) //is the distance closer than the previously closest distance?
			{ 
				closest_dist = dist; //closest distance is now this distance
				closest_color = palette[i]; //closest color is now this color
			}
		}

		color = closest_color; //return the pixel
	}

	if (Nostalgia_scanlines == 1)
	{
		color *= frac(texcoord.y * (BUFFER_HEIGHT * 0.5)) + 0.5; //Scanlines
	}
	if (Nostalgia_scanlines == 2)
	{
		float grey  = dot(color,float(1.0/3.0));
		color = (frac(texcoord.y * (BUFFER_HEIGHT * 0.5)) < 0.25) ? color : color * ((-grey*grey+grey+grey) * 0.5 + 0.5);
	}

	return color; //return the pixel
}


/*----------------.
| :: Technique :: |
'----------------*/

technique Nostalgia
{
	pass NostalgiaPass
	{
		VertexShader = PostProcessVS;
		PixelShader = PS_Nostalgia;

		#if Nostalgia_linear == 1
			SRGBWriteEnable = true;
		#endif	

		ClearRenderTargets = false;
	}
}

Oilify.fx:
/*
	Oilify Shader for ReShade

	By: Lord of Lunacy

	This shader applies a Kuwahara filter using an optimized method for extracting the image mean and variance.

	Kuwahara filter. (2020, May 01). Retrieved October 17, 2020, from https://en.wikipedia.org/wiki/Kuwahara_filter

	Kyprianidis, J. E., Kang, H., &amp; Dã¶Llner, J. (2009). Image and Video Abstraction by Anisotropic Kuwahara Filtering.
	Computer Graphics Forum, 28(7), 1955-1963. doi:10.1111/j.1467-8659.2009.01574.x
*/
#ifndef OILIFY_SIZE
	#define OILIFY_SIZE 7
#endif
#ifndef OILIFY_ITERATIONS
	#define OILIFY_ITERATIONS 1
#endif
#define OILIFY_PASS \
		pass \
		{ \
			VertexShader = PostProcessVS;\
			PixelShader = KuwaharaPS;\
		}\

	static const float PI = 3.1415926536;
	static const float GAUSSIAN_WEIGHTS[5] = {0.095766,	0.303053,	0.20236,	0.303053,	0.095766};
	static const float GAUSSIAN_OFFSETS[5] = {-3.2979345488, -1.40919905099, 0, 1.40919905099, 3.2979345488};

namespace Oilify
{
	texture BackBuffer : COLOR;
	texture Anisotropy {Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; Format = RGBA16f;};

	sampler sBackBuffer{Texture = BackBuffer;};
	sampler sAnisotropy{Texture = Anisotropy;};

	uniform float Sharpness<
		ui_type = "slider";
		ui_label = "Sharpness";
		ui_tooltip = "Higher settings result in a sharper image, while lower values give the\n"
					"image a more simplified look.";
		ui_min = 0; ui_max = 1;
		ui_step = 0.001;
	> = 1;

	uniform float Tuning<
		ui_type = "slider";
		ui_label = "Anistropy Tuning";
		ui_tooltip = "Adjusts how elliptical the sampling can become with anisotropy\n"
					"Smaller numbers mean more elliptical. (Use this if the shader looks stretched)";
		ui_min = 0; ui_max = 4;
	> = 2;

	uniform float Scale<
		ui_type = "slider";
		ui_label = "Scale";
		ui_tooltip = "Similar to size it raises the range the effect is applied over, \n"
					"however, the number of samples remains unchanged resulting in a less, \n"
					"detailed image.";
		ui_min = 1; ui_max = 4;
	> = 1;

	// Vertex shader generating a triangle covering the entire screen
	void PostProcessVS(in uint id : SV_VertexID, out float4 position : SV_Position, out float2 texcoord : TEXCOORD)
	{
		texcoord.x = (id == 2) ? 2.0 : 0.0;
		texcoord.y = (id == 1) ? 2.0 : 0.0;
		position = float4(texcoord * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
	}

	void AnisotropyPS(float4 vpos : SV_POSITION, float2 texcoord : TEXCOORD, out float4 anisotropyData : SV_TARGET0)
	{
		float3 center = tex2D(sBackBuffer, texcoord).rgb * 255;
		float3 dx = center * GAUSSIAN_WEIGHTS[2];
		float3 dy = dx;

		[unroll]
		for(int i = 0; i < 5; i++)
		{
			if (i == 2) i++;
			float3 offsets = float3(BUFFER_RCP_WIDTH, BUFFER_RCP_HEIGHT, 0) * GAUSSIAN_OFFSETS[i];
			dx += tex2D(sBackBuffer, texcoord + offsets.xz).rgb * GAUSSIAN_WEIGHTS[i] * 255;
			dy += tex2D(sBackBuffer, texcoord + offsets.zy).rgb * GAUSSIAN_WEIGHTS[i] * 255;
		}

		float e = dot(dx, dx);
		float f = dot(dx, dy);
		float g = dot(dy, dy);
		float root = sqrt((e-g) * (e-g) + 4 * f * f);
		float2 eigenvalues = float2(e + g + root, e + g - root) / 2;

		float2 t;
		if(any(abs(float2(eigenvalues.x - e, -f)) > 1e-15))
		{
			t = (normalize((float2(eigenvalues.x - e, -f))));
		}
		else
			t = float2(1, 0);

		float anisotropy = abs((eigenvalues.y - eigenvalues.x) / (eigenvalues.x + eigenvalues.y));
		anisotropy *= anisotropy;
		anisotropy = saturate(anisotropy);
		anisotropy = max(anisotropy, 1e-15);
		anisotropyData.xyz = float3(t, anisotropy);
		anisotropyData.w = 1;
	}


	void KuwaharaPS(float4 vpos : SV_POSITION, float2 texcoord : TEXCOORD, out float3 kuwahara : SV_TARGET0)
	{
		float sharpnessMultiplier = max(1023 * pow(( 2 * Sharpness / 3) + 0.333333, 4), 1e-10);
		float3 sum[6];
		float3 squaredSum[6];
		float gaussianSum[6];
		float sampleCount[6];

		float radius = length(float2((float(OILIFY_SIZE) / 2), (float(OILIFY_SIZE) / 4)));

		float3 anistropyData = tex2D(sAnisotropy, texcoord).xyz;
		float2 t = anistropyData.xy;
		float anisotropy = anistropyData.z;
		float tuning = exp2(Tuning - 1);
		float2x2 tuningMatrix = float2x2(tuning / (anisotropy + tuning), 0,
								0, (tuning + anisotropy) / tuning);
		float2x2 rotationMatrix = float2x2(t.x, -t.y, t.y, t.x);
		float2x2 offsetMatrix = mul(rotationMatrix, tuningMatrix);
		[unroll]
		for(int i = -(OILIFY_SIZE / 2); i < ((OILIFY_SIZE + 1) / 2); i++)
		{
			[unroll]
			for(int j = -(OILIFY_SIZE / 2); j < ((OILIFY_SIZE + 1) / 2); j++)
			{
				float2 offset = float2(i, j);
				if(abs(j) % 2 != 0)
				{
					offset.y -= 0.5;
				}

				if(all(int2(i, j) == 0))
				{
					[unroll]
					for(int k = 0; k < 6; k++)
					{
						float3 color = tex2D(sBackBuffer, texcoord).rgb * sharpnessMultiplier;
						sum[k] += color;
						squaredSum[k] += color * color;
						sampleCount[k]++;
					}
				}
				else if(length(offset) <= radius)
				{
					float angle = atan2(offset.x, offset.y) + PI;
					if(angle > 5.75958653158)
					{
						angle -= 2 * PI;
					}
					float sectorOffset = (float((angle * 6) / PI) + 1) / 2;
					int sector = floor(sectorOffset);
					sectorOffset -= float(sector);
					offset *= float2(BUFFER_RCP_WIDTH, BUFFER_RCP_HEIGHT) * Scale;
					offset = mul(offset, offsetMatrix);
					float3 color = tex2D(sBackBuffer, texcoord + offset).rgb * sharpnessMultiplier;
					sum[sector] += color;
					squaredSum[sector] += color * color;
					sampleCount[sector]++;
				}
			}
		}

		float3 weightedSum = 0;
		float3 weightSum = 0;
		[unroll]
		for(int i = 0; i < 6; i++)
		{
			float3 sumSquared = sum[i] * sum[i];
			float3 mean = sum[i] / sampleCount[i];
			float3 variance = (squaredSum[i] - ((sumSquared) / sampleCount[i]));
			variance /= sampleCount[0];
			float3 weight = 1 / (1 + pow(sqrt(max(dot(variance, float3(0.299, 0.587, 0.114)), 1e-5)), 8));
			weightedSum += mean * weight;
			weightSum += weight;
		}
		kuwahara = ((weightedSum) / weightSum) / sharpnessMultiplier;
	}

	technique Oilify<ui_tooltip = "Oilify is a revised version of the anisotropic kuwahara filter,\n"
							  "which is used to create a painterly effect.\n\n"
							  "Part of Insane Shaders\n"
							  "By: Lord of Lunacy\n\n"
							  "OILIFY_SIZE: Changes the size of the filter used.\n"
							  "OILIFY_ITERATIONS: Ranges from 1 to 8.";>
	{
		pass
		{
			VertexShader = PostProcessVS;
			PixelShader = AnisotropyPS;
			RenderTarget0 = Anisotropy;
		}

		pass
		{
			VertexShader = PostProcessVS;
			PixelShader = KuwaharaPS;
		}
#if OILIFY_ITERATIONS > 1
	OILIFY_PASS
#endif
#if OILIFY_ITERATIONS > 2
	OILIFY_PASS
#endif
#if OILIFY_ITERATIONS > 3
	OILIFY_PASS
#endif
#if OILIFY_ITERATIONS > 4
	OILIFY_PASS
#endif
#if OILIFY_ITERATIONS > 5
	OILIFY_PASS
#endif
#if OILIFY_ITERATIONS > 6
	OILIFY_PASS
#endif
#if OILIFY_ITERATIONS > 7
	OILIFY_PASS
#endif	
	}
}

