		ui_tooltip = "Apply Gamma to first diffusion layer.";
	> = 0.7;

	uniform float Diffusion_1_Quality <
		ui_category = "Diffusion layer 1";
		ui_label = "Sampling quality";
		ui_type = "drag";
		ui_min = 1.00;
		ui_max = 64.00;
		ui_step = 1.0;
		ui_tooltip = "Set the quality of the first diffusion layer. Number is the divider of how many times the texture size is divided in half. Lower number = higher quality, but more processing needed. (No need to adjust this.)";
	> = 2.0;

	uniform float Diffusion_2_Amount <
		ui_category = "Diffusion layer 2";
		ui_label = "Amount";
		ui_type = "drag";
		ui_min = 0.000;
		ui_max = 1.000;
		ui_step = 0.01;
		ui_tooltip = "Adjust the amount of the second diffusion layer.";
	> = 0.2;

	uniform float Diffusion_2_Radius <
		ui_category = "Diffusion layer 2";
		ui_label = "Radius";
		ui_type = "drag";
		ui_min = 5.0;
		ui_max = 20.0;
		ui_step = 0.01;
		ui_tooltip = "Set the radius of the second diffusion layer.";
	> = 5.0;

	uniform float Diffusion_2_Gamma <
		ui_category = "Diffusion layer 2";
		ui_label = "Gamma";
		ui_type = "drag";
		ui_min = 0.02;
		ui_max = 5.0;
		ui_step = 0.01;
		ui_tooltip = "Apply Gamma to second diffusion layer.";
	> = 0.5;

	uniform float Diffusion_2_Quality <
		ui_category = "Diffusion layer 2";
		ui_label = "Sampling quality";
		ui_type = "drag";
		ui_min = 1.00;
		ui_max = 64.00;
		ui_step = 1.0;
		ui_tooltip = "Set the quality of the second diffusion layer. Number is the divider of how many times the texture size is divided in half. Lower number = higher quality, but more processing needed. (No need to adjust this.)";
	> = 16.0;

	uniform float Diffusion_3_Amount <
		ui_category = "Diffusion layer 3";
		ui_label = "Amount";
		ui_type = "drag";
		ui_min = 0.000;
		ui_max = 1.000;
		ui_step = 0.01;
		ui_tooltip = "Adjust the amount of the third diffusion layer.";
	> = 1.0;

	uniform float Diffusion_3_Radius <
		ui_category = "Diffusion layer 3";
		ui_label = "Radius";
		ui_type = "drag";
		ui_min = 5.0;
		ui_max = 20.0;
		ui_step = 0.01;
		ui_tooltip = "Set the radius of the third diffusion layer.";
	> = 7.4;

	uniform float Diffusion_3_Gamma <
		ui_category = "Diffusion layer 3";
		ui_label = "Gamma";
		ui_type = "drag";
		ui_min = 0.02;
		ui_max = 5.0;
		ui_step = 0.01;
		ui_tooltip = "Apply Gamma to third diffusion layer.";
	> = 5.0;

	uniform float Diffusion_3_Quality <
		ui_category = "Diffusion layer 3";
		ui_label = "Sampling quality";
		ui_type = "drag";
		ui_min = 1.00;
		ui_max = 64.00;
		ui_step = 1.0;
		ui_tooltip = "Set the quality of the third diffusion layer. Number is the divider of how many times the texture size is divided in half. Lower number = higher quality, but more processing needed. (No need to adjust this.)";
	> = 3.0;

	uniform int framecount < source = "framecount"; >;


	// TEXTURES
	//--------------------------------------------
	texture NoiseTex <source = "hd_noise.png"; > { Width = 1920; Height = 1080; Format = RGBA8; };
	texture prePassLayer { Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; Format = RGBA8; };
	texture blurLayerHorizontal { Width = BUFFER_WIDTH / 2; Height = BUFFER_HEIGHT / 2; Format = RGBA8; };
	texture blurLayerVertical { Width = BUFFER_WIDTH / 2; Height = BUFFER_HEIGHT / 2; Format = RGBA8; };
	texture blurLayerHorizontalMedRes { Width = BUFFER_WIDTH / 16; Height = BUFFER_HEIGHT / 16; Format = RGBA8; };
	texture blurLayerVerticalMedRes { Width = BUFFER_WIDTH / 16; Height = BUFFER_HEIGHT / 16; Format = RGBA8; };
	texture blurLayerHorizontalLoRes { Width = BUFFER_WIDTH / 64; Height = BUFFER_HEIGHT / 64; Format = RGBA8; };
	texture blurLayerVerticalLoRes { Width = BUFFER_WIDTH / 64; Height = BUFFER_HEIGHT / 64; Format = RGBA8; };


	// SAMPLERS
	//--------------------------------------------
	sampler2D NoiseSampler { Texture = NoiseTex; };
	sampler2D PFX_PrePassLayer { Texture = prePassLayer; };
	// ------- samplers for large radius blur
	sampler2D PFX_blurHorizontalLayer { Texture = blurLayerHorizontal; };
	sampler2D PFX_blurVerticalLayer { Texture = blurLayerVertical; };
	sampler2D PFX_blurHorizontalLayerMedRes { Texture = blurLayerHorizontalMedRes; };
	sampler2D PFX_blurVerticalLayerMedRes { Texture = blurLayerVerticalMedRes; };
	sampler2D PFX_blurHorizontalLayerLoRes { Texture = blurLayerHorizontalLoRes; };
	sampler2D PFX_blurVerticalLayerLoRes { Texture = blurLayerVerticalLoRes; };


	// FUNCTIONS
	//--------------------------------------------
	float AdjustableSigmoidCurve (float value, float amount) 
	{
		return value < 0.5 ? pow(value, amount) * pow(2.0, amount) * 0.5 
						   : 1.0 - pow(1.0 - value, amount) * pow(2.0, amount) * 0.5;
	}

	float Randomize (float2 coord) 
	{
		return clamp((frac(sin(dot(coord, float2(12.9898, 78.233))) * 43758.5453)), 0.0, 1.0);
	}

	float SigmoidCurve (float value) 
	{
		value = value * 2.0 - 1.0;
		return -value * abs(value) * 0.5 + value + 0.5;	
	}

	float4 BlurH (sampler2D input, float2 uv, float radius, float sampling) 
	{
		float4 avgColor = float4(0.0, 0.0, 0.0, 0.0);
		float width = 1.0 / BUFFER_WIDTH * (sampling + (sampling==0));
		float4 tapCoord = float4(0, 0, 0, 0);
		for (float x = -radius; x <= radius; x++)
		{
			float2 coordinate = uv + float2(x * width, 0.0);
			tapCoord.xy = clamp(coordinate, 0.0, 1.0); 
			float weight = SigmoidCurve(1.0 - (abs(x) / (radius + (radius==0))));
			avgColor.rgb += tex2Dlod(input, tapCoord).rgb * weight;
			avgColor.a += weight;
		}

		avgColor.rgb /= (avgColor.a + (avgColor.a==0));
		avgColor.a = 1.0;
		return avgColor;
	}

	float4 BlurV (sampler input, float2 uv, float radius, float sampling) 
	{
		float4 avgColor = float4(0.0, 0.0, 0.0, 0.0);
		float height = 1.0 / BUFFER_HEIGHT * sampling;
		float4 tapCoord = float4(0, 0, 0, 0);
		for (float y = -radius; y <= radius; y++)
		{
			float2 coordinate = uv + float2(0.0, y * height);
			tapCoord.xy = clamp(coordinate, 0.0, 1.0); 
			float weight = SigmoidCurve(1.0 - (abs(y) / (radius + (radius==0))));
			avgColor.rgb += tex2Dlod(input, tapCoord).rgb * weight;
			avgColor.a += weight;
		}

		avgColor.rgb /= (avgColor.a + (avgColor.a==0));
		avgColor.a = 1.0;
		return avgColor;
	}



	// SHADERS
	//--------------------------------------------
	void PS_PrePass (float4 pos : SV_Position, 
					 float2 uv : TEXCOORD, 
					 out float4 result : SV_Target) 
	{
		float4 A = tex2D(ReShade::BackBuffer, uv);
		A.r = pow(A.r, Gamma_R);
		A.g = pow(A.g, Gamma_G);
		A.b = pow(A.b, Gamma_B);
		A.r = AdjustableSigmoidCurve(A.r, Contrast_R);
		A.g = AdjustableSigmoidCurve(A.g, Contrast_G);
		A.b = AdjustableSigmoidCurve(A.b, Contrast_B);

		// ------- Change color weights of the final render, similar to a printed film
		A.g = A.g * 0.8 + A.b * 0.2;

		float red = clamp(A.r - A.g - A.b, 0.0, 1.0);
		float green = clamp(A.g - A.r - A.b, 0.0, 1.0);
		float blue = clamp(A.b - A.r - A.g, 0.0, 1.0);

		A = A * (1.0 - red * 0.6);
		A = A * (1.0 - green * 0.8);
		A = A * (1.0 - blue * 0.3);

		result = A;
	}


	void PS_HorizontalPass (float4 pos : SV_Position, 
							float2 uv : TEXCOORD, out float4 result : SV_Target) 
	{
		result = BlurH(PFX_PrePassLayer, uv, Diffusion_1_Radius, Diffusion_1_Quality);
	}

	void PS_VerticalPass (float4 pos : SV_Position, 
						  float2 uv : TEXCOORD, out float4 result : SV_Target) 
	{
		result = BlurV(PFX_blurHorizontalLayer, uv, Diffusion_1_Radius, Diffusion_1_Quality);
	}

	void PS_HorizontalPassMedRes (float4 pos : SV_Position, 
							float2 uv : TEXCOORD, out float4 result : SV_Target) 
	{
		result = BlurH(PFX_blurVerticalLayer, uv, Diffusion_2_Radius, Diffusion_2_Quality);
	}

	void PS_VerticalPassMedRes (float4 pos : SV_Position, 
						  float2 uv : TEXCOORD, out float4 result : SV_Target) 
	{
		result = BlurV(PFX_blurHorizontalLayerMedRes, uv, Diffusion_2_Radius, Diffusion_2_Quality);
	}

	void PS_HorizontalPassLoRes (float4 pos : SV_Position, 
							float2 uv : TEXCOORD, out float4 result : SV_Target) 
	{
		result = BlurH(PFX_blurVerticalLayerMedRes, uv, Diffusion_3_Radius, Diffusion_3_Quality);
	}

	void PS_VerticalPassLoRes (float4 pos : SV_Position, 
						  float2 uv : TEXCOORD, out float4 result : SV_Target) 
	{
		result = BlurV(PFX_blurHorizontalLayerLoRes, uv, Diffusion_3_Radius, Diffusion_3_Quality);
	}

	float4 PS_Composition (float4 vpos : SV_Position, 
							 float2 uv : TEXCOORD) : SV_Target 
	{
		// ------- Create blurred layers for lens diffusion
		float4 blurLayer;
		float4 blurLayerMedRes;
		float4 blurLayerLoRes;

		// ------- Read original image
		float4 A = tex2D(PFX_PrePassLayer, uv);
		float4 O = tex2D(ReShade::BackBuffer, uv);
		float3 rndSample = tex2D(NoiseSampler, uv).rgb;

		if (Enable_Diffusion)
		{
			// TODO enable/disable for performance >>
			blurLayer = tex2D(PFX_blurVerticalLayer, uv);
			blurLayerMedRes = tex2D(PFX_blurVerticalLayerMedRes, uv);
			blurLayerLoRes = tex2D(PFX_blurVerticalLayerLoRes, uv);

			// ------- Colorize the blur layers
			blurLayerMedRes = lerp(blurLayerMedRes, dot(0.3333, blurLayerMedRes.rgb), 0.75);
			blurLayerLoRes = lerp(blurLayerLoRes, dot(0.3333, blurLayerLoRes.rgb), 0.75);

			// ------- Set blur layer weights
			blurLayer *= Diffusion_1_Amount;
			blurLayerMedRes *= Diffusion_2_Amount;
			blurLayerLoRes *= Diffusion_3_Amount;

			blurLayer = pow(blurLayer, Diffusion_1_Gamma);
			blurLayerMedRes = pow(blurLayerMedRes, Diffusion_2_Gamma);
			blurLayerLoRes = pow(blurLayerLoRes, Diffusion_3_Gamma);

			if (Enable_Static_Dither)
			{
				float3 hd_noise = 1.0 - (rndSample * 0.01);
				blurLayer.rgb = 1.0 - hd_noise * (1.0 - blurLayer.rgb);
				blurLayerMedRes.rgb = 1.0 - hd_noise * (1.0 - blurLayerMedRes.rgb);
				blurLayerLoRes.rgb = 1.0 - hd_noise * (1.0 - blurLayerLoRes.rgb);
			}

			blurLayer = clamp(blurLayer, 0.0, 1.0);
			blurLayerMedRes = clamp(blurLayerMedRes, 0.0, 1.0);
			blurLayerLoRes = clamp(blurLayerLoRes, 0.0, 1.0);

			// ------- Screen blend the blur layers to create lens diffusion
			A.rgb = 1.0 - (1.0 - blurLayer.rgb) * (1.0 - A.rgb);
			A.rgb = 1.0 - (1.0 - blurLayerMedRes.rgb) * (1.0 - A.rgb);
			A.rgb = 1.0 - (1.0 - blurLayerLoRes.rgb) * (1.0 - A.rgb);
		}

		// ------ Compress contrast using Hard Light blending ------
		float Ag = dot(float3(0.3333, 0.3333, 0.3333), A.rgb);
		float4 C = (Ag > 0.5) ? 1 - 2 * (1 - Ag) * (1 - A) : 2 * Ag * A;
		C = pow(C, 0.6);
		A = lerp(A, C, Enable_Bleach_Bypass ? Bleach_Bypass_Amount : 0);

		// ------ Compress to TV levels if needed ------
		// A = A * 0.9373 + 0.0627;
		// ------ Create noise for dark level dither (heavy processing!) ------
		if (Enable_Dither)
		{
			float uvRnd = Randomize(rndSample.rg * framecount);
			float uvRnd2 = Randomize(rndSample.rg * framecount + 1);
			A -= tex2D(NoiseSampler, uv * uvRnd2).r * 0.04;
			A += tex2D(NoiseSampler, uv * uvRnd).r * 0.04;
		}
		return lerp(O, A, Blend_Amount);
	}

	// TECHNIQUES
	//--------------------------------------------
	technique PandaFX 
	{
		pass PreProcess	
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_PrePass;
			RenderTarget = prePassLayer;
		}

		pass HorizontalPass
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_HorizontalPass;
			RenderTarget = blurLayerHorizontal;
		}

		pass VerticalPass
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_VerticalPass;
			RenderTarget = blurLayerVertical;
		}

		pass HorizontalPassMedRes
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_HorizontalPassMedRes;
			RenderTarget = blurLayerHorizontalMedRes;
		}

		pass VerticalPassMedRes
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_VerticalPassMedRes;
			RenderTarget = blurLayerVerticalMedRes;
		}

		pass HorizontalPassLoRes
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_HorizontalPassLoRes;
			RenderTarget = blurLayerHorizontalLoRes;
		}

		pass VerticalPassLoRes
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_VerticalPassLoRes;
			RenderTarget = blurLayerVerticalLoRes;
		}

		pass CustomPass
		{
			VertexShader = PostProcessVS;
			PixelShader = PS_Composition ;
		}
	}
}

Overlay.fx:
#include "ReShade.fxh"

#ifndef OVERLAY_FILENAME
#define OVERLAY_FILENAME "Overlay.png"
#endif

#ifndef OVERLAY_FILTER
#define OVERLAY_FILTER LINEAR
#endif

#ifndef OVERLAY_WIDTH
#define OVERLAY_WIDTH BUFFER_WIDTH
#endif

#ifndef OVERLAY_HEIGHT
#define OVERLAY_HEIGHT BUFFER_HEIGHT
#endif

uniform float fOpacity <
	ui_label = "Opacity";
	ui_type = "drag";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = 1.0;

uniform float fStretch <
	ui_label = "Stretch";
	ui_type = "drag";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = 1.0;

uniform float2 f2Center <
	ui_label = "Center";
	ui_type = "drag";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.001;
> = float2(0.5, 0.5);

uniform bool bKeepAspectRatio <
	ui_label = "Keep Aspect Ratio";
> = false;

uniform bool bFollowMouse <
	ui_label = "Follow Mouse";
> = false;

uniform float2 f2Mouse <source="mousepoint";>;

static const float2 f2Resolution = float2(OVERLAY_WIDTH, OVERLAY_HEIGHT);
static const float2 f2PixelSize = 1.0 / f2Resolution;

texture tOverlay <
	source=OVERLAY_FILENAME;
> {
	Width = OVERLAY_WIDTH;
	Height = OVERLAY_HEIGHT;
};
sampler sOverlay { 
	Texture = tOverlay;
	MinFilter = OVERLAY_FILTER;
	MagFilter = OVERLAY_FILTER;
	AddressU = BORDER;
	AddressV = BORDER;
};

float2 scale_uv(float2 uv, float2 scale, float2 center) {
	return (uv - center) * scale + center;
}

float4 PS_Overlay(
	float4 pos : SV_POSITION,
	float2 uv : TEXCOORD
) : SV_TARGET {
	float2 ar = f2Resolution.x > f2Resolution.y ? float2(f2Resolution.x / f2Resolution.y, 1.0) : float2(1.0, f2Resolution.y / f2Resolution.x);
	float2 corrected = bKeepAspectRatio ? ReShade::ScreenSize * ar : ReShade::ScreenSize;
	float2 stretch = lerp(
		ReShade::ScreenSize * f2PixelSize / (bKeepAspectRatio ? 1.0 : ar),
		corrected * ReShade::PixelSize,
		fStretch
	);

	float2 mouse_pos = saturate(f2Mouse * ReShade::PixelSize);
	float2 uv_overlay;

	if (bFollowMouse)
		uv_overlay = scale_uv(
			uv - mouse_pos + 0.5, 
			stretch, 
			0.5
		);
	else
		uv_overlay = scale_uv(
			uv,
			stretch,
			float2(f2Center.x, 1.0 - f2Center.y)
		);

	float4 original = tex2D(ReShade::BackBuffer, uv);
	float4 overlay = tex2D(sOverlay, uv_overlay);

	float opacity = overlay.a * fOpacity;

	return lerp(original, overlay, opacity);
}

technique Overlay {
	pass {
		VertexShader = PostProcessVS;
		PixelShader = PS_Overlay;
	}
}

PD80/PD80_00_Base_Effects.fxh:
/*
 *  Collection of simple base effects often used across shaders by prod80
 *  Required for proper effect execution
 *  Includes [range]: exposure [-4, 4], contrast [-1, 1.5], brightness [-1, 1.5], saturation [-1, 1], vibrance[-1, 1]
 */

float3 sl( float3 c, float3 b )
{ 
    return b < 0.5f ? ( 2.0f * c * b + c * c * ( 1.0f - 2.0f * b )) :
                      ( sqrt( c ) * ( 2.0f * b - 1.0f ) + 2.0f * c * ( 1.0f - b ));
}

float getLum( in float3 x )
{
    return dot( x, float3( 0.212656, 0.715158, 0.072186 ));
}

float3 exposure( float3 res, float x )
{
    x = x < 0.0f ? x * 0.333f : x;
    return saturate( res.xyz * ( x * ( 1.0f - res.xyz ) + 1.0f ));
}

float3 con( float3 res, float x )
{
    //softlight
    float3 c = sl( res.xyz, res.xyz );
    x = ( x < 0.0f ) ? x * 0.5f : x;
    return saturate( lerp( res.xyz, c.xyz, x ));
}

float3 bri( float3 res, float x )
{
    //screen
    float3 c = 1.0f - ( 1.0f - res.xyz ) * ( 1.0f - res.xyz );
    x = ( x < 0.0f ) ? x * 0.5f : x;
    return saturate( lerp( res.xyz, c.xyz, x ));   
}

float3 sat( float3 res, float x )
{
    return saturate( lerp( getLum( res.xyz ), res.xyz, x + 1.0f ));
}

float3 vib( float3 res, float x )
{
    float4 sat = 0.0f;
    sat.xy = float2( min( min( res.x, res.y ), res.z ), max( max( res.x, res.y ), res.z ));
    sat.z = sat.y - sat.x;
    sat.w = getLum( res.xyz );
    return saturate( lerp( sat.w, res.xyz, 1.0f + ( x * ( 1.0f - sat.z ))));
}

PD80/PD80_00_Blend_Modes.fxh:
/*
 *  Blend functions across shaders by prod80
 *  Required for proper effect execution
 *  These can be used by calling the function blendmode() taking input of base, blend, blendmode, opacity
 *  The effects only operate in LDR space
 *  UI elements

    uniform int blendmode < __UNIFORM_COMBO_INT1
        ui_label = "Blendmode";
        ui_tooltip = "Description";
        ui_category = "Category";
        ui_items = "Default\0Darken\0Multiply\0Linearburn\0Colorburn\0Lighten\0Screen\0Colordodge\0Lineardodge\0Overlay\0Softlight\0Vividlight\0Linearlight\0Pinlight\0Hardmix\0Reflect\0Glow\0Hue\0Saturation\0Color\0Luminosity\0";
        > = 0;
    uniform float opacity <
        ui_label = "Opacity";
        ui_tooltip = "Description";
        ui_category = "Category";
        ui_type = "slider";
        ui_min = 0.0;
        ui_max = 1.0;
        > = 1.0;

 */

float getAvgColor( float3 col )
{
    return dot( col.xyz, float3( 0.333333f, 0.333334f, 0.333333f ));
}

// nVidia blend modes
// Source: https://www.khronos.org/registry/OpenGL/extensions/NV/NV_blend_equation_advanced.txt
float3 ClipColor( float3 color )
{
    float lum         = getAvgColor( color.xyz );
    float mincol      = min( min( color.x, color.y ), color.z );
    float maxcol      = max( max( color.x, color.y ), color.z );
    color.xyz         = ( mincol < 0.0f ) ? lum + (( color.xyz - lum ) * lum ) / ( lum - mincol ) : color.xyz;
    color.xyz         = ( maxcol > 1.0f ) ? lum + (( color.xyz - lum ) * ( 1.0f - lum )) / ( maxcol - lum ) : color.xyz;
    return color;
}

// Luminosity: base, blend
// Color: blend, base
float3 blendLuma( float3 base, float3 blend )
{
    float lumbase     = getAvgColor( base.xyz );
    float lumblend    = getAvgColor( blend.xyz );
    float ldiff       = lumblend - lumbase;
    float3 col        = base.xyz + ldiff;
    return ClipColor( col.xyz );
}

// Hue: blend, base, base
// Saturation: base, blend, base
float3 blendColor( float3 base, float3 blend, float3 lum )
{
    float minbase     = min( min( base.x, base.y ), base.z );
    float maxbase     = max( max( base.x, base.y ), base.z );
    float satbase     = maxbase - minbase;
    float minblend    = min( min( blend.x, blend.y ), blend.z );
    float maxblend    = max( max( blend.x, blend.y ), blend.z );
    float satblend    = maxblend - minblend;
    float3 color      = ( satbase > 0.0f ) ? ( base.xyz - minbase ) * satblend / satbase : 0.0f;
    return blendLuma( color.xyz, lum.xyz );
}

float3 darken(float3 c, float3 b)       { return min(c,b);}
float3 multiply(float3 c, float3 b) 	{ return c*b;}
float3 linearburn(float3 c, float3 b) 	{ return max(c+b-1.0f,0.0f);}
float3 colorburn(float3 c, float3 b)    { return b<=0.0f ? b:saturate(1.0f-((1.0f-c)/b)); }
float3 lighten(float3 c, float3 b) 		{ return max(b,c);}
float3 screen(float3 c, float3 b) 		{ return 1.0f-(1.0f-c)*(1.0f-b);}
float3 colordodge(float3 c, float3 b) 	{ return b>=1.0f ? b:saturate(c/(1.0f-b));}
float3 lineardodge(float3 c, float3 b) 	{ return min(c+b,1.0f);}
float3 overlay(float3 c, float3 b) 		{ return c<0.5f ? 2.0f*c*b:(1.0f-2.0f*(1.0f-c)*(1.0f-b));}
float3 softlight(float3 c, float3 b) 	{ return b<0.5f ? (2.0f*c*b+c*c*(1.0f-2.0f*b)):(sqrt(c)*(2.0f*b-1.0f)+2.0f*c*(1.0f-b));}
float3 vividlight(float3 c, float3 b) 	{ return b<0.5f ? colorburn(c,(2.0f*b)):colordodge(c,(2.0f*(b-0.5f)));}
float3 linearlight(float3 c, float3 b) 	{ return b<0.5f ? linearburn(c,(2.0f*b)):lineardodge(c,(2.0f*(b-0.5f)));}
float3 pinlight(float3 c, float3 b) 	{ return b<0.5f ? darken(c,(2.0f*b)):lighten(c, (2.0f*(b-0.5f)));}
float3 hardmix(float3 c, float3 b)      { return vividlight(c,b)<0.5f ? float3(0.0,0.0,0.0):float3(1.0,1.0,1.0);}
float3 reflect(float3 c, float3 b)      { return b>=1.0f ? b:saturate(c*c/(1.0f-b));}
float3 glow(float3 c, float3 b)         { return reflect(b,c);}
float3 blendhue(float3 c, float3 b)         { return blendColor(b,c,c);}
float3 blendsaturation(float3 c, float3 b)  { return blendColor(c,b,c);}
float3 blendcolor(float3 c, float3 b)       { return blendLuma(b,c);}
float3 blendluminosity(float3 c, float3 b)  { return blendLuma(c,b);}

float3 blendmode( float3 c, float3 b, int mode, float o )
{
    float3 ret;
    switch( mode )
    {
        case 0:  // Default
        { ret.xyz = b.xyz; } break;
        case 1:  // Darken
        { ret.xyz = darken( c, b ); } break;
        case 2:  // Multiply
        { ret.xyz = multiply( c, b ); } break;
        case 3:  // Linearburn
        { ret.xyz = linearburn( c, b ); } break;
        case 4:  // Colorburn
        { ret.xyz = colorburn( c, b ); } break;
        case 5:  // Lighten
        { ret.xyz = lighten( c, b ); } break;
        case 6:  // Screen
        { ret.xyz = screen( c, b ); } break;
        case 7:  // Colordodge
        { ret.xyz = colordodge( c, b ); } break;
        case 8:  // Lineardodge
        { ret.xyz = lineardodge( c, b ); } break;
        case 9:  // Overlay
        { ret.xyz = overlay( c, b ); } break;
        case 10:  // Softlight
        { ret.xyz = softlight( c, b ); } break;
        case 11: // Vividlight
        { ret.xyz = vividlight( c, b ); } break;
        case 12: // Linearlight
        { ret.xyz = linearlight( c, b ); } break;
        case 13: // Pinlight
        { ret.xyz = pinlight( c, b ); } break;
        case 14: // Hard Mix
        { ret.xyz = hardmix( c, b ); } break;
        case 15: // Reflect
        { ret.xyz = reflect( c, b ); } break;
        case 16: // Glow
        { ret.xyz = glow( c, b ); } break;
        case 17: // Hue
        { ret.xyz = blendhue( c, b ); } break;
        case 18: // Saturation
        { ret.xyz = blendsaturation( c, b ); } break;
        case 19: // Color
        { ret.xyz = blendcolor( c, b ); } break;
        case 20: // Luminosity
        { ret.xyz = blendluminosity( c, b ); } break;
    }
    return saturate( lerp( c.xyz, ret.xyz, o ));
}

PD80/PD80_00_Color_Spaces.fxh:
/*
 *  Color spaces shared across shaders by prod80
 *  Required for proper effect execution
 */

float3 HUEToRGB( in float H )
{
    return saturate( float3( abs( H * 6.0f - 3.0f ) - 1.0f,
                                  2.0f - abs( H * 6.0f - 2.0f ),
                                  2.0f - abs( H * 6.0f - 4.0f )));
}

float3 RGBToHCV( in float3 RGB )
{
    // Based on work by Sam Hocevar and Emil Persson
    float4 P         = ( RGB.g < RGB.b ) ? float4( RGB.bg, -1.0f, 2.0f/3.0f ) : float4( RGB.gb, 0.0f, -1.0f/3.0f );
    float4 Q1        = ( RGB.r < P.x ) ? float4( P.xyw, RGB.r ) : float4( RGB.r, P.yzx );
    float C          = Q1.x - min( Q1.w, Q1.y );
    float H          = abs(( Q1.w - Q1.y ) / ( 6.0f * C + 0.000001f ) + Q1.z );
    return float3( H, C, Q1.x );
}

float3 RGBToHSL( in float3 RGB )
{
    RGB.xyz          = max( RGB.xyz, 0.000001f );
    float3 HCV       = RGBToHCV(RGB);
    float L          = HCV.z - HCV.y * 0.5f;
    float S          = HCV.y / ( 1.0f - abs( L * 2.0f - 1.0f ) + 0.000001f);
    return float3( HCV.x, S, L );
}

float3 HSLToRGB( in float3 HSL )
{
    float3 RGB       = HUEToRGB(HSL.x);
    float C          = (1.0f - abs(2.0f * HSL.z - 1.0f)) * HSL.y;
    return ( RGB - 0.5f ) * C + HSL.z;
}

// Collected from
// http://lolengine.net/blog/2013/07/27/rgb-to-hsv-in-glsl
float3 RGBToHSV(float3 c)
{
    float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    float4 p = c.g < c.b ? float4(c.bg, K.wz) : float4(c.gb, K.xy);
    float4 q = c.r < p.x ? float4(p.xyw, c.r) : float4(c.r, p.yzx);

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

float3 HSVToRGB(float3 c)
{
    float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    float3 p = abs(frac(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * lerp(K.xxx, saturate(p - K.xxx), c.y);
}

// Color temperature

float3 KelvinToRGB( in float k )
{
    float3 ret;
    float kelvin     = clamp( k, 1000.0f, 40000.0f ) / 100.0f;
    if( kelvin <= 66.0f )
    {
        ret.r        = 1.0f;
        ret.g        = saturate( 0.39008157876901960784f * log( kelvin ) - 0.63184144378862745098f );
    }
    else
    {
        float t      = max( kelvin - 60.0f, 0.0f );
        ret.r        = saturate( 1.29293618606274509804f * pow( t, -0.1332047592f ));
        ret.g        = saturate( 1.12989086089529411765f * pow( t, -0.0755148492f ));
    }
    if( kelvin >= 66.0f )
        ret.b        = 1.0f;
    else if( kelvin < 19.0f )
        ret.b        = 0.0f;
    else
        ret.b        = saturate( 0.54320678911019607843f * log( kelvin - 10.0f ) - 1.19625408914f );
    return ret;
}

// sRGB to Linear RGB conversion

float3 LinearTosRGB( float3 color )
{
    float3 x = color * 12.92f;
    float3 y = 1.055f * pow(saturate(color), 1.0f / 2.4f) - 0.055f;

    float3 clr = color;
    clr.r = color.r < 0.0031308f ? x.r : y.r;
    clr.g = color.g < 0.0031308f ? x.g : y.g;
    clr.b = color.b < 0.0031308f ? x.b : y.b;

    return clr;
}

float3 SRGBToLinear( float3 color )
{
    float3 x = color / 12.92f;
    float3 y = pow(max((color + 0.055f) / 1.055f, 0.0f), 2.4f);

    float3 clr = color;
    clr.r = color.r <= 0.04045f ? x.r : y.r;
    clr.g = color.g <= 0.04045f ? x.g : y.g;
    clr.b = color.b <= 0.04045f ? x.b : y.b;

    return clr;
}

// SRGB <--> CIELAB CONVERSIONS

// Reference white D65
#define reference_white     float3( 0.95047, 1.0, 1.08883 )

// Source
// http://www.brucelindbloom.com/index.html?Eqn_RGB_to_XYZ.html

#define K_val               float( 24389.0 / 27.0 )
#define E_val               float( 216.0 / 24389.0 )

float3 pd80_xyz_to_lab( float3 c )
{
    // .xyz output contains .lab
    float3 w       = max( c / reference_white, 0.0f );
    float3 v;
    v.x            = ( w.x >  E_val ) ? pow( w.x, 1.0 / 3.0 ) : ( K_val * w.x + 16.0 ) / 116.0;
    v.y            = ( w.y >  E_val ) ? pow( w.y, 1.0 / 3.0 ) : ( K_val * w.y + 16.0 ) / 116.0;
    v.z            = ( w.z >  E_val ) ? pow( w.z, 1.0 / 3.0 ) : ( K_val * w.z + 16.0 ) / 116.0;
    return float3( 116.0 * v.y - 16.0,
                   500.0 * ( v.x - v.y ),
                   200.0 * ( v.y - v.z ));
}

float3 pd80_lab_to_xyz( float3 c )
{
    float3 v;
    v.y            = ( c.x + 16.0 ) / 116.0;
    v.x            = c.y / 500.0 + v.y;
    v.z            = v.y - c.z / 200.0;
    return float3(( v.x * v.x * v.x > E_val ) ? v.x * v.x * v.x : ( 116.0 * v.x - 16.0 ) / K_val,
                  ( c.x > K_val * E_val ) ? v.y * v.y * v.y : c.x / K_val,
                  ( v.z * v.z * v.z > E_val ) ? v.z * v.z * v.z : ( 116.0 * v.z - 16.0 ) / K_val ) *
                  reference_white;
}

float3 pd80_srgb_to_xyz( float3 c )
{
    // Source: http://www.brucelindbloom.com/index.html?Eqn_RGB_XYZ_Matrix.html
    // sRGB to XYZ (D65) - Standard sRGB reference white ( 0.95047, 1.0, 1.08883 )
    const float3x3 mat = float3x3(
    0.4124564, 0.3575761, 0.1804375,
    0.2126729, 0.7151522, 0.0721750,
    0.0193339, 0.1191920, 0.9503041
    );
    return mul( mat, c );
}

float3 pd80_xyz_to_srgb( float3 c )
{
    // Source: http://www.brucelindbloom.com/index.html?Eqn_RGB_XYZ_Matrix.html
    // XYZ to sRGB (D65) - Standard sRGB reference white ( 0.95047, 1.0, 1.08883 )
    const float3x3 mat = float3x3(
    3.2404542,-1.5371385,-0.4985314,
   -0.9692660, 1.8760108, 0.0415560,
    0.0556434,-0.2040259, 1.0572252
    );
    return mul( mat, c );
}

// Maximum value in LAB, B channel is pure blue with 107.8602... divide by 108 to get 0..1 range values
// Maximum value in LAB, L channel is pure white with 100
float3 pd80_srgb_to_lab( float3 c )
{
    float3 lab = pd80_srgb_to_xyz( c );
    lab        = pd80_xyz_to_lab( lab );
    return lab / float3( 100.0, 108.0, 108.0 );
}

float3 pd80_lab_to_srgb( float3 c )
{
    float3 rgb = pd80_lab_to_xyz( c * float3( 100.0, 108.0, 108.0 ));
    rgb        = pd80_xyz_to_srgb( max( min( rgb, reference_white ), 0.0 ));
    return saturate( rgb );
}

