SharpContrast.fx:
/*
	This sharpen filter uses a kuwahara filter to create an unsharp mask, and was originally developed from the anisotropic
	kuwahara technique that was used by my Oilify shader. Changes to this Kuwahara include, the removal of the anisotropy
	and the porting of it to a compute for the purposes of optimization and improved visuals.

	There is also an edge mask being implemented that uses a weighted minimum and maximum from the entirety of the sample
	patch to attempt to determine the size of halos that need to be masked.

	Kuwahara filter. (2020, May 01). Retrieved October 17, 2020, from https://en.wikipedia.org/wiki/Kuwahara_filter

	Kyprianidis, J. E., Kang, H., &amp; Dã¶Llner, J. (2009). Image and Video Abstraction by Anisotropic Kuwahara Filtering.
	Computer Graphics Forum, 28(7), 1955-1963. doi:10.1111/j.1467-8659.2009.01574.x
*/

#include "ReShade.fxh"

#define DIVIDE_ROUNDING_UP(n, d) uint(((n) + (d) - 1) / (d))
#ifndef SHARP_CONTRAST_SIZE
	#define SHARP_CONTRAST_SIZE 7
#endif


#undef SECTOR_COUNT

#if SHARP_CONTRAST_SIZE <= 2
	#undef SHARP_CONTRAST_SIZE
	#define SHARP_CONTRAST_SIZE 2
	#define SECTOR_COUNT 2
#elif SHARP_CONTRAST_SIZE == 3
	#define SECTOR_COUNT 3
#elif SHARP_CONTRAST_SIZE == 4
	#define SECTOR_COUNT 3
#elif SHARP_CONTRAST_SIZE == 5
	#define SECTOR_COUNT 4
#elif SHARP_CONTRAST_SIZE == 6
	#define SECTOR_COUNT 6
#elif SHARP_CONTRAST_SIZE == 7
	#define SECTOR_COUNT 7
#elif SHARP_CONTRAST_SIZE == 8
	#define SECTOR_COUNT 8
#elif SHARP_CONTRAST_SIZE == 9
	#define SECTOR_COUNT 9
#elif SHARP_CONTRAST_SIZE == 10
	#define SECTOR_COUNT 13
#elif SHARP_CONTRAST_SIZE >= 11
	#undef SHARP_CONTRAST_SIZE
	#define SHARP_CONTRAST_SIZE 11
	#define SECTOR_COUNT 15
#endif

#ifndef SHARP_CONTRAST_FASTER_COMPILE
	#define SHARP_CONTRAST_FASTER_COMPILE 1
#endif

#if SHARP_CONTRAST_FASTER_COMPILE == 0 && SHARP_CONTRAST_SIZE < 10
	#define SAMPLES_PER_THREAD uint2(2, 2)
#else
	#define SAMPLES_PER_THREAD uint2(1, 1)
#endif

#define SAMPLES_PER_THREAD_COUNT (SAMPLES_PER_THREAD.x * SAMPLES_PER_THREAD.y)

#if SHARP_CONTRAST_SIZE > 7
	#define GROUP_SIZE uint2(16, 16)
#else
	#define GROUP_SIZE uint2(8, 8)
#endif

#define GROUP_COUNT (GROUP_SIZE.x * GROUP_SIZE.y)
#define GROUP_SAMPLE_SIZE ((GROUP_SIZE * SAMPLES_PER_THREAD) + (SHARP_CONTRAST_SIZE / 2).xx * 2)
#define GROUP_SAMPLE_COUNT (GROUP_SAMPLE_SIZE.x * GROUP_SAMPLE_SIZE.y)
#define INTERPOLATED_SAMPLE_SIZE (GROUP_SAMPLE_SIZE - 1)
#define INTERPOLATED_SAMPLE_COUNT (INTERPOLATED_SAMPLE_SIZE.x * INTERPOLATED_SAMPLE_SIZE.y)
#define ARRAY_INDEX(X, Y, SAMPLE_SIZE) uint((X) + (Y) * (SAMPLE_SIZE.x))
#define ARRAY_COORD(INDEX, SAMPLE_SIZE) uint2(INDEX % SAMPLE_SIZE.x, INDEX / SAMPLE_SIZE.x)

#if (((__RENDERER__ >= 0xb000 && __RENDERER__ < 0x10000) || (__RENDERER__ >= 0x14300)) && __RESHADE__ >=40800)

	#define COMPUTE 1
#else
	#define COMPUTE 0
#endif

#define VULKAN 0x20000
#define NVIDIA 0x10DE



static const float PI = 3.1415926536;
static const float GAUSSIAN_WEIGHTS[5] = {0.095766,	0.303053,	0.20236,	0.303053,	0.095766};
static const float GAUSSIAN_OFFSETS[5] = {-3.2979345488, -1.40919905099, 0, 1.40919905099, 3.2979345488};

#if COMPUTE	
namespace SharpContrast
{
	texture BackBuffer : COLOR;
	texture Luma<pooled = true;>{Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; Format = R8;};
	texture Temp<pooled = true;>{Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; Format = R8;};


	sampler sBackBuffer{Texture = BackBuffer;};
	sampler sLuma {Texture = Luma;};
	sampler sTemp {Texture = Temp;};

	storage wLuma {Texture = Luma;};
	storage wTemp {Texture = Temp;};

	uniform float SharpenStrength<
		ui_type = "slider";
		ui_label = "Strength";
		ui_tooltip = "Strength of the sharpen.";
		ui_min = 0; ui_max = 1;
		ui_step = 0.001;
	> = 0.667;

	uniform float EdgeBias<
		ui_type = "slider";
		ui_label = "Edge Contrast";
		ui_tooltip = "Changes how much contrast and coarseness there is near edges.";
		ui_min = 0; ui_max = 1;
		ui_step = 0.001;
	> = 1;

	uniform float EdgeFloor<
		ui_type = "slider";
		ui_label = "Edge Floor";
		ui_tooltip = "Amount of sharpening allowed on edges.";
		ui_min = 0; ui_max = 1;
		ui_step = 0.001;
	> = 0;	

	uniform bool GammaCorrect<
		ui_label = "Use Linear Color Gamut";
		ui_tooltip = "Changes whether the sharpen is applied on a linear\n"
					 "or standard color gamut.";
	> = true;

	uniform bool EnableDepth<
		ui_category = "Depth Settings";
		ui_label = "Enable Depth Settings";
		ui_tooltip = "This setting must be enabled to be able to adjust the Depth Curve \n"
					"or enable the Mask Sky option.";
	> = false;

	uniform float DepthCurve<
		ui_type = "slider";
		ui_label = "Depth Curve";
		ui_category = "Depth Settings";
		ui_tooltip = "Adjusts how the sharpen fades with depth, lower values mean a shorter fadeout distance.";
		ui_min = 0; ui_max = 1;
		ui_step = 0.001;
	> = 1;

	uniform bool MaskSky<
		ui_category = "Depth Settings";
		ui_label = "Mask Sky";
		ui_tooltip = "This setting prevents the sky from having the sharpen applied.";
	> = true;


	uniform int Debug<
		ui_type = "combo";
		ui_items = "None\0Masking\0Sharpen\0";
		ui_label = "Debug View";
		ui_category = "Debug";
		ui_tooltip = "Masking: Shows the regions where the sharpen is having its application limited.\n"
					 "Sharpen: Shows the sharpen that's being applied to the image.";
	> = 0;

	void LumaCS(uint3 id : SV_DispatchThreadID)
	{
		float4 r = tex2DgatherR(sBackBuffer, (float2(id.xy * 2) + 0.5)/float2(BUFFER_WIDTH, BUFFER_HEIGHT));
		float4 g = tex2DgatherG(sBackBuffer, (float2(id.xy * 2) + 0.5)/float2(BUFFER_WIDTH, BUFFER_HEIGHT));
		float4 b = tex2DgatherB(sBackBuffer, (float2(id.xy * 2) + 0.5)/float2(BUFFER_WIDTH, BUFFER_HEIGHT));

		float4 luma;
		luma.x = dot(float3(r.x, g.x, b.x), float3(0.299, 0.587, 0.114));
		luma.y = dot(float3(r.y, g.y, b.y), float3(0.299, 0.587, 0.114));
		luma.z = dot(float3(r.z, g.z, b.z), float3(0.299, 0.587, 0.114));
		luma.w = dot(float3(r.w, g.w, b.w), float3(0.299, 0.587, 0.114));

		tex2Dstore(wLuma, id.xy * 2 + int2(0, 1), luma.xyzw);
		tex2Dstore(wLuma, id.xy * 2 + int2(1, 1), luma.yyyy);
		tex2Dstore(wLuma, id.xy * 2 + int2(1, 0), luma.zzzz);
		tex2Dstore(wLuma, id.xy * 2 + int2(0, 0), luma.wwww);
	}

	groupshared float samples[GROUP_SAMPLE_COUNT];
	groupshared uint throwAway;
	void KuwaharaSharpCS(uint3 id : SV_DispatchThreadID, uint3 tid : SV_GroupThreadID)
	{
		uint2 cornerCoord = (id.xy - tid.xy) * SAMPLES_PER_THREAD;
		//uint groupIndex = ARRAY_INDEX(tid.x, tid.y, GROUP_SIZE);
		float sharpnessMultiplier = max(1023 * pow(( 2 * EdgeBias / 3) + 0.333333, 4), 1e-10);
		[unroll]
		for(int j = tid.y * 2; j < GROUP_SAMPLE_SIZE.y; j += GROUP_SIZE.y * 2)
		{
			[unroll]
			for(int i = tid.x * 2; i < GROUP_SAMPLE_SIZE.x; i += GROUP_SIZE.x * 2)
			{
				float2 sampleCoord = (cornerCoord) + int2(i, j) - (SHARP_CONTRAST_SIZE / 2).xx;

				sampleCoord += 0.5;
				sampleCoord = (sampleCoord < 0) ? abs(sampleCoord) : 
							  (sampleCoord > float2(BUFFER_WIDTH, BUFFER_HEIGHT)) ? float2(BUFFER_WIDTH, BUFFER_HEIGHT) - (sampleCoord - float2(BUFFER_WIDTH, BUFFER_HEIGHT)) : sampleCoord;

				sampleCoord /= float2(BUFFER_WIDTH, BUFFER_HEIGHT);
				//sampleCoord /= 2;
				float4 r = tex2DgatherR(sLuma, sampleCoord);

				//approximate gamma correction
				if(GammaCorrect)
				{
					r *= r;
				}

				r *= sharpnessMultiplier;


				int arrayIndex = ARRAY_INDEX(i, j, GROUP_SAMPLE_SIZE);

				samples[arrayIndex + GROUP_SAMPLE_SIZE.x] = r.x;
				samples[arrayIndex + GROUP_SAMPLE_SIZE.x + 1] = r.y;
				samples[arrayIndex + 1] = r.z;
				samples[arrayIndex] = r.w;
			}
		}
		barrier();

		[unroll]
		for(int k = 0; k < SAMPLES_PER_THREAD_COUNT; k++)
		{
			float sum[SECTOR_COUNT];
			float squaredSum[SECTOR_COUNT];
			float sampleCount[SECTOR_COUNT];
			float maximum = 0;
			float minimum = sharpnessMultiplier;
			float center;
			uint2 coord = tid.xy * SAMPLES_PER_THREAD;
			coord.x += k % SAMPLES_PER_THREAD.x;
			coord.y += k / SAMPLES_PER_THREAD.y;


			[unroll]
			for(int i = -(SHARP_CONTRAST_SIZE/2); i <= (SHARP_CONTRAST_SIZE/2); i++)
			{
				[unroll]
				for(int j = -(SHARP_CONTRAST_SIZE/2); j <= (SHARP_CONTRAST_SIZE/2); j++)
				{
					[flatten]
					if(all(int2(i, j) == 0))
					{
						uint arrayIndex = ARRAY_INDEX(coord.x + (SHARP_CONTRAST_SIZE/2), coord.y + (SHARP_CONTRAST_SIZE/2), GROUP_SAMPLE_SIZE);
						float luma = samples[arrayIndex];
						center = luma * rcp(sharpnessMultiplier);
						maximum = max(maximum, luma);
						minimum = min(minimum, luma);
						[unroll]
						for(int i = 0; i < SECTOR_COUNT; i++)
						{
							sum[i] += luma;
							squaredSum[i] += luma * luma;
							sampleCount[i]++;
						}
					}
					else
					{
						float angle = atan2(float(j), float(i)) + PI;
						uint sector = float((angle * SECTOR_COUNT) / (PI * 2)) % SECTOR_COUNT;
						uint arrayIndex = ARRAY_INDEX(i + coord.x + (SHARP_CONTRAST_SIZE/2), j + coord.y + (SHARP_CONTRAST_SIZE/2), GROUP_SAMPLE_SIZE);
						float luma = samples[arrayIndex];
						float centerDistance = length(float2(i, j));
						maximum = max(maximum, luma * rcp((centerDistance)));
						minimum = min(minimum, luma * (centerDistance));
						sum[sector] += luma;
						squaredSum[sector] += luma * luma;
						sampleCount[sector]++;
					}
				}
			}
			float edgeMultiplier = (max((1-(maximum - minimum) * rcp(maximum)), 1e-5));
			edgeMultiplier = edgeMultiplier * (1 - EdgeFloor) + EdgeFloor;

			float weightedSum = 0;
			float weightSum = 0;
			uint count = 0;
			[unroll]
			for(int i = 0; i < SECTOR_COUNT; i++)
			{
				float sumSquared = sum[i] * sum[i];
				float mean = sum[i] / sampleCount[i];
				float variance = (squaredSum[i] - ((sumSquared) / sampleCount[i]));
				variance /= sampleCount[i];

				float weight = max(/*dot(variance, float3(0.299, 0.587, 0.114))*/ variance, 1e-5);
				weight *= weight;
				weight *= weight;
				weight = rcp(1 + weight);

				weightedSum += mean * weight;
				weightSum += weight;
			}

			float kuwahara = ((weightedSum) / weightSum) / sharpnessMultiplier;


			if(Debug == 1) kuwahara = edgeMultiplier;
			else kuwahara = center + (center - kuwahara) * SharpenStrength * edgeMultiplier * 1.5;
			if(GammaCorrect) kuwahara = sqrt(kuwahara);
			tex2Dstore(wTemp, cornerCoord + coord, kuwahara);
		}
	}

	void OutputPS(float4 vpos : SV_POSITION, float2 texcoord : TEXCOORD, out float4 output : SV_TARGET0)
	{
		float y = tex2D(sTemp, texcoord).x;
		float3 color = tex2D(sBackBuffer, texcoord).rgb;
		float cb = dot(color, float3(-0.168736, -0.331264, 0.5));
		float cr = dot(color, float3(0.5, -0.418688, -0.081312));
		float luma = dot(color, float3(0.299, 0.587, 0.114));


		output.r = dot(float2(y, cr), float2(1, 1.402));//y + 1.402 * cr;
		output.g = dot(float3(y, cb, cr), float3(1, -0.344135, -0.714136));
		output.b = dot(float2(y, cb), float2(1, 1.772));//y + 1.772 * cb;
		output.a = 1;

		float depthCurve = 1;
		if(EnableDepth)
		{
			float depth = ReShade::GetLinearizedDepth(texcoord);
			depthCurve = lerp(0, 1, 1/max(exp(depth * (1 - DepthCurve) * 3), 0.0001));
			if(MaskSky && depth > 0.999) depthCurve = 0;
			output = lerp(color.rgbr, output, depthCurve);
		}

		if(Debug == 1) output = y * depthCurve;
		else if(Debug == 2)
		{
			output = (color.xyzx - output) + 0.5;
		}

	}

	technique SharpContrast< ui_tooltip =     "SharpContrast is a sharpen that takes into acount a wider screen area,\n"
						  "than most sharpen shaders, while also attempting to avoid crossing contrast boundries, \n"
						  "giving it a unique look.\n\n"
						  "Part of Insane Shaders\n"
						  "By: Lord of Lunacy\n\n"
						  "SHARP_CONTRAST_SIZE: Changes the size of the filter being used.\n"
						  "\t\t Set lower for more performance.\n"
						  "SHARP_CONTRAST_FASTER_COMPILE: Set to 0 for a slight performance increase,\n"
						  "\t\t at the expense of a longer compile time.";
	>
	{	
		pass
		{
			ComputeShader = LumaCS<8, 8>;
			DispatchSizeX = DIVIDE_ROUNDING_UP(BUFFER_WIDTH, 16);
			DispatchSizeY = DIVIDE_ROUNDING_UP(BUFFER_HEIGHT, 16);
		}
		pass
		{
			ComputeShader = KuwaharaSharpCS<GROUP_SIZE.x, GROUP_SIZE.y>;
			DispatchSizeX = DIVIDE_ROUNDING_UP(BUFFER_WIDTH, (SAMPLES_PER_THREAD.x * GROUP_SIZE.x));
			DispatchSizeY = DIVIDE_ROUNDING_UP(BUFFER_HEIGHT, (SAMPLES_PER_THREAD.y * GROUP_SIZE.y));
		}

		pass
		{
			VertexShader = PostProcessVS;
			PixelShader = OutputPS;
		}
	}
}

#endif

Sketch.fx:
//#region Preprocessor

#define RESHADE_BACK_BUFFER_SAMPLER_OPTIONS \
	SRGBTexture = false; /*\
	MinFilter = POINT; \
	MagFilter = POINT; \
	MipFilter = POINT;*/

#define RESHADE_DEPTH_BUFFER_SAMPLER_OPTIONS \
	MinFilter = POINT; \
	MagFilter = POINT; \
	MipFilter = POINT;

#include "ReShade.fxh"
#include "ReShadeUI.fxh"

#ifndef SKETCH_USE_PATTERN_TEXTURE
#define SKETCH_USE_PATTERN_TEXTURE 0
#endif

#ifndef SKETCH_PATTERN_TEXTURE_NAME
#define SKETCH_PATTERN_TEXTURE_NAME "Sketch_Shadow.png"
#endif

#ifndef SKETCH_PATTERN_TEXTURE_SIZE
#define SKETCH_PATTERN_TEXTURE_SIZE 1024
#endif

#ifndef SKETCH_SMOOTH
#define SKETCH_SMOOTH 1
#endif

#ifndef SKETCH_SMOOTH_SAMPLES
#define SKETCH_SMOOTH_SAMPLES 5
#endif

#ifndef SKETCH_DEBUG
#define SKETCH_DEBUG 0
#endif

//#endregion

//#region Constants

static const int SmoothingSamples = SKETCH_SMOOTH_SAMPLES;
static const float SmoothingSamplesInv = 1.0 / SmoothingSamples;
static const float SmoothingSamplesHalf = SmoothingSamples / 2;

static const float2 ZeroOne = float2(0.0, 1.0);

#if SKETCH_USE_PATTERN_TEXTURE

static const float2 ShadowSize = SKETCH_PATTERN_TEXTURE_SIZE;
static const float2 ShadowPixelSize = 1.0 / ShadowSize;

#endif

#if SKETCH_DEBUG

static const int DebugOptions_None = 0;
static const int DebugOptions_ShowRGBPalette = 1;
static const int DebugOptions_ShowSmoothing = 2;

#endif

//#endregion

//#region Textures

sampler SRGBBackBuffer
{
	Texture = ReShade::BackBufferTex;
	SRGBTexture = true;
};

#if SKETCH_USE_PATTERN_TEXTURE

texture Sketch_Shadow <source = SKETCH_PATTERN_TEXTURE_NAME;>
{
	Width = SKETCH_PATTERN_TEXTURE_SIZE;
	Height = SKETCH_PATTERN_TEXTURE_SIZE;
};

sampler Shadow
{
	Texture = Sketch_Shadow;
	AddressU = REPEAT;
	AddressV = REPEAT;
};

#endif

//#endregion

//#region Uniforms

uniform float4 PatternColor
<
	__UNIFORM_COLOR_FLOAT4

	ui_label = "Pattern Color";
	ui_tooltip = "Default: 255 255 255 16";
> = float4(255, 255, 255, 16) / 255;

uniform float2 PatternRange
<
	__UNIFORM_DRAG_FLOAT2

	ui_label = "Pattern Range";
	ui_tooltip = "Default: 0.0 0.5";
	ui_min = 0.0;
	ui_max = 1.0;
	ui_step = 0.01;
> = float2(0.0, 0.5);

uniform float OutlineThreshold
<
	__UNIFORM_DRAG_FLOAT1

	ui_label = "Outline Threshold";
	ui_tooltip = "Default: 0.01";
	ui_min = 0.001;
	ui_max = 0.1;
	ui_step = 0.001;
> = 0.01;

uniform float Posterization
<
	__UNIFORM_DRAG_FLOAT1

	ui_tooltip = "Default: 5";
	ui_min = 1;
	ui_max = 255;
	ui_step = 1;
> = 5;

#if SKETCH_SMOOTH

uniform float SmoothingScale
<
	__UNIFORM_SLIDER_FLOAT1

	ui_label = "Smoothing Scale";
	ui_tooltip = "Default: 1.0";
	ui_min = 1.0;
	ui_max = 10.0;
	ui_step = 0.01;
> = 1.0;

#endif

#if SKETCH_DEBUG

uniform int DebugOptions
<
	__UNIFORM_COMBO_INT1

	ui_label = "Debug Options";
	ui_tooltip = "Default: None";
	ui_items = "None\0Show RGB Palette\0Show Smoothing\0";
> = 0;

#endif

//#endregion

//#region Functions

float get_depth(float2 uv)
{
	return ReShade::GetLinearizedDepth(uv);
}

float3 get_normals(float2 uv)
{
	float3 ps = float3(ReShade::PixelSize, 0.0);

	float3 normals;
	normals.x = get_depth(uv - ps.xz) - get_depth(uv + ps.xz);
	normals.y = get_depth(uv + ps.zy) - get_depth(uv - ps.zy);
	normals.z = get_depth(uv);

	normals.xy = abs(normals.xy) * 0.5 * ReShade::ScreenSize;
	normals = normalize(normals);

	return normals;
}

float get_outline(float2 uv)
{
	float3 normals = get_normals(uv);

	float outline = dot(normals, float3(0.0, 0.0, 1.0));
	outline = step(OutlineThreshold, outline);

	return outline;
}

float get_pattern(float2 uv)
{
	#if SKETCH_USE_PATTERN_TEXTURE
		uv.x *= ShadowPixelSize.x * ReShade::ScreenSize.y;

		float shadow = tex2D(Shadow, uv).a;
		shadow *= 10.0;

		return shadow;
	#else
		float x = uv.x + uv.y;
		x = abs(x);
		x %= 0.0125;
		x /= 0.0125;
		x = abs((x - 0.5) * 2.0);
		x = step(0.5, x);

		return x;
	#endif
}

float3 test_palette(float3 color, float2 uv)
{
	float2 bw = float2(1.0, 0.0);
	uv.y = 1.0 - uv.y;
	uv.y *= 20.0;

	return (uv.y < 0.333)
		? uv.x * bw.xyy
		: (uv.y < 0.666)
			? uv.x * bw.yxy
			: (uv.y < 1.0)
				? uv.x * bw.yyx
				: color;
}

float3 cel_shade(float3 color, out float gray)
{
	gray = dot(color, 0.333);
	color -= gray;

	gray *= Posterization;
	gray = round(gray);
	gray /= Posterization;

	color += gray;
	return color;
}

#if SKETCH_SMOOTH

float3 blur_old(sampler s, float2 uv, float2 dir)
{
	dir *= SmoothingScale;

	uv -= SmoothingSamplesHalf * dir;
	float3 color = tex2D(s, uv).rgb;

	[unroll]
	for (int i = 1; i < SmoothingSamples; ++i)
	{
		uv += dir;
		color += tex2D(s, uv).rgb;
	}

	color *= SmoothingSamplesInv;
	return color;
}

float3 blur_depth_threshold(sampler s, float2 uv, float2 dir)
{
	dir *= SmoothingScale;

	float depth = get_depth(uv);

	uv -= SmoothingSamplesHalf * dir;
	float4 color = 0.0;

	[unroll]
	for (int i = 0; i < SmoothingSamples; ++i)
	{
		float z = get_depth(uv);
		if (abs(z - depth) < 0.001)
			color += float4(tex2D(s, uv).rgb, 1.0);

		uv += dir;
	}

	color.rgb /= color.a;
	return color.rgb;
}

float3 blur(sampler s, float2 uv, float2 dir)
{
	dir *= SmoothingScale;

	float3 center = tex2D(s, uv).rgb;

	uv -= SmoothingSamplesHalf * dir;
	float4 color = 0.0;

	[unroll]
	for (int i = 0; i < SmoothingSamples; ++i)
	{
		float3 pixel = tex2D(s, uv).rgb;
		float delta = dot(1.0 - abs(pixel - center), 0.333);

		if (delta > 0.9		)
			color += float4(pixel, 1.0);
	}

	color.rgb /= color.a;
	return color.rgb;
}

#endif

//#endregion

//#region Shaders

#if SKETCH_SMOOTH

float4 BlurXPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float2 dir = float2(BUFFER_RCP_WIDTH, 0.0);
	float3 color = blur(SRGBBackBuffer, uv, dir);
	return float4(color, 1.0);
}

float4 BlurYPS(float4 p : SV_POSITION, float2 uv : TEXCOORD) : SV_TARGET
{
	float2 dir = float2(0.0, BUFFER_RCP_HEIGHT);
	float3 color = blur(ReShade::BackBuffer, uv, dir);
	return float4(color, 1.0);
}

#endif

void MainVS(
	uint id : SV_VERTEXID,
	out float4 p : SV_POSITION,
	out float2 uv : TEXCOORD0,
	out float2 pattern_uv : TEXCOORD1)
{
	PostProcessVS(id, p, uv);

	pattern_uv = uv;
	pattern_uv.x *= ReShade::AspectRatio;
}

float4 MainPS(
	float4 p : SV_POSITION,
	float2 uv : TEXCOORD0,
	float2 pattern_uv : TEXCOORD1) : SV_TARGET
{
	float4 color = tex2D(ReShade::BackBuffer, uv);

	#if SKETCH_DEBUG
		switch (DebugOptions)
		{
			case DebugOptions_ShowSmoothing:
				return color;
			case DebugOptions_ShowRGBPalette:
				color.rgb = test_palette(color.rgb, uv);
				break;
		}
	#endif

	float gray;
	color.rgb = cel_shade(color.rgb, gray);

	float pattern = get_pattern(pattern_uv);
	pattern *= 1.0 - smoothstep(PatternRange.x, PatternRange.y, gray);
	pattern *= (1.0 - gray) * PatternColor.a;
	color.rgb = lerp(color.rgb, PatternColor.rgb, pattern);

	float outline = get_outline(uv);
	color.rgb *= outline;

	return color;
}

//#endregion

//#region Technique

technique Sketch
{
	#if SKETCH_SMOOTH
		pass BlurX
		{
			VertexShader = PostProcessVS;
			PixelShader = BlurXPS;
		}
		pass BlurY
		{
			VertexShader = PostProcessVS;
			PixelShader = BlurYPS;
			SRGBWriteEnable = true;
		}
	#endif
	pass Main
	{
		VertexShader = MainVS;
		PixelShader = MainPS;
	}
}

//#endregion

SlitScan.fx:
/*-----------------------------------------------------------------------------------------------------*/
/* Slit Scan Shader - by Radegast Stravinsky of Ultros.                                               */
/* There are plenty of shaders that make your game look amazing. This isn't one of them.               */
/*-----------------------------------------------------------------------------------------------------*/
#include "ReShade.fxh"
#include "Include/SlitScan.fxh"

texture texColorBuffer: COLOR;

texture ssTexture {
    Height = BUFFER_HEIGHT;
    Width = BUFFER_WIDTH;
};

sampler samplerColor {
    Texture = texColorBuffer;

    Width = BUFFER_WIDTH;
    Height = BUFFER_HEIGHT;
    Format = RGBA16;

};

sampler ssTarget {
    Texture = ssTexture;

    AddressU = WRAP;
    AddressV = WRAP;
    AddressW = WRAP;

    Height = BUFFER_HEIGHT;
    Width = BUFFER_WIDTH;
    Format = RGBA16;
};


// Vertex Shader
void FullScreenVS(uint id : SV_VertexID, out float4 position : SV_Position, out float2 texcoord : TEXCOORD0)
{

    if (id == 2)
        texcoord.x = 2.0;
    else
        texcoord.x = 0.0;

    if (id == 1)
        texcoord.y  = 2.0;
    else
        texcoord.y = 0.0;

    position = float4( texcoord * float2(2, -2) + float2(-1, 1), 0, 1);
};

void SlitScan(float4 pos : SV_Position, float2 texcoord : TEXCOORD0, out float4 color : SV_TARGET)
{
    float4 col_pixels =  tex2D(samplerColor, float2(x_col, texcoord.y));
    const float pix_w =  scan_speed * BUFFER_RCP_WIDTH;

    float slice_to_fill = (anim_rate * pix_w) % 1;

    float4 cols = tex2Dfetch(ssTarget, texcoord);
    float4 col_to_write = tex2Dfetch(ssTarget, texcoord);
    if(texcoord.x >= slice_to_fill - pix_w && texcoord.x <= slice_to_fill + pix_w)
        col_to_write.rgba = col_pixels.rgba;
    else
        discard;
    color = col_to_write;
};

void SlitScanPost(float4 pos : SV_Position, float2 texcoord : TEXCOORD0, out float4 color : SV_TARGET)
{
    const float depth = ReShade::GetLinearizedDepth(texcoord).r;
    float2 uv = texcoord;
    float4 screen = tex2D(samplerColor, texcoord);
    float pix_w =  scan_speed * BUFFER_RCP_WIDTH;
    uv.x +=  (anim_rate * pix_w ) - x_col % 1 ;
    float4 scanned = tex2D(ssTarget, uv);


    float4 mask = step(texcoord.x, x_col);

    if(depth >= min_depth)
        color = lerp(screen, scanned, mask);
    else
        color = screen;
}



technique SlitScan <
ui_label="Slit Scan";
> {
    pass p0 {

        VertexShader = FullScreenVS;
        PixelShader = SlitScan;

        RenderTarget = ssTexture;
    }

    pass p1 {

        VertexShader = FullScreenVS;
        PixelShader = SlitScanPost;

    }
}

Splitscreen.fx:
/*------------------.
| :: Description :: |
'-------------------/

	Splitscreen (version 2.0)

	Author: CeeJay.dk
	License: MIT

	About:
	Displays the image before and after it has been modified by effects using a splitscreen


	Ideas for future improvement:
    *

	History:
	(*) Feature (+) Improvement (x) Bugfix (-) Information (!) Compatibility

	Version 1.0
    * Does a splitscreen before/after view

	Version 2.0
    * Ported to Reshade 3.x
    * Added UI settings.
    * Added Diagonal split mode
    - Removed curvy mode. I didn't like how it looked.
    - Threatened other modes to behave or they would be next.
*/

/*------------------.
| :: UI Settings :: |
'------------------*/

#include "ReShadeUI.fxh"

uniform int splitscreen_mode <
    ui_type = "combo";
    ui_label = "Mode";
    ui_tooltip = "Choose a mode";
    //ui_category = "";
    ui_items = 
    "Vertical 50/50 split\0"
    "Vertical 25/50/25 split\0"
    "Angled 50/50 split\0"
    "Angled 25/50/25 split\0"
    "Horizontal 50/50 split\0"
    "Horizontal 25/50/25 split\0"
    "Diagonal split\0"
    ;
> = 0;

/*---------------.
| :: Includes :: |
'---------------*/

#include "ReShade.fxh"


/*-------------------------.
| :: Texture and sampler:: |
'-------------------------*/

texture Before { Width = BUFFER_WIDTH; Height = BUFFER_HEIGHT; };
sampler Before_sampler { Texture = Before; };


/*-------------.
| :: Effect :: |
'-------------*/

float4 PS_Before(float4 pos : SV_Position, float2 texcoord : TEXCOORD) : SV_Target
{
    return tex2D(ReShade::BackBuffer, texcoord);
}

float4 PS_After(float4 pos : SV_Position, float2 texcoord : TEXCOORD) : SV_Target
{
    float4 color; 

    // -- Vertical 50/50 split --
    [branch] if (splitscreen_mode == 0)
        color = (texcoord.x < 0.5 ) ? tex2D(Before_sampler, texcoord) : tex2D(ReShade::BackBuffer, texcoord);

    // -- Vertical 25/50/25 split --
    [branch] if (splitscreen_mode == 1)
    {
        //Calculate the distance from center
        float dist = abs(texcoord.x - 0.5);

        //Further than 1/4 away from center?
        dist = saturate(dist - 0.25);

        color = dist ? tex2D(Before_sampler, texcoord) : tex2D(ReShade::BackBuffer, texcoord);
	}

    // -- Angled 50/50 split --
    [branch] if (splitscreen_mode == 2)
    {
        //Calculate the distance from center
        float dist = ((texcoord.x - 3.0/8.0) + (texcoord.y * 0.25));

        //Further than 1/4 away from center?
        dist = saturate(dist - 0.25);

        color = dist ? tex2D(ReShade::BackBuffer, texcoord) : tex2D(Before_sampler, texcoord);
    }

    // -- Angled 25/50/25 split --
    [branch] if (splitscreen_mode == 3)
    {
        //Calculate the distance from center
        float dist = ((texcoord.x - 3.0/8.0) + (texcoord.y * 0.25));

        dist = abs(dist - 0.25);

        //Further than 1/4 away from center?
        dist = saturate(dist - 0.25);

        color = dist ? tex2D(Before_sampler, texcoord) : tex2D(ReShade::BackBuffer, texcoord);
    }

    // -- Horizontal 50/50 split --
    [branch] if (splitscreen_mode == 4)
	    color =  (texcoord.y < 0.5) ? tex2D(Before_sampler, texcoord) : tex2D(ReShade::BackBuffer, texcoord);

    // -- Horizontal 25/50/25 split --
    [branch] if (splitscreen_mode == 5)
    {
        //Calculate the distance from center
        float dist = abs(texcoord.y - 0.5);

        //Further than 1/4 away from center?
        dist = saturate(dist - 0.25);

        color = dist ? tex2D(Before_sampler, texcoord) : tex2D(ReShade::BackBuffer, texcoord);
    }

    // -- Diagonal split --
    [branch] if (splitscreen_mode == 6)
    {
        //Calculate the distance from center
        float dist = (texcoord.x + texcoord.y);

        //Further than 1/2 away from center?
        //dist = saturate(dist - 1.0);

        color = (dist < 1.0) ? tex2D(Before_sampler, texcoord) : tex2D(ReShade::BackBuffer, texcoord);
    }

    return color;
}


/*-----------------.
| :: Techniques :: |
'-----------------*/

technique Before
{
    pass
    {
        VertexShader = PostProcessVS;
        PixelShader = PS_Before;
        RenderTarget = Before;
    }
}

technique After
{
    pass
    {
        VertexShader = PostProcessVS;
        PixelShader = PS_After;
    }
}

